pub(crate) const TLE_KEY_SESSION_SINGLETON_KEY: u64 = 0;

/// Validate the exact frozen ordered validator roster for a public TLE session.
pub(crate) fn validate_tle_key_session_roster_binding_v1(
    public_state: &TleKeySessionPublicStateV1,
    ordered_roster: &[PeerId],
) -> Result<(), TleReleaseAdapterError> {
    let unique_peers = ordered_roster.iter().collect::<BTreeSet<_>>();
    if ordered_roster.is_empty()
        || unique_peers.len() != ordered_roster.len()
        || usize::from(public_state.committee_size) != ordered_roster.len()
        || public_state.roster_hash
            != crate::beacon::global_threshold_beacon_roster_hash_v1(ordered_roster)
    {
        return Err(TleReleaseAdapterError::TranscriptMismatch);
    }
    Ok(())
}

fn validate_tle_key_session_lifecycle_head_v1(
    ordered_lifecycles: &[TleKeySessionLifecycleV1],
    active_key_session_id: Option<TleKeySessionId>,
) -> Result<(), &'static str> {
    let Some((latest, history)) = ordered_lifecycles.split_last() else {
        return active_key_session_id.map_or(Ok(()), |_| {
            Err("active TLE session pointer exists without a lifecycle head")
        });
    };
    if history
        .iter()
        .any(|lifecycle| !lifecycle.selection_is_closed())
    {
        return Err("a non-latest TLE key-session lifecycle remains open");
    }
    match (latest.selection_is_closed(), active_key_session_id) {
        (false, Some(active_key_session_id)) if active_key_session_id == latest.key_session_id => {
            Ok(())
        }
        (false, _) => Err("the open latest lifecycle head lacks its exact active TLE pointer"),
        (true, None) => Ok(()),
        (true, Some(_)) => Err("a closed latest lifecycle head still has an active TLE pointer"),
    }
}

/// Closed failures for the committed Parliament TLE key-session lifecycle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum TleKeySessionLifecycleErrorV1 {
    /// The requested finalized public key session is absent or invalid.
    #[error("TLE key session is not a valid committed public session")]
    UnknownSession,
    /// A retirement request did not name the currently active key session.
    #[error("TLE key session is not the active session")]
    ActiveSessionMismatch,
    /// A successor was scheduled before its predecessor reached activation.
    #[error("TLE key session already has a pending next-height activation")]
    ActivationPending,
    /// The mandatory next-height activation or configured lifetime overflowed.
    #[error("TLE key-session activation or expiry height overflows")]
    HeightOverflow,
    /// The session is not active, is expired, or exhausted its fresh-ballot budget.
    #[error("TLE key session is unavailable for a fresh ballot")]
    FreshBallotUnavailable,
}

/// Fixed threshold-key lifecycle certificate version.
pub const THRESHOLD_KEY_LIFECYCLE_CERTIFICATE_VERSION_V1: u16 = 1;
/// Maximum canonical public transcript bytes carried by one lifecycle action.
pub const THRESHOLD_KEY_LIFECYCLE_PUBLIC_STATE_MAX_BYTES_V1: usize = 4 * 1024 * 1024;

/// Closed failures while authenticating a threshold-key lifecycle certificate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum ThresholdKeyLifecycleCertificateErrorV1 {
    /// The public certificate shape, version, height, or payload was invalid.
    #[error("threshold-key lifecycle certificate shape is invalid")]
    InvalidShape,
    /// The certificate did not bind the exact current network or validator roster.
    #[error("threshold-key lifecycle certificate context binding is invalid")]
    ContextMismatch,
    /// The exact `2f + 1` signer set was malformed or contained an invalid signature.
    #[error("threshold-key lifecycle certificate quorum authentication failed")]
    InvalidQuorum,
}

/// Build the exact public message authenticated by a threshold-key lifecycle QC.
///
/// The public transcript is represented by its SHA-256 commitment plus exact
/// byte length. Core separately requires canonical decoding and re-encoding
/// before applying an install action.
///
/// # Errors
///
/// Returns a closed error when the payload length cannot be represented.
pub fn threshold_key_lifecycle_certificate_preimage_v1(
    certificate: &iroha_data_model::isi::consensus_keys::ThresholdKeyLifecycleCertificateV1,
) -> Result<Vec<u8>, ThresholdKeyLifecycleCertificateErrorV1> {
    use iroha_data_model::isi::consensus_keys::ThresholdKeyLifecycleActionV1 as Action;
    let action = match certificate.action {
        Action::FinalizeGlobalBeaconKey => 1,
        Action::InstallParliamentTleKey => 2,
        Action::RetireParliamentTleKey => 3,
    };
    let public_state_len = u64::try_from(certificate.public_state.len())
        .map_err(|_| ThresholdKeyLifecycleCertificateErrorV1::InvalidShape)?;
    let public_state_hash = Hash::new(&certificate.public_state);
    let mut preimage = Vec::with_capacity(225);
    preimage.extend_from_slice(b"iroha.consensus.threshold-key-lifecycle.qc.v1\0");
    preimage.extend_from_slice(&certificate.version.to_be_bytes());
    preimage.push(action);
    match certificate.expected_active_session_id {
        None => preimage.push(0),
        Some(session_id) => {
            preimage.push(1);
            preimage.extend_from_slice(&session_id);
        }
    }
    preimage.extend_from_slice(&certificate.effective_height.to_be_bytes());
    preimage.extend_from_slice(certificate.network_id.as_bytes());
    preimage.extend_from_slice(&certificate.roster_hash);
    preimage.extend_from_slice(&certificate.committee_size.to_be_bytes());
    preimage.extend_from_slice(&certificate.quorum.to_be_bytes());
    preimage.extend_from_slice(&certificate.session_id);
    preimage.extend_from_slice(&certificate.transcript_hash);
    preimage.extend_from_slice(&public_state_len.to_be_bytes());
    preimage.extend_from_slice(public_state_hash.as_ref());
    Ok(preimage)
}

/// The committee that authorizes threshold-key lifecycle certificates at `height`: the entry
/// World's lag-2 consensus schedule holds for that height (committed in `R_{height−2}`, identical
/// on every node), in the core's canonical order.
///
/// # Errors
/// The schedule holds no entry for `height`, or the entry's committee is empty.
pub(crate) fn threshold_key_lifecycle_roster_v1(
    world: &impl WorldReadOnly,
    height: u64,
) -> core::result::Result<Vec<PeerId>, String> {
    crate::sumeragi::schedule::scheduled_committee(world, height).map_err(|error| error.to_string())
}

/// Verify an exact current-roster `2f + 1` lifecycle certificate.
///
/// # Errors
///
/// Returns a closed error for a foreign network/roster, wrong height, malformed
/// quorum geometry, duplicate signer index, or invalid validator signature.
pub fn verify_threshold_key_lifecycle_certificate_v1(
    certificate: &iroha_data_model::isi::consensus_keys::ThresholdKeyLifecycleCertificateV1,
    network_id: &NetworkId,
    current_height: u64,
    ordered_roster: &[PeerId],
) -> Result<(), ThresholdKeyLifecycleCertificateErrorV1> {
    use iroha_data_model::isi::consensus_keys::ThresholdKeyLifecycleActionV1 as Action;
    let installing = matches!(
        certificate.action,
        Action::FinalizeGlobalBeaconKey | Action::InstallParliamentTleKey
    );
    if certificate.version != THRESHOLD_KEY_LIFECYCLE_CERTIFICATE_VERSION_V1
        || certificate.effective_height != current_height
        || certificate.session_id == [0; 32]
        || certificate
            .expected_active_session_id
            .is_some_and(|session_id| session_id == [0; 32])
        || certificate.transcript_hash == [0; 32]
        || certificate.public_state.len() > THRESHOLD_KEY_LIFECYCLE_PUBLIC_STATE_MAX_BYTES_V1
        || installing == certificate.public_state.is_empty()
    {
        return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape);
    }
    if installing {
        if certificate.expected_active_session_id == Some(certificate.session_id) {
            return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape);
        }
    } else if certificate.expected_active_session_id != Some(certificate.session_id) {
        return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape);
    }
    let committee_size = u16::try_from(ordered_roster.len())
        .map_err(|_| ThresholdKeyLifecycleCertificateErrorV1::InvalidShape)?;
    if ordered_roster.is_empty() || !(ordered_roster.len() - 1).is_multiple_of(3) {
        return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape);
    }
    let faults = (ordered_roster.len() - 1) / 3;
    let quorum = u16::try_from(faults.saturating_mul(2).saturating_add(1))
        .map_err(|_| ThresholdKeyLifecycleCertificateErrorV1::InvalidShape)?;
    if certificate.network_id != *network_id
        || certificate.roster_hash
            != crate::beacon::global_threshold_beacon_roster_hash_v1(ordered_roster)
        || certificate.committee_size != committee_size
        || certificate.quorum != quorum
    {
        return Err(ThresholdKeyLifecycleCertificateErrorV1::ContextMismatch);
    }
    if certificate.signatures.len() != usize::from(quorum) {
        return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum);
    }
    let preimage = threshold_key_lifecycle_certificate_preimage_v1(certificate)?;
    let mut previous = None;
    for signed in &certificate.signatures {
        if previous.is_some_and(|index| signed.signer_index <= index) {
            return Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum);
        }
        let peer = ordered_roster
            .get(usize::from(signed.signer_index))
            .ok_or(ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum)?;
        signed
            .signature
            .verify(peer.public_key(), &preimage)
            .map_err(|_| ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum)?;
        previous = Some(signed.signer_index);
    }
    Ok(())
}

#[cfg(test)]
mod threshold_key_lifecycle_certificate_tests {
    use super::*;
    use iroha_crypto::{KeyPair, Signature};
    use iroha_data_model::isi::consensus_keys::{
        ThresholdKeyLifecycleActionV1, ThresholdKeyLifecycleCertificateV1,
        ThresholdKeyLifecycleSignatureV1,
    };

    fn network_id(seed: u8) -> NetworkId {
        NetworkId::from_genesis_hash(
            iroha_crypto::HashOf::<iroha_data_model::block::BlockHeader>::from_untyped_unchecked(
                Hash::prehashed([seed; Hash::LENGTH]),
            ),
        )
    }

    fn certified_fixture() -> (
        ThresholdKeyLifecycleCertificateV1,
        Vec<KeyPair>,
        Vec<PeerId>,
    ) {
        let mut validators = (1u8..=4)
            .map(|seed| {
                let key = KeyPair::from_seed(vec![seed; 32], iroha_crypto::Algorithm::BlsNormal);
                (PeerId::new(key.public_key().clone()), key)
            })
            .collect::<Vec<_>>();
        validators.sort_by(|(left, _), (right, _)| left.cmp(right));
        let (roster, keys): (Vec<_>, Vec<_>) = validators.into_iter().unzip();
        let mut certificate = ThresholdKeyLifecycleCertificateV1 {
            version: THRESHOLD_KEY_LIFECYCLE_CERTIFICATE_VERSION_V1,
            action: ThresholdKeyLifecycleActionV1::RetireParliamentTleKey,
            expected_active_session_id: Some([0x41; 32]),
            effective_height: 17,
            network_id: network_id(0x31),
            roster_hash: crate::beacon::global_threshold_beacon_roster_hash_v1(&roster),
            committee_size: 4,
            quorum: 3,
            session_id: [0x41; 32],
            transcript_hash: [0x42; 32],
            public_state: Vec::new(),
            signatures: Vec::new(),
        };
        let preimage = threshold_key_lifecycle_certificate_preimage_v1(&certificate)
            .expect("certificate preimage");
        certificate.signatures = keys
            .iter()
            .take(3)
            .enumerate()
            .map(|(index, key)| ThresholdKeyLifecycleSignatureV1 {
                signer_index: u16::try_from(index).expect("small roster index"),
                signature: Signature::try_new(key.private_key(), &preimage)
                    .expect("sign lifecycle certificate"),
            })
            .collect();
        (certificate, keys, roster)
    }

    #[test]
    fn current_exact_roster_qc_is_required() {
        let (certificate, _keys, roster) = certified_fixture();
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &certificate.network_id,
                certificate.effective_height,
                &roster,
            ),
            Ok(())
        );

        let foreign_roster = (0..4)
            .map(|_| PeerId::new(KeyPair::random().public_key().clone()))
            .collect::<Vec<_>>();
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &certificate.network_id,
                certificate.effective_height,
                &foreign_roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::ContextMismatch)
        );
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &network_id(0x32),
                certificate.effective_height,
                &roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::ContextMismatch)
        );
    }

    #[test]
    fn forged_duplicate_and_replayed_certificates_fail_closed() {
        let (certificate, _keys, roster) = certified_fixture();

        let mut duplicate = certificate.clone();
        duplicate.signatures[1].signer_index = duplicate.signatures[0].signer_index;
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &duplicate,
                &duplicate.network_id,
                duplicate.effective_height,
                &roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum)
        );

        let mut forged = certificate.clone();
        let preimage =
            threshold_key_lifecycle_certificate_preimage_v1(&forged).expect("certificate preimage");
        forged.signatures[0].signature =
            Signature::try_new(KeyPair::random().private_key(), &preimage)
                .expect("forge outsider signature");
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &forged,
                &forged.network_id,
                forged.effective_height,
                &roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidQuorum)
        );

        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &certificate.network_id,
                certificate.effective_height + 1,
                &roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape)
        );

        let mut missing_retirement_predecessor = certificate.clone();
        missing_retirement_predecessor.expected_active_session_id = None;
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &missing_retirement_predecessor,
                &missing_retirement_predecessor.network_id,
                missing_retirement_predecessor.effective_height,
                &roster,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::InvalidShape)
        );
    }

    fn schedule_world(entries: [Vec<PeerId>; 3], first_height: u64) -> World {
        use crate::sumeragi::schedule::{
            ChainParamsRecord, ConsensusSchedule, RetainedConsensusSchedule, ScheduledConfig,
            ScheduledSlot,
        };
        let world = World::new();
        if entries.iter().all(Vec::is_empty) {
            return world;
        }
        let signed = crate::sumeragi::epoch::tests::genesis_fixture(
            iroha_data_model::parameter::system::SumeragiConsensusMode::Permissioned,
            10,
            false,
        );
        let epoch = crate::sumeragi::epoch::authenticated_genesis(&signed)
            .map(|genesis| genesis.into_parts().0)
            .unwrap();
        let roster = epoch
            .committee
            .iter()
            .map(|member| member.validator.clone())
            .collect::<Vec<_>>();
        assert!(entries.iter().all(|entry| entry == &roster));
        let params = ChainParamsRecord::from_parameters(
            &iroha_data_model::parameter::system::SumeragiParameters::default(),
        );
        let graph = ConsensusSchedule::from_owned_entries(
            (first_height..first_height + 3)
                .map(|height| {
                    ScheduledSlot::Ready(ScheduledConfig {
                        height,
                        epoch: epoch.clone(),
                        params,
                    })
                })
                .collect(),
        )
        .unwrap();
        let budget = iroha_allocation::AllocationBudget::new(1024 * 1024);
        let mut schedule = world.consensus_schedule.block();
        *schedule.get_mut() = RetainedConsensusSchedule::admit(&graph, &budget).unwrap();
        schedule.commit();
        world
    }

    fn sign_at_height(
        mut certificate: ThresholdKeyLifecycleCertificateV1,
        keys: &[KeyPair],
        height: u64,
    ) -> ThresholdKeyLifecycleCertificateV1 {
        certificate.effective_height = height;
        certificate.signatures.clear();
        let preimage = threshold_key_lifecycle_certificate_preimage_v1(&certificate)
            .expect("encode lifecycle certificate preimage");
        certificate.signatures = keys
            .iter()
            .take(3)
            .enumerate()
            .map(|(index, key)| ThresholdKeyLifecycleSignatureV1 {
                signer_index: u16::try_from(index).expect("small signer index"),
                signature: Signature::try_new(key.private_key(), &preimage)
                    .expect("sign lifecycle certificate"),
            })
            .collect();
        certificate
    }

    #[test]
    fn scheduled_committee_order_survives_commit_topology_rotation() {
        let (certificate, keys, roster) = certified_fixture();
        let certificate = sign_at_height(certificate, &keys, 2);
        let world = schedule_world([roster.clone(), roster.clone(), roster.clone()], 1);
        let scheduled = threshold_key_lifecycle_roster_v1(&world.view(), 2)
            .expect("the schedule holds height two");
        assert_eq!(scheduled, roster);
        let mut rotated_commit_topology = roster.clone();
        rotated_commit_topology[..3].rotate_left(1);
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &certificate.network_id,
                2,
                &scheduled,
            ),
            Ok(()),
            "leader-role rotation must not change lifecycle signer indices",
        );
        assert_eq!(
            verify_threshold_key_lifecycle_certificate_v1(
                &certificate,
                &certificate.network_id,
                2,
                &rotated_commit_topology,
            ),
            Err(ThresholdKeyLifecycleCertificateErrorV1::ContextMismatch),
            "the mutable role topology is not lifecycle certificate authority",
        );
    }

    #[test]
    fn lifecycle_roster_is_the_scheduled_committee_of_exactly_that_height() {
        let (_, _, roster) = certified_fixture();
        let successor = roster.clone();
        let world = schedule_world([roster.clone(), roster.clone(), successor.clone()], 5);
        assert_eq!(
            threshold_key_lifecycle_roster_v1(&world.view(), 6),
            Ok(roster)
        );
        assert_eq!(
            threshold_key_lifecycle_roster_v1(&world.view(), 7),
            Ok(successor),
            "each retained height preserves its authenticated committee"
        );
        for height in [4, 8] {
            assert!(
                threshold_key_lifecycle_roster_v1(&world.view(), height).is_err(),
                "height {height} is outside the schedule window"
            );
        }
        assert!(threshold_key_lifecycle_roster_v1(&World::new().view(), 1).is_err());
        let empty = schedule_world([Vec::new(), Vec::new(), Vec::new()], 1);
        assert!(threshold_key_lifecycle_roster_v1(&empty.view(), 2).is_err());
    }

    #[test]
    fn next_height_admission_reads_the_committed_schedule() {
        let (certificate, keys, roster) = certified_fixture();
        let network = certificate.network_id;
        let state = State::new_with_chain_and_network_id_for_testing(
            schedule_world([roster.clone(), roster.clone(), roster.clone()], 1),
            crate::kura::Kura::blank_kura_for_testing(),
            crate::query::store::LiveQueryStore::start_test(),
            iroha_model_base::chain::ChainId::from("lifecycle-admission"),
            network,
        );
        let certificate = sign_at_height(certificate, &keys, 2);
        assert!(
            state
                .verify_next_height_threshold_key_lifecycle_certificate_v1(&certificate)
                .is_err(),
            "admission requires a committed parent"
        );
        let header = BlockHeader::new(core::num::NonZeroU64::MIN, None, None, 0, 0);
        let mut block_hashes = state.block_hashes.block();
        block_hashes.push_for_tests(header.hash());
        block_hashes.commit_for_tests();
        assert_eq!(
            state.verify_next_height_threshold_key_lifecycle_certificate_v1(&certificate),
            Ok((header.hash(), roster)),
        );
        let wrong_height = sign_at_height(certificate, &keys, 3);
        assert!(
            state
                .verify_next_height_threshold_key_lifecycle_certificate_v1(&wrong_height)
                .is_err(),
            "a certificate must name the next height"
        );
    }
}

const fn trigger_batch_gas_budget(remaining_block_budget: u64) -> u64 {
    if remaining_block_budget == u64::MAX {
        DEFAULT_TRIGGER_GAS_LIMIT
    } else {
        remaining_block_budget
    }
}
const fn remaining_trigger_batch_gas(batch_gas_limit: u64, batch_gas_used: u64) -> u64 {
    batch_gas_limit.saturating_sub(batch_gas_used)
}
enum ResolvedIvmTriggerProgram {
    Contract(ivm::PreparedContract),
    Generic(crate::smartcontracts::ivm::cache::GenericProgramSummary),
}
pub(crate) fn account_label_is_pii(label: &AccountAlias) -> bool {
    let raw = label.label.as_ref();
    if raw.is_empty() {
        return false;
    }
    let mut digits = 0usize;
    for (idx, ch) in raw.chars().enumerate() {
        if idx == 0 && ch == '+' {
            continue;
        }
        if ch.is_ascii_digit() {
            digits += 1;
            continue;
        }
        if matches!(ch, '-' | '.') {
            continue;
        }
        return false;
    }
    matches!(digits, 8..=15)
}
fn account_ids_in_rekey_record(record: &AccountRekeyRecord) -> impl Iterator<Item = &AccountId> {
    core::iter::once(&record.active_account_id).chain(record.previous_account_ids.iter())
}
pub(crate) fn current_axt_slot_from_block(header: &BlockHeader, slot_length_ms: NonZeroU64) -> u64 {
    header.creation_time_ms / slot_length_ms.get()
}
