// Execution-pool cells reserve their original capacity; other fields start empty.
macro_rules! initial_world_field {
    (sccp_reconciliations, $execution:ident) => {
        sccp_reconciliation_store::Records::try_new_admitted($execution.clone())?
    };
    (sccp_reconciliation_proven, $execution:ident) => {
        sccp_reconciliation_store::Proofs::try_new_admitted($execution.clone())?
    };
    (sccp_pending_refund_amount, $execution:ident) => {
        sccp_reconciliation_store::Refunds::try_new_admitted($execution.clone())?
    };
    (sccp_reconciliation_due, $execution:ident) => {
        sccp_reconciliation_store::Due::try_new_admitted($execution.clone())?
    };
    (sccp_forgery_offences, $execution:ident) => {
        sccp_forgery_custody::OffenceStorage::try_new_admitted($execution.clone())?
    };
    (sccp_forgery_max_generation, $execution:ident) => {
        sccp_forgery_custody::initialize_max(
            None,
            sccp_forgery_custody::MaxGenerationPredecessor::Unchanged,
            $execution,
        )?
    };
    (sccp_light_client_sets, $execution:ident) => {
        LightClientSetStorage::try_new_admitted($execution.clone())?
    };
    (sccp_committee_generations, $execution:ident) => {
        CommitteeStorage::try_new_admitted($execution.clone())?
    };
    (sccp_anchor_open, $execution:ident) => {
        mv::cell::CellInitialization::<RetainedSccpAnchors>::try_reserve($execution)
            .map(|owner| owner.initialize(RetainedSccpAnchors::default(), None))
            .map_err(scalar_cell_custody::admission_error)?
    };
    (sccp_anchor_chunks, $execution:ident) => {
        AnchorStorage::try_new_admitted($execution.clone())?
    };
    (sccp_committee_current, $execution:ident) => {
        scalar_cell_custody::initialize(0, $execution)?
    };
    (sccp_liability_clock, $execution:ident) => {
        scalar_cell_custody::initialize(0, $execution)?
    };
    (sccp_degraded_run, $execution:ident) => {
        mv::cell::CellInitialization::<u32>::try_reserve($execution)
            .map(|owner| owner.initialize(0, None))
            .map_err(scalar_cell_custody::admission_error)?
    };
    (sumeragi_amx_participant, $execution:ident) => {
        crate::sumeragi::amx::empty_participant_cell($execution)?
    };
    (musubi_replication_shortfall_releases, $execution:ident) => {
        scalar_cell_custody::initialize(0, $execution)?
    };
    ($field:ident, $execution:ident) => {
        Default::default()
    };
}
macro_rules! initial_world {
    ($execution:ident; [$($prefix:ident,)*] [$($privacy:ident,)*] [$($suffix:ident,)*]) => {
        WorldData {
            $($prefix: initial_world_field!($prefix, $execution),)*
            $($privacy: initial_world_field!($privacy, $execution),)*
            $($suffix: initial_world_field!($suffix, $execution),)*
            external_event_buf: Default::default(),
        }
    };
}
impl WorldData {
    /// Construct the empty World census from the caller's original execution pool.
    fn try_new_with_execution_budget(
        execution_budget: &iroha_allocation::AllocationBudget,
    ) -> Result<Self, mv::storage::AdmittedStorageError> {
        Ok(with_world_overlay_fields!(initial_world, execution_budget))
    }
}
impl Default for WorldData {
    fn default() -> Self {
        Self::try_new_with_execution_budget(&scalar_cell_custody::default_budget())
            .expect("default execution pool admits the initial World cells")
    }
}

// Quantity storages wrap their child checkpoints; other fields open ordinary ones.
macro_rules! world_field_transaction {
    ($field:expr, sccp_reconciliations) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_reconciliation_proven) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_pending_refund_amount) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_reconciliation_due) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_forgery_offences) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_light_client_sets) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_committee_generations) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, sccp_anchor_chunks) => {
        $field.try_transaction_admitted()?
    };
    ($field:expr, assets) => {
        fastpq_quantity_storage::QuantityStorageTransaction::new($field.transaction())
    };
    ($field:expr, asset_definitions) => {
        fastpq_quantity_storage::QuantityStorageTransaction::new($field.transaction())
    };
    ($field:expr, $ordinary:ident) => {
        $field.transaction()
    };
}

macro_rules! build_world_transaction_from_fields {
    (
        $state:expr,
        $telemetry:expr,
        $axt_lane_config:expr,
        $axt_current_slot:expr,
        $axt_lane_map:expr;
        [$($prefix:ident,)*]
        [$($privacy:ident,)*]
        [$($suffix:ident,)*]
    ) => {{
        let authorization_identities = axt_authorization_identities($state);
        // Split fields through one concrete mutable borrow, without repeatedly
        // borrowing the entire prepaid owner through DerefMut.
        let fields = &mut **$state.fields.as_mut().expect("original World block fields");
        Box::new(WorldTransaction {
            execution_deferral: std::cell::RefCell::default(),
            dataspace_catalog: fields.dataspace_catalog.clone(),
            quantity_mutation_observation: fastpq_quantity_capture::QuantityMutationObservation::default(),
            axt_last_authorization_identities: authorization_identities,
            axt_authorization_transitioned: BTreeSet::new(),
            $($prefix: world_field_transaction!(fields.$prefix, $prefix),)*
            $($privacy: world_field_transaction!(fields.$privacy, $privacy),)*
            $($suffix: world_field_transaction!(fields.$suffix, $suffix),)*
            axt_lane_config: $axt_lane_config,
            axt_current_slot: $axt_current_slot,
            axt_lane_map: $axt_lane_map,
            current_dataspace_id: None,
            retail_fee_now_ms: 0,
            retail_fee_height: 0,
            retail_fee_source_transaction_hash: None,
            retail_fee_assessment: None,
            retail_fee_assessment_marker_pending: false,
            retail_fee_observed_payments: Vec::new(),
            retail_fee_pending_credits: Vec::new(),
            retail_fee_pending_transcripts: Vec::new(),
            retail_fee_exempt_payments: Vec::new(),
            external_event_sink: &mut fields.external_event_buf,
            dataspace_catalog_sink: &mut fields.dataspace_catalog,
            external_event_buf: Vec::new(),
            #[cfg(feature = "telemetry")]
            telemetry: $telemetry,
            internal_event_buf: Vec::new(),
        })
    }};
}
macro_rules! build_world_transaction {
    (
        $state:expr,
        $telemetry:expr,
        $axt_lane_config:expr,
        $axt_current_slot:expr,
        $axt_lane_map:expr
    ) => {
        with_world_overlay_fields!(
            build_world_transaction_from_fields,
            $state,
            $telemetry,
            $axt_lane_config,
            $axt_current_slot,
            $axt_lane_map
        )
    };
}
macro_rules! build_world_view_from_fields {
    (
        $state:expr, $releases:expr;
        [$($prefix:ident,)*]
        [$($_privacy:ident,)*]
        [$($suffix:ident,)*]
    ) => {
        build_world_view_from_fields! {
            $state, $releases, iroha_data_model::nexus::DataSpaceCatalog::default();
            [$($prefix,)*] [$($_privacy,)*] [$($suffix,)*]
        }
    };
    (
        $state:expr, $releases:expr, $catalog:expr;
        [$($prefix:ident,)*]
        [$($_privacy:ident,)*]
        [$($suffix:ident,)*]
    ) => {
        Ok(WorldView {
            dataspace_catalog: $catalog,
            $($prefix: view_acquisition::StateFieldReader::try_read_field(&$state.$prefix, &mut $releases.$prefix)?,)*
            privacy_commitments: view_acquisition::StateFieldReader::try_read_field(&$state.privacy_commitments, &mut $releases.privacy_commitments)?,
            $($suffix: view_acquisition::StateFieldReader::try_read_field(&$state.$suffix, &mut $releases.$suffix)?,)*
        })
    };
}
macro_rules! build_world_view {
    ($state:expr, $releases:expr) => {
        with_world_overlay_fields!(build_world_view_from_fields, $state, $releases)
    };
}
/// Shared immutable generations of the canonical block-hash journal.
/// Opening a view retains its original tree; appending or replacing a tip copies
/// only the edited tree path. Private execution never retains a physical writer.
/// Every concrete tree allocation retains credits from its original finite pool.
pub struct BlockHashes {
    inner: BlockHashStorage,
    budget: iroha_allocation::AllocationBudget,
    released: iroha_allocation::release::ReleaseNotification,
    committed_height: AtomicUsize,
}

#[path = "state/block_hashes_admission.rs"]
