    /// Record that the given asset definition belongs to its domain.
    pub(crate) fn track_asset_definition_domain(&mut self, definition_id: &AssetDefinitionId) {
        let Some(domain_id) = self.asset_definition_domains.get(definition_id).cloned() else {
            return;
        };
        if let Some(definitions) = self.domain_asset_definitions.get_mut(&domain_id) {
            definitions.insert(definition_id.clone());
        } else {
            self.domain_asset_definitions
                .insert(domain_id, BTreeSet::from([definition_id.clone()]));
        }
    }
    /// Drop the domain linkage when the asset definition no longer exists.
    pub(crate) fn untrack_asset_definition_domain(&mut self, definition_id: &AssetDefinitionId) {
        let Some(domain_id) = self.asset_definition_domains.get(definition_id).cloned() else {
            return;
        };
        let remove_domain_index_entry = self
            .domain_asset_definitions
            .get_mut(&domain_id)
            .is_some_and(|definitions| {
                definitions.remove(definition_id);
                definitions.is_empty()
            });
        if remove_domain_index_entry {
            self.domain_asset_definitions.remove(domain_id);
        }
    }
    /// Record asset-definition ownership in the read-side owner index.
    pub(crate) fn track_asset_definition_owner(
        &mut self,
        definition_id: &AssetDefinitionId,
        owner: &AccountId,
    ) {
        if let Some(definitions) = self.asset_definitions_by_owner.get_mut(owner) {
            definitions.insert(definition_id.clone());
        } else {
            self.asset_definitions_by_owner
                .insert(owner.clone(), BTreeSet::from([definition_id.clone()]));
        }
    }
    /// Drop asset-definition ownership from the read-side owner index.
    pub(crate) fn untrack_asset_definition_owner(
        &mut self,
        definition_id: &AssetDefinitionId,
        owner: &AccountId,
    ) {
        let remove_owner_entry =
            self.asset_definitions_by_owner
                .get_mut(owner)
                .is_some_and(|definitions| {
                    definitions.remove(definition_id);
                    definitions.is_empty()
                });
        if remove_owner_entry {
            self.asset_definitions_by_owner.remove(owner.clone());
        }
    }
    /// Insert an asset definition and keep derived indexes consistent.
    /// This generic replacement remains an unowned quantity write.
    pub(crate) fn insert_asset_definition_entry(
        &mut self,
        definition_id: AssetDefinitionId,
        definition: AssetDefinition,
    ) -> Option<AssetDefinition> {
        let owner = definition.owned_by().clone();
        let domain_context = definition.owning_domain().clone();
        let next_transition_height = definition
            .confidential_policy()
            .pending_transition()
            .as_ref()
            .map(|transition| transition.effective_height());
        let previous = self
            .asset_definitions
            .insert(definition_id.clone(), definition);
        self.update_inserted_asset_definition_indexes(
            &definition_id,
            &owner,
            domain_context,
            next_transition_height,
            previous.as_ref(),
        );
        previous
    }

    /// Original registration's absent-to-zero storage port. The canonical caller
    /// derives and installs the new incarnation in this same World transaction.
    fn register_empty_asset_definition_entry(
        &mut self,
        definition_id: AssetDefinitionId,
        definition: AssetDefinition,
    ) -> Result<(), Error> {
        if self.axt_asset_incarnations.get(&definition_id).is_some()
            || self.asset_definition_assets.get(&definition_id).is_some()
            || self.asset_definition_holders.get(&definition_id).is_some()
            || self
                .asset_definition_nonzero_holders
                .get(&definition_id)
                .is_some()
            || self
                .asset_definition_direct_homes
                .get(&definition_id)
                .is_some()
        {
            return Err(Error::InvariantViolation(
                "asset-definition registration must own an absent lifecycle and balance indexes"
                    .into(),
            ));
        }
        let owner = definition.owned_by().clone();
        let domain_context = definition.owning_domain().clone();
        let next_transition_height = definition
            .confidential_policy()
            .pending_transition()
            .as_ref()
            .map(|transition| transition.effective_height());
        self.asset_definitions
            .register_empty_definition(definition_id.clone(), definition)?;
        self.update_inserted_asset_definition_indexes(
            &definition_id,
            &owner,
            domain_context,
            next_transition_height,
            None,
        );
        Ok(())
    }

    /// Preserve the same derived indexes for raw replacement and canonical registration.
    fn update_inserted_asset_definition_indexes(
        &mut self,
        definition_id: &AssetDefinitionId,
        owner: &AccountId,
        domain_context: Option<DomainId>,
        next_transition_height: Option<u64>,
        previous: Option<&AssetDefinition>,
    ) {
        if let Some(previous) = previous {
            if let Some(transition) = previous.confidential_policy().pending_transition() {
                self.untrack_confidential_policy_transition(
                    definition_id,
                    transition.effective_height(),
                );
            }
            self.untrack_asset_definition_domain(definition_id);
            self.untrack_asset_definition_owner(definition_id, previous.owned_by());
        }
        match domain_context {
            Some(domain_id) => {
                self.asset_definition_domains
                    .insert(definition_id.clone(), domain_id);
            }
            None => {
                self.asset_definition_domains.remove(definition_id.clone());
            }
        }
        self.track_asset_definition_domain(definition_id);
        self.track_asset_definition_owner(definition_id, owner);
        if let Some(effective_height) = next_transition_height {
            self.track_confidential_policy_transition(definition_id, effective_height);
        }
    }
    /// Remove an asset definition and keep derived indexes consistent.
    pub(crate) fn remove_asset_definition_entry(
        &mut self,
        definition_id: &AssetDefinitionId,
    ) -> Option<AssetDefinition> {
        if self.asset_definitions.get(definition_id).is_some() {
            self.quantity_mutation_observation.changed();
        }
        let removed = self.remove_quantity_definition(definition_id);
        if let Some(definition) = removed.as_ref() {
            self.axt_asset_incarnations.remove(definition_id.clone());
            // A direct home exists only while its incarnation is live.
            self.asset_definition_direct_homes
                .remove(definition_id.clone());
            if let Some(transition) = definition.confidential_policy().pending_transition() {
                self.untrack_confidential_policy_transition(
                    definition_id,
                    transition.effective_height(),
                );
            }
            self.untrack_asset_definition_domain(definition_id);
            self.untrack_asset_definition_owner(definition_id, definition.owned_by());
            self.asset_definition_domains.remove(definition_id.clone());
        }
        removed
    }
    /// Add one pending confidential-policy transition to the exact due-height index.
    pub(crate) fn track_confidential_policy_transition(
        &mut self,
        definition_id: &AssetDefinitionId,
        effective_height: u64,
    ) {
        let key = (effective_height, definition_id.clone());
        if self
            .confidential_policy_transition_index
            .insert(key, ())
            .is_some()
        {
            return;
        }
        let count = self
            .confidential_policy_transition_counts
            .get(&effective_height)
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .expect("confidential-policy transition count must not overflow");
        self.confidential_policy_transition_counts
            .insert(effective_height, count);
    }
    /// Remove one pending confidential-policy transition from the exact due-height index.
    pub(crate) fn untrack_confidential_policy_transition(
        &mut self,
        definition_id: &AssetDefinitionId,
        effective_height: u64,
    ) {
        if self
            .confidential_policy_transition_index
            .remove((effective_height, definition_id.clone()))
            .is_none()
        {
            return;
        }
        let count = self
            .confidential_policy_transition_counts
            .get(&effective_height)
            .copied()
            .expect("tracked confidential-policy transition must have an exact height count");
        if count == 1 {
            self.confidential_policy_transition_counts
                .remove(effective_height);
        } else {
            self.confidential_policy_transition_counts
                .insert(effective_height, count - 1);
        }
    }
    /// Return the exact number of pending confidential-policy transitions at a height.
    pub(crate) fn confidential_policy_transition_count(&self, effective_height: u64) -> u32 {
        self.confidential_policy_transition_counts
            .get(&effective_height)
            .copied()
            .unwrap_or(0)
    }
    /// Move an existing asset definition id between owner index buckets.
    pub(crate) fn replace_asset_definition_owner_index(
        &mut self,
        definition_id: &AssetDefinitionId,
        previous_owner: &AccountId,
        next_owner: &AccountId,
    ) {
        if previous_owner == next_owner {
            self.track_asset_definition_owner(definition_id, next_owner);
            return;
        }
        self.untrack_asset_definition_owner(definition_id, previous_owner);
        self.track_asset_definition_owner(definition_id, next_owner);
    }
    /// Record that the given account now holds at least one balance partition of the definition.
    pub(crate) fn track_asset_holder(&mut self, asset_id: &AssetId) {
        insert_set_index_member(
            &mut self.asset_definition_holders,
            asset_id.definition(),
            asset_id.account(),
        );
        insert_set_index_member(
            &mut self.asset_definition_assets,
            asset_id.definition(),
            asset_id,
        );
        insert_set_index_member(&mut self.assets_by_account, asset_id.account(), asset_id);
        if let Some(domain_id) = self
            .asset_definition_domains
            .get(asset_id.definition())
            .cloned()
        {
            insert_set_index_member(&mut self.assets_by_domain, &domain_id, asset_id);
        }
    }
    /// Record that the given account has a non-zero balance for the definition.
    pub(crate) fn track_nonzero_asset_holder(&mut self, asset_id: &AssetId) {
        insert_set_index_member(
            &mut self.asset_definition_nonzero_holders,
            asset_id.definition(),
            asset_id.account(),
        );
    }
    /// Drop a non-zero holder entry when no remaining partition for that account is non-zero.
    pub(crate) fn refresh_nonzero_asset_holder(&mut self, asset_id: &AssetId) {
        let has_nonzero_for_definition =
            self.assets
                .range::<dyn AsAssetIdAccountDefinitionCompare>(
                    AssetByAccountDefinitionBounds::new(asset_id.account(), asset_id.definition()),
                )
                .any(|(_, value)| !value.as_ref().is_zero());
        if has_nonzero_for_definition {
            self.track_nonzero_asset_holder(asset_id);
            return;
        }
        remove_set_index_member(
            &mut self.asset_definition_nonzero_holders,
            asset_id.definition(),
            asset_id.account(),
        );
    }
    /// Drop asset-id linkage, then remove the holder linkage when the account no longer has any
    /// remaining balance partition for the definition.
    pub(crate) fn untrack_asset_holder_if_empty(&mut self, asset_id: &AssetId) {
        remove_set_index_member(
            &mut self.asset_definition_assets,
            asset_id.definition(),
            asset_id,
        );
        remove_set_index_member(&mut self.assets_by_account, asset_id.account(), asset_id);
        if let Some(domain_id) = self
            .asset_definition_domains
            .get(asset_id.definition())
            .cloned()
        {
            remove_set_index_member(&mut self.assets_by_domain, &domain_id, asset_id);
        }
        let has_remaining_for_definition =
            self.assets
                .range::<dyn AsAssetIdAccountDefinitionCompare>(
                    AssetByAccountDefinitionBounds::new(asset_id.account(), asset_id.definition()),
                )
                .next()
                .is_some();
        if has_remaining_for_definition {
            return;
        }
        remove_set_index_member(
            &mut self.asset_definition_holders,
            asset_id.definition(),
            asset_id.account(),
        );
    }
    /// Remove an asset entry and any attached asset metadata.
    pub(crate) fn remove_asset_and_metadata(&mut self, asset_id: &AssetId) -> Option<AssetValue> {
        if self.assets.get(asset_id).is_some() {
            self.quantity_mutation_observation.changed();
        }
        let removed = self.remove_quantity_balance(asset_id);
        self.asset_metadata.remove(asset_id.clone());
        if removed.is_some() {
            self.refresh_nonzero_asset_holder(asset_id);
            self.untrack_asset_holder_if_empty(asset_id);
        }
        removed
    }
    /// Remove an asset entry, metadata and decrement the owning definition's tracked total.
    ///
    /// # Errors
    /// Returns an error when the persisted definition total cannot be decremented.
    #[cfg(test)]
    pub(crate) fn remove_asset_and_metadata_with_total(
        &mut self,
        asset_id: &AssetId,
    ) -> Result<Option<AssetValue>, Error> {
        let Some(value) = self.assets.get(asset_id).cloned() else {
            self.asset_metadata.remove(asset_id.clone());
            return Ok(None);
        };
        let amount = value.clone().into_inner();
        self.decrease_asset_total_amount(asset_id.definition(), &amount)?;
        Ok(self.remove_asset_and_metadata(asset_id))
    }
    /// Record domain ownership in the read-side owner index.
    pub(crate) fn track_domain_owner(&mut self, domain_id: &DomainId, owner: &AccountId) {
        if let Some(domains) = self.domains_by_owner.get_mut(owner) {
            domains.insert(domain_id.clone());
        } else {
            self.domains_by_owner
                .insert(owner.clone(), BTreeSet::from([domain_id.clone()]));
        }
    }
    /// Drop domain ownership from the read-side owner index.
    pub(crate) fn untrack_domain_owner(&mut self, domain_id: &DomainId, owner: &AccountId) {
        let remove_owner_entry = self.domains_by_owner.get_mut(owner).is_some_and(|domains| {
            domains.remove(domain_id);
            domains.is_empty()
        });
        if remove_owner_entry {
            self.domains_by_owner.remove(owner.clone());
        }
    }
    /// Insert a domain and keep the owner index consistent.
    pub(crate) fn insert_domain_entry(
        &mut self,
        domain_id: DomainId,
        domain: Domain,
    ) -> Option<Domain> {
        let owner = domain.owned_by().clone();
        let previous = self.domains.insert(domain_id.clone(), domain);
        if let Some(previous) = previous.as_ref() {
            self.untrack_domain_owner(&domain_id, previous.owned_by());
        }
        self.track_domain_owner(&domain_id, &owner);
        previous
    }
    /// Remove a domain and keep the owner index consistent.
    pub(crate) fn remove_domain_entry(&mut self, domain_id: &DomainId) -> Option<Domain> {
        let removed = self.domains.remove(domain_id.clone());
        if let Some(domain) = removed.as_ref() {
            self.untrack_domain_owner(domain_id, domain.owned_by());
        }
        removed
    }
    /// Move an existing domain id between owner index buckets.
    pub(crate) fn replace_domain_owner_index(
        &mut self,
        domain_id: &DomainId,
        previous_owner: &AccountId,
        next_owner: &AccountId,
    ) {
        if previous_owner == next_owner {
            self.track_domain_owner(domain_id, next_owner);
            return;
        }
        self.untrack_domain_owner(domain_id, previous_owner);
        self.track_domain_owner(domain_id, next_owner);
    }
