/// Lifecycle status of a governance proposal.
#[derive(norito::NoritoSchema)]
#[norito_schema(name = "iroha_core::state::GovernanceProposalStatus")]
#[derive(Clone, Copy, Debug, PartialEq, Eq, NoritoSerialize, NoritoDeserialize)]
pub enum GovernanceProposalStatus {
    /// Proposal has been submitted and its latest attempt is active or certified.
    Proposed,
    /// The latest Parliament attempt rejected the proposal.
    Rejected,
    /// Proposal has been enacted and applied.
    Enacted,
    /// The certified compare-and-set predecessor was no longer current at execution.
    Superseded,
    /// The certified proposal effect failed atomically during automatic execution.
    ExecutionFailed,
}
impl GovernanceProposalStatus {
    /// Project the canonical proposal status from the latest Parliament attempt.
    #[must_use]
    pub(crate) const fn from_attempt_status(
        status: iroha_data_model::governance::types::GovernanceAttemptStatusV1,
    ) -> Self {
        use iroha_data_model::governance::types::GovernanceAttemptStatusV1 as Attempt;

        match status {
            Attempt::Active | Attempt::Certified => Self::Proposed,
            Attempt::Rejected => Self::Rejected,
            Attempt::Enacted => Self::Enacted,
            Attempt::Superseded => Self::Superseded,
            Attempt::ExecutionFailed => Self::ExecutionFailed,
        }
    }
}
impl json::FastJsonWrite for GovernanceProposalStatus {
    fn write_json(&self, out: &mut String) {
        let label = match self {
            GovernanceProposalStatus::Proposed => "Proposed",
            GovernanceProposalStatus::Rejected => "Rejected",
            GovernanceProposalStatus::Enacted => "Enacted",
            GovernanceProposalStatus::Superseded => "Superseded",
            GovernanceProposalStatus::ExecutionFailed => "ExecutionFailed",
        };
        json::write_json_string(label, out);
    }
}
impl json::JsonDeserialize for GovernanceProposalStatus {
    fn json_deserialize(parser: &mut json::Parser<'_>) -> Result<Self, json::Error> {
        let value = parser.parse_string()?;
        match value.as_str() {
            "Proposed" => Ok(GovernanceProposalStatus::Proposed),
            "Rejected" => Ok(GovernanceProposalStatus::Rejected),
            "Enacted" => Ok(GovernanceProposalStatus::Enacted),
            "Superseded" => Ok(GovernanceProposalStatus::Superseded),
            "ExecutionFailed" => Ok(GovernanceProposalStatus::ExecutionFailed),
            other => Err(json::Error::UnknownField {
                field: other.to_owned(),
            }),
        }
    }
}
/// Absolute deadline height for an oracle change `stage` started at `started_at`, or `None`
/// when the governance SLA for that stage is disabled.
pub(crate) fn oracle_stage_deadline(
    stage: iroha_data_model::oracle::OracleChangeStage,
    cfg: &iroha_config::parameters::actual::OracleGovernance,
    started_at: u64,
) -> Option<u64> {
    let sla = match stage {
        iroha_data_model::oracle::OracleChangeStage::Intake => cfg.intake_sla_blocks,
        iroha_data_model::oracle::OracleChangeStage::RulesCommittee => cfg.rules_sla_blocks,
        iroha_data_model::oracle::OracleChangeStage::CopReview => cfg.cop_sla_blocks,
        iroha_data_model::oracle::OracleChangeStage::TechnicalAudit => cfg.technical_sla_blocks,
        iroha_data_model::oracle::OracleChangeStage::PolicyJury => cfg.policy_jury_sla_blocks,
        iroha_data_model::oracle::OracleChangeStage::Enactment => cfg.enact_sla_blocks,
    };
    if sla == 0 {
        None
    } else {
        Some(started_at.saturating_add(sla))
    }
}
/// Stage records for a new oracle change: intake starts at `created_at`; later stages wait.
pub(crate) fn seed_oracle_change_stages(
    created_at: u64,
    cfg: &iroha_config::parameters::actual::OracleGovernance,
) -> Vec<iroha_data_model::oracle::OracleChangeStageRecord> {
    use iroha_data_model::oracle::OracleChangeStage as Stage;
    let mut stages = Vec::with_capacity(6);
    stages.push(iroha_data_model::oracle::OracleChangeStageRecord {
        stage: Stage::Intake,
        approvals: BTreeSet::new(),
        rejections: BTreeSet::new(),
        evidence: Vec::new(),
        started_at: Some(created_at),
        deadline: oracle_stage_deadline(Stage::Intake, cfg, created_at),
        completed_at: None,
        failure: None,
    });
    for stage in [
        Stage::RulesCommittee,
        Stage::CopReview,
        Stage::TechnicalAudit,
        Stage::PolicyJury,
        Stage::Enactment,
    ] {
        stages.push(iroha_data_model::oracle::OracleChangeStageRecord {
            stage,
            approvals: BTreeSet::new(),
            rejections: BTreeSet::new(),
            evidence: Vec::new(),
            started_at: None,
            deadline: None,
            completed_at: None,
            failure: None,
        });
    }
    stages
}
fn update_oracle_change_pipeline(
    wtx: &mut WorldTransaction<'_, '_>,
    now_h: u64,
    cfg: &iroha_config::parameters::actual::OracleGovernance,
) {
    use iroha_data_model::{
        events::data::oracle::{OracleChangeStageUpdated, OracleEvent},
        oracle::{OracleChangeStage, OracleChangeStageFailure, OracleChangeStatus},
    };
    let changes: Vec<_> = wtx
        .oracle_changes
        .iter()
        .map(|(id, rec)| (*id, rec.clone()))
        .collect();
    for (change_id, mut rec) in changes {
        if rec.status.is_terminal() {
            continue;
        }
        if rec.stages.is_empty() {
            rec.stages = seed_oracle_change_stages(rec.created_at, cfg);
        }
        if let Some(intake) = rec
            .stages
            .iter_mut()
            .find(|stage| stage.stage == OracleChangeStage::Intake)
        {
            if intake.started_at.is_none() {
                intake.started_at = Some(now_h);
                intake.deadline = oracle_stage_deadline(OracleChangeStage::Intake, cfg, now_h);
            }
        }
        let mut emit_update = false;
        if let Some(stage) = rec.current_stage_mut() {
            if stage.failure.is_none() && stage.is_pending() {
                if let Some(deadline) = stage.deadline {
                    if now_h > deadline {
                        stage.failure = Some(OracleChangeStageFailure::DeadlineMissed);
                        rec.status = OracleChangeStatus::Failed(
                            iroha_data_model::oracle::OracleChangeFailure {
                                stage: stage.stage,
                                reason: OracleChangeStageFailure::DeadlineMissed,
                                at: now_h,
                            },
                        );
                        emit_update = true;
                    }
                }
            }
        }
        if emit_update {
            let (stage_id, approvals, rejections, evidence_hashes) = rec.current_stage().map_or(
                (OracleChangeStage::Enactment, 0, 0, Vec::new()),
                |stage| {
                    (
                        stage.stage,
                        u32::try_from(stage.approvals.len()).unwrap_or(u32::MAX),
                        u32::try_from(stage.rejections.len()).unwrap_or(u32::MAX),
                        stage.evidence.clone(),
                    )
                },
            );
            wtx.emit_events(Some(OracleEvent::ChangeStageUpdated(
                OracleChangeStageUpdated {
                    change_id,
                    stage: stage_id,
                    status: rec.status.clone(),
                    approvals,
                    rejections,
                    evidence_hashes,
                },
            )));
        }
        wtx.oracle_changes.insert(change_id, rec);
    }
}
/// Referendum record for governance (status and schedule)
#[derive(norito::NoritoSchema)]
#[norito_schema(name = "iroha_core::state::GovernanceReferendumRecord")]
#[derive(
    Clone, Debug, PartialEq, Eq, JsonSerialize, JsonDeserialize, NoritoSerialize, NoritoDeserialize,
)]
#[norito(deny_unknown_fields)]
pub struct GovernanceReferendumRecord {
    /// Enactment window start height (inclusive)
    pub h_start: u64,
    /// Enactment window end height (inclusive)
    pub h_end: u64,
    /// Current referendum status
    pub status: GovernanceReferendumStatus,
    /// Voting mode for this referendum
    pub mode: GovernanceReferendumMode,
    /// Required immutable public-ballot context, frozen by creation/bootstrap before voting.
    pub plain_context: iroha_data_model::governance::conviction::PlainVotingContextV1,
    /// Required lifecycle/result binding, retained independently of released voting locks.
    pub plain_result: iroha_data_model::governance::conviction::PlainVotingResultV1,
}
impl GovernanceReferendumRecord {
    /// Validate the mode/context pairing without deriving any policy from current configuration.
    ///
    /// # Errors
    /// Rejects missing, mismatched or arithmetically invalid frozen public-ballot context.
    pub fn validate_context(&self) -> Result<(), String> {
        use iroha_data_model::governance::conviction::{PlainVotingContextV1, PlainVotingResultV1};
        match (
            &self.mode,
            &self.plain_context,
            &self.plain_result,
            self.status,
        ) {
            (
                GovernanceReferendumMode::Plain,
                PlainVotingContextV1::Conviction(policy),
                PlainVotingResultV1::Pending,
                GovernanceReferendumStatus::Proposed | GovernanceReferendumStatus::Open,
            ) => policy.validate().map_err(|error| error.to_string()),
            (
                GovernanceReferendumMode::Plain,
                PlainVotingContextV1::Conviction(policy),
                PlainVotingResultV1::Decided(result),
                GovernanceReferendumStatus::Closed,
            ) => {
                let expected = policy
                    .decide([result.approve, result.reject, result.abstain])
                    .map_err(|error| error.to_string())?;
                if result != &expected {
                    return Err("closed PLAIN decision does not match its frozen policy".into());
                }
                Ok(())
            }
            (
                GovernanceReferendumMode::Zk,
                PlainVotingContextV1::NotApplicable,
                PlainVotingResultV1::NotApplicable,
                _,
            ) => Ok(()),
            _ => Err(
                "referendum mode/status does not match its required frozen PLAIN context/result"
                    .into(),
            ),
        }
    }

    /// Borrow the exact public-ballot policy retained by this referendum.
    ///
    /// # Errors
    /// Rejects a ZK referendum or an invalid/mismatched frozen context.
    pub fn plain_policy(
        &self,
    ) -> Result<&iroha_data_model::governance::conviction::PlainConvictionPolicyV1, String> {
        self.validate_context()?;
        match &self.plain_context {
            iroha_data_model::governance::conviction::PlainVotingContextV1::Conviction(policy) => {
                Ok(policy)
            }
            _ => Err("referendum has no public conviction policy".into()),
        }
    }
}
/// Project an open public corpus or read its immutable closed result.
///
/// # Errors
/// Rejects invalid context/result, malformed custody/owner bindings, corpus or arithmetic bounds.
pub fn plain_governance_tally(
    referendum: &GovernanceReferendumRecord,
    locks: Option<&GovernanceLocksForReferendum>,
    evaluated_height: u64,
) -> Result<[u128; 3], String> {
    let policy = referendum.plain_policy()?;
    if let iroha_data_model::governance::conviction::PlainVotingResultV1::Decided(result) =
        &referendum.plain_result
    {
        return Ok([result.approve, result.reject, result.abstain]);
    }
    locks.map_or(Ok([0; 3]), |locks| {
        crate::smartcontracts::isi::world::isi::plain_governance_tally_v1(
            locks,
            None,
            Some(evaluated_height.min(referendum.h_end)),
            policy,
        )
        .map_err(|error| error.to_string())
    })
}
