    fn prune_axt_replay_ledger(&mut self, current_slot: u64, retention_slots: u64) {
        let expired: Vec<_> = self
            .world
            .axt_replay_ledger
            .iter()
            .filter(|(_, record)| record.is_expired(current_slot, retention_slots))
            .map(|(key, _)| *key)
            .collect();
        for key in expired {
            self.world.axt_replay_ledger.remove(key);
        }
    }
