    fn seed_consensus_key(
        world_block: &mut WorldBlock<'_>,
        peer: &PeerId,
        status: ConsensusKeyStatus,
        activation_height: u64,
    ) {
        seed_consensus_key_with_role(
            world_block,
            peer,
            ConsensusKeyRole::Validator,
            status,
            activation_height,
        );
    }
    fn seed_consensus_key_with_role(
        world_block: &mut WorldBlock<'_>,
        peer: &PeerId,
        role: ConsensusKeyRole,
        status: ConsensusKeyStatus,
        activation_height: u64,
    ) {
        let ident = match role {
            ConsensusKeyRole::Validator => derive_validator_key_id(peer.public_key()),
            ConsensusKeyRole::Committee => derive_committee_key_id(peer.public_key()),
            ConsensusKeyRole::Endorsement => {
                ConsensusKeyId::new(ConsensusKeyRole::Endorsement, "test-endorsement-key")
            }
        };
        let mut record = ConsensusKeyRecord {
            id: ident,
            public_key: peer.public_key().clone(),
            pop: None,
            activation_height,
            expiry_height: None,
            replaces: None,
            status,
        };
        if matches!(record.status, ConsensusKeyStatus::Disabled) {
            record.expiry_height = Some(activation_height);
        }
        world_block
            .consensus_keys
            .insert(record.id.clone(), record.clone());
        let pk = record.public_key.to_string();
        let mut by_pk = world_block
            .consensus_keys_by_pk
            .get(&pk)
            .cloned()
            .unwrap_or_default();
        if !by_pk.contains(&record.id) {
            by_pk.push(record.id.clone());
            world_block.consensus_keys_by_pk.insert(pk, by_pk);
        }
    }
    fn lane_validator_record(
        lane_id: LaneId,
        validator: &DMAccountId,
        peer_id: PeerId,
        stake: u32,
        status: PublicLaneValidatorStatus,
    ) -> PublicLaneValidatorRecord {
        let activation_height = match &status {
            PublicLaneValidatorStatus::PendingActivation(height) => *height,
            _ => 0,
        };
        let deactivation_height = match &status {
            PublicLaneValidatorStatus::Exiting(_)
            | PublicLaneValidatorStatus::Exited
            | PublicLaneValidatorStatus::Slashed(_) => Some(2),
            PublicLaneValidatorStatus::PendingActivation(_) | PublicLaneValidatorStatus::Active => {
                None
            }
        };
        PublicLaneValidatorRecord {
            lane_id,
            validator: validator.clone(),
            peer_id,
            stake_account: validator.clone(),
            total_stake: iroha_primitives::numeric::Quantity::from(stake),
            self_stake: iroha_primitives::numeric::Quantity::from(stake),
            metadata: Metadata::default(),
            status,
            activation_height,
            election_exit_height: deactivation_height,
            deactivation_height,
        }
    }
    fn active_lane_validator_record(
        lane_id: LaneId,
        validator: &DMAccountId,
        peer_id: PeerId,
        stake: u32,
    ) -> PublicLaneValidatorRecord {
        lane_validator_record(
            lane_id,
            validator,
            peer_id,
            stake,
            PublicLaneValidatorStatus::Active,
        )
    }
    fn seed_active_public_lane_validator(
        world_block: &mut WorldBlock<'_>,
        keypair: &KeyPair,
        lane_id: LaneId,
        stake: u32,
    ) -> PeerId {
        let peer = PeerId::from(keypair.public_key().clone());
        let validator = DMAccountId::of(keypair.public_key().clone());
        let _ = world_block.peers.get_mut().push(peer.clone());
        seed_consensus_key(world_block, &peer, ConsensusKeyStatus::Active, 0);
        world_block.public_lane_validators.insert(
            (lane_id, validator.clone()),
            active_lane_validator_record(lane_id, &validator, peer.clone(), stake),
        );
        peer
    }
    #[test]
    fn consensus_key_pop_lookup_uses_index_and_fallback() {
        let keypair = crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal);
        let peer_id = PeerId::new(keypair.public_key().clone());
        let pop =
            iroha_crypto::bls_normal_pop_prove(keypair.private_key()).expect("pop for test key");
        let id = derive_validator_key_id(peer_id.public_key());
        let record = ConsensusKeyRecord {
            id: id.clone(),
            public_key: peer_id.public_key().clone(),
            pop: Some(pop.clone()),
            activation_height: 0,
            expiry_height: None,
            replaces: None,
            status: ConsensusKeyStatus::Active,
        };
        let indexed_world = World::default();
        {
            let mut block = indexed_world.block();
            block.consensus_keys.insert(id.clone(), record.clone());
            block
                .consensus_keys_by_pk
                .insert(peer_id.public_key().to_string(), vec![id.clone()]);
            block.commit();
        }
        let indexed_view = indexed_world.view();
        let indexed_pop = consensus_key_pop_for_public_key(&indexed_view, peer_id.public_key());
        assert_eq!(indexed_pop.as_deref(), Some(pop.as_slice()));
        let fallback_world = World::default();
        {
            let mut block = fallback_world.block();
            block.consensus_keys.insert(id, record);
            block.commit();
        }
        let fallback_view = fallback_world.view();
        let fallback_pop = consensus_key_pop_for_public_key(&fallback_view, peer_id.public_key());
        assert_eq!(fallback_pop.as_deref(), Some(pop.as_slice()));
    }
