    #[test]
    fn nexus_lane_active_for_authority_requires_dataspace_match() {
        let private_dataspace = DataSpaceId::new(9);
        let private_lane = LaneId::new(4);
        let lane_catalog = LaneCatalog::new(
            NonZeroU32::new(5).expect("nonzero lane count"),
            vec![
                LaneConfig::default(),
                LaneConfig {
                    id: private_lane,
                    dataspace_id: private_dataspace,
                    alias: "private-lane".to_owned(),
                    ..LaneConfig::default()
                },
            ],
        )
        .expect("private lane catalog");
        let dataspace_catalog = DataSpaceCatalog::new(vec![
            DataSpaceMetadata::default(),
            DataSpaceMetadata {
                id: private_dataspace,
                alias: "private".to_owned(),
                ..DataSpaceMetadata::default()
            },
        ])
        .expect("private dataspace catalog");
        let mut nexus = iroha_config::parameters::actual::Nexus {
            lane_catalog,
            dataspace_catalog,
            ..Default::default()
        };
        nexus.lane_config = DerivedLaneConfig::from_catalog(&nexus.lane_catalog);
        assert!(
            nexus_lane_active_for_authority(private_lane, private_dataspace, &nexus, 7),
            "matching non-default lane/dataspace binding should remain active"
        );
        assert!(
            !nexus_lane_active_for_authority(private_lane, DataSpaceId::UNIVERSAL, &nexus, 7),
            "forged dataspace context must not make an active lane authoritative"
        );
        assert_eq!(
            nexus_active_lane_dataspace_at_height(private_lane, &nexus, 7),
            Some(private_dataspace),
            "public active-lane lookup should still return the catalog-owned dataspace"
        );
        let mut missing_dataspace = nexus.clone();
        missing_dataspace.dataspace_catalog =
            DataSpaceCatalog::new(vec![DataSpaceMetadata::default()])
                .expect("universal-only dataspace catalog");
        assert!(
            !nexus_lane_active_for_authority(
                private_lane,
                private_dataspace,
                &missing_dataspace,
                7
            ),
            "lanes bound to removed dataspaces must not remain authoritative"
        );
        assert_eq!(
            nexus_active_lane_dataspace_at_height(private_lane, &missing_dataspace, 7),
            None,
            "public active-lane lookup must also require the dataspace catalog entry"
        );
    }
    #[test]
    fn validator_lane_ids_for_peers_ignore_inactive_public_lane_records() {
        let world = World::default();
        let active_kp = crate::state::checked_keypair();
        let slashed_kp = crate::state::checked_keypair();
        let exiting_kp = crate::state::checked_keypair();
        let mismatched_kp = crate::state::checked_keypair();
        let active_peer = PeerId::from(active_kp.public_key().clone());
        let slashed_peer = PeerId::from(slashed_kp.public_key().clone());
        let exiting_peer = PeerId::from(exiting_kp.public_key().clone());
        let mismatched_peer = PeerId::from(mismatched_kp.public_key().clone());
        let active_validator = DMAccountId::of(active_kp.public_key().clone());
        let slashed_validator = DMAccountId::of(slashed_kp.public_key().clone());
        let exiting_validator = DMAccountId::of(exiting_kp.public_key().clone());
        let mismatched_validator = DMAccountId::of(mismatched_kp.public_key().clone());
        {
            let mut block = world.public_lane_validators.block();
            block.insert(
                (LaneId::new(1), active_validator.clone()),
                active_lane_validator_record(
                    LaneId::new(1),
                    &active_validator,
                    active_peer.clone(),
                    10_u32,
                ),
            );
            block.insert(
                (LaneId::new(2), slashed_validator.clone()),
                lane_validator_record(
                    LaneId::new(2),
                    &slashed_validator,
                    slashed_peer.clone(),
                    20_u32,
                    PublicLaneValidatorStatus::Slashed(Hash::new(b"test slash")),
                ),
            );
            block.insert(
                (LaneId::new(3), exiting_validator.clone()),
                lane_validator_record(
                    LaneId::new(3),
                    &exiting_validator,
                    exiting_peer.clone(),
                    30_u32,
                    PublicLaneValidatorStatus::Exiting(7),
                ),
            );
            block.insert(
                (LaneId::new(4), mismatched_validator.clone()),
                active_lane_validator_record(
                    LaneId::new(5),
                    &mismatched_validator,
                    mismatched_peer.clone(),
                    40_u32,
                ),
            );
            block.commit();
        }
        let view = world.view();
        assert_eq!(
            validator_lane_ids_for_peers(
                &view,
                [&active_peer, &slashed_peer, &exiting_peer, &mismatched_peer],
                2,
            ),
            BTreeSet::from([LaneId::new(1)]),
            "only active validator records with matching storage-key and embedded lanes should influence live lane scope"
        );
        assert!(
            validator_lane_ids_for_peer(&view, &slashed_peer, 2).is_empty(),
            "inactive single-peer records must not retain stale lane scope"
        );
        assert!(
            validator_lane_ids_for_peer(&view, &mismatched_peer, 2).is_empty(),
            "mismatched key/record lane ids must not retain stale lane scope"
        );
    }
    #[test]
    fn state_block_due_activation_ignores_mismatched_public_lane_validator_rows() {
        let kura = crate::kura::Kura::blank_kura_for_testing();
        let query = crate::query::store::LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), std::sync::Arc::clone(&kura), query);
        let valid_kp = crate::state::checked_keypair();
        let mismatched_kp = crate::state::checked_keypair();
        let valid_validator = DMAccountId::of(valid_kp.public_key().clone());
        let mismatched_validator = DMAccountId::of(mismatched_kp.public_key().clone());
        let valid_lane = LaneId::SINGLE;
        let mismatched_key_lane = LaneId::new(12);
        let mismatched_record_lane = LaneId::new(13);
        {
            // Inject the malformed row after validated state construction so this
            // test reaches the activation filter rather than snapshot admission.
            let mut block = state.world.public_lane_validators.block();
            block.insert(
                (valid_lane, valid_validator.clone()),
                lane_validator_record(
                    valid_lane,
                    &valid_validator,
                    PeerId::from(valid_kp.public_key().clone()),
                    10_u32,
                    PublicLaneValidatorStatus::PendingActivation(9),
                ),
            );
            block.insert(
                (mismatched_key_lane, mismatched_validator.clone()),
                lane_validator_record(
                    mismatched_record_lane,
                    &mismatched_validator,
                    PeerId::from(mismatched_kp.public_key().clone()),
                    20_u32,
                    PublicLaneValidatorStatus::PendingActivation(9),
                ),
            );
            block.commit();
        }
        let header = BlockHeader::new(
            core::num::NonZeroU64::new(9).expect("non-zero height"),
            None,
            None,
            0,
            0,
        );
        let mut state_block = state.block(header);
        state_block.activate_due_public_lane_validators(3);
        let valid = state_block
            .world
            .public_lane_validators
            .get(&(valid_lane, valid_validator))
            .expect("valid pending validator remains present");
        assert!(matches!(valid.status, PublicLaneValidatorStatus::Active));
        assert_eq!(valid.activation_height, 9);
        assert_eq!(valid.deactivation_height, None);
        let mismatched = state_block
            .world
            .public_lane_validators
            .get(&(mismatched_key_lane, mismatched_validator))
            .expect("mismatched pending validator remains present");
        assert!(
            matches!(
                mismatched.status,
                PublicLaneValidatorStatus::PendingActivation(9)
            ),
            "mismatched key/record rows must not auto-promote to Active"
        );
        assert_eq!(mismatched.activation_height, 9);
        assert_eq!(mismatched.deactivation_height, None);
    }
