    /// Creates a [`World`] with these [`Domain`]s and [`Peer`]s.
    pub fn with<D, A, Ad>(domains: D, accounts: A, asset_definitions: Ad) -> Self
    where
        D: IntoIterator<Item = Domain>,
        A: IntoIterator<Item = Account>,
        Ad: IntoIterator<Item = AssetDefinition>,
    {
        Self::with_assets(domains, accounts, asset_definitions, [], [])
    }
    /// Creates a World whose asset supplies equal the supplied initial balances.
    /// Repeated asset identities retain their last supplied balance.
    ///
    /// # Panics
    /// Panics if supplied entities are invalid or their rebuild cannot
    /// complete. Production callers use [`Self::try_with_execution_budget`].
    pub fn with_assets<D, A, Ad, As, N>(
        domains: D,
        accounts: A,
        asset_definitions: Ad,
        assets: As,
        nfts: N,
    ) -> Self
    where
        D: IntoIterator<Item = Domain>,
        A: IntoIterator<Item = Account>,
        Ad: IntoIterator<Item = AssetDefinition>,
        As: IntoIterator<Item = Asset>,
        N: IntoIterator<Item = Nft>,
    {
        Self::try_with_assets_on(
            WorldData::default(),
            domains,
            accounts,
            asset_definitions,
            assets,
            nfts,
        )
        .expect("invalid World initialization in convenience constructor")
    }
    /// Construct World with its configured original execution pool.
    ///
    /// Initial storage refusal occurs before consuming the supplied entity iterators.
    /// Later validation/rebuild failure drops consumed entities and returns the
    /// original typed cause; retry therefore requires the caller's source values.
    ///
    /// # Errors
    /// Returns original cell admission refusal, malformed entity state, or typed
    /// local execution deferral. No partially rebuilt World escapes on failure.
    /// TODO(S6): ordinary input tables, indexes and nested Kaigi/crypto graphs still
    /// need complete original-pool physical ownership; codec quotas do not fund them.
    pub fn try_with_execution_budget<D, A, Ad>(
        domains: D,
        accounts: A,
        asset_definitions: Ad,
        execution_budget: &iroha_allocation::AllocationBudget,
    ) -> Result<Self, WorldConstructionError>
    where
        D: IntoIterator<Item = Domain>,
        A: IntoIterator<Item = Account>,
        Ad: IntoIterator<Item = AssetDefinition>,
    {
        let fields = WorldData::try_new_with_execution_budget(execution_budget)?;
        let result = Self::try_with_assets_on(fields, domains, accounts, asset_definitions, [], []);
        #[cfg(all(test, sumeragi_core_mutation = "HC221"))]
        {
            return Ok(
                result.expect("invalid World initialization in restored infallible boundary")
            );
        }
        #[cfg(not(all(test, sumeragi_core_mutation = "HC221")))]
        result
    }
    fn try_with_assets_on<D, A, Ad, As, N>(
        initial: WorldData,
        domains: D,
        accounts: A,
        asset_definitions: Ad,
        assets: As,
        nfts: N,
    ) -> Result<Self, WorldConstructionError>
    where
        D: IntoIterator<Item = Domain>,
        A: IntoIterator<Item = Account>,
        Ad: IntoIterator<Item = AssetDefinition>,
        As: IntoIterator<Item = Asset>,
        N: IntoIterator<Item = Nft>,
    {
        let domains: Storage<DomainId, Domain> = domains
            .into_iter()
            .map(|domain| (domain.id().clone(), domain))
            .collect();
        let mut account_pairs = BTreeMap::<AccountId, AccountValue>::new();
        let mut rekey_pairs = Vec::new();
        for account in accounts {
            if let Some(record) = AccountRekeyRecord::from_account(&account) {
                rekey_pairs.push((record.label.clone(), record));
            }
            let (account_id, account_value) = account.into_key_value();
            account_pairs.insert(account_id, account_value);
        }
        let accounts = account_pairs.into_iter().collect();
        let account_rekey_records = rekey_pairs.into_iter().collect();
        let mut definition_pairs = BTreeMap::new();
        let mut definition_alias_bindings = BTreeMap::new();
        let mut definition_domains = BTreeMap::new();
        let domain_view = domains.view();
        for mut definition in asset_definitions {
            let definition_id = definition.id().clone();
            if definition.balance_scope_policy() == AssetBalancePolicy::DataspaceRestricted
                && definition.owning_domain().is_none()
            {
                return Err(format!(
                    "dataspace-restricted asset definition {definition_id} requires an explicit owning domain"
                ).into());
            }
            if let Some(domain_id) = definition.owning_domain().as_ref() {
                if domain_view.get(domain_id).is_none() {
                    return Err(format!(
                        "asset definition {definition_id} references missing owning domain {domain_id}"
                    ).into());
                }
                definition_domains.insert(definition_id.clone(), domain_id.clone());
            }
            if let Some(alias) = definition.alias.take() {
                if let Some(domain) = alias.domain_segment() {
                    let domain_id =
                        DomainId::try_new(domain, alias.dataspace_segment()).map_err(|error| {
                            format!("qualified asset alias must contain a valid domain: {error}")
                        })?;
                    if domain_view.get(&domain_id).is_none() {
                        return Err(format!(
                            "qualified asset alias `{alias}` references missing domain {domain_id}"
                        )
                        .into());
                    }
                }
                definition_alias_bindings.insert(
                    definition_id.clone(),
                    AssetDefinitionAliasBindingRecord {
                        alias,
                        lease_expiry_ms: None,
                        grace_until_ms: None,
                        bound_at_ms: 0,
                    },
                );
            }
            definition_pairs.insert(definition_id, definition);
        }
        drop(domain_view);
        let asset_pairs = assets
            .into_iter()
            .map(IntoKeyValue::into_key_value)
            .collect::<BTreeMap<AssetId, AssetValue>>();
        for definition in definition_pairs.values_mut() {
            definition.total_quantity = Quantity::zero();
        }
        for (id, quantity) in &asset_pairs {
            let definition = definition_pairs
                .get_mut(id.definition())
                .ok_or_else(|| "initial asset must have its original definition".to_owned())?;
            ensure_asset_quantity_value(&quantity.0, definition.spec()).map_err(|error| {
                format!("initial asset quantity must satisfy its definition: {error:?}")
            })?;
            definition.total_quantity = definition
                .total_quantity
                .checked_add(&quantity.0)
                .map_err(|error| {
                    format!("initial asset supply must fit its quantity representation: {error:?}")
                })?;
            ensure_asset_quantity_value(&definition.total_quantity, definition.spec()).map_err(
                |error| format!("initial asset supply must satisfy its definition: {error:?}"),
            )?;
        }
        let asset_definitions = definition_pairs.into_iter().collect();
        let asset_definition_alias_bindings = definition_alias_bindings.into_iter().collect();
        let asset_definition_domains = definition_domains.into_iter().collect();
        let assets = asset_pairs.into_iter().collect();
        let nfts = nfts.into_iter().map(IntoKeyValue::into_key_value).collect();
        let mut world = Self(Box::new(WorldData {
            domains,
            domains_by_owner: Storage::default(),
            kaigi_relay_registry: Storage::default(),
            kaigi_account_dependencies: Storage::default(),
            accounts,
            uaid_accounts: Storage::default(),
            account_rekey_records,
            account_rekey_records_by_account: Storage::default(),
            account_recovery_policies: Storage::default(),
            account_recovery_requests: Storage::default(),
            account_scope_accounts: Storage::default(),
            asset_definitions,
            asset_definition_aliases: Storage::default(),
            asset_definition_alias_bindings,
            contract_aliases: Storage::default(),
            contract_alias_bindings: Storage::default(),
            asset_definition_domains,
            domain_asset_definitions: Storage::default(),
            asset_definitions_by_owner: Storage::default(),
            asset_definition_holders: Storage::default(),
            asset_definition_assets: Storage::default(),
            assets_by_account: Storage::default(),
            assets_by_domain: Storage::default(),
            asset_definition_nonzero_holders: Storage::default(),
            assets,
            asset_metadata: Storage::default(),
            nfts,
            nfts_by_owner: Storage::default(),
            nfts_by_domain: Storage::default(),
            rwas: Storage::default(),
            rwas_by_owner: Storage::default(),
            rwas_by_status: Storage::default(),
            rwas_by_frozen: Storage::default(),
            proofs: Storage::default(),
            proofs_by_status: Storage::default(),
            contract_manifests: Storage::default(),
            contract_code: Storage::default(),
            contract_code_uploads: Storage::default(),
            contract_code_upload_chunks: Storage::default(),
            contract_instances: Storage::default(),
            contract_subject_bindings: Storage::default(),
            contract_subject_addresses: Storage::default(),
            smart_contract_state: Storage::default(),
            capacity_declarations: Storage::default(),
            capacity_fee_ledger: Storage::default(),
            capacity_disputes: Storage::default(),
            sorafs_pricing: Cell::default(),
            provider_credit_ledger: Storage::default(),
            provider_owners: Storage::default(),
            provider_ingest_completion_authorities: Storage::default(),
            da_pin_intents_by_ticket: Storage::default(),
            da_pin_intents_by_alias: Storage::default(),
            da_pin_intents_by_manifest: Storage::default(),
            da_pin_intents_by_lane_epoch: Storage::default(),
            pin_manifests: Storage::default(),
            manifest_aliases: Storage::default(),
            replication_orders: Storage::default(),
            repo_agreements: Storage::default(),
            repo_agreements_by_initiator: Storage::default(),
            repo_agreements_by_counterparty: Storage::default(),
            repo_agreements_by_custodian: Storage::default(),
            settlement_receipts: Storage::default(),
            bonds: Storage::default(),
            bond_entitlements: Storage::default(),
            bond_vaults: Storage::default(),
            ministry_agenda_proposals: Storage::default(),
            governance_proposals: Storage::default(),
            governance_referenda: Storage::default(),
            governance_locks: Storage::default(),
            governance_lock_expiry_index: Storage::default(),
            validation_fee_proposal_index: Storage::default(),
            governance_slashes: Storage::default(),
            governance_last_unlock_sweep_height: Cell::default(),
            governance_unlock_stats: Cell::default(),
            parliament_attempts: Storage::default(),
            ..initial
        }));
        world.validate_numeric_asset_invariants().map_err(|error| {
            format!("invalid numeric asset state in world constructor: {error}")
        })?;
        world
            .validate_quantity_ledger_invariants()
            .map_err(|error| {
                error.map_rejection(|error| {
                    format!("invalid quantity ledger state in world constructor: {error}")
                })
            })?;
        world.rebuild_domain_owner_index();
        world
            .rebuild_account_identity_indexes()
            .map_err(|error| format!("duplicate UAID in world constructor: {error}"))?;
        world
            .rebuild_account_alias_index()
            .map_err(|error| format!("duplicate account alias in world constructor: {error}"))?;
        world.rebuild_account_scope_directory().map_err(|error| {
            format!("invalid account scope directory in world constructor: {error}")
        })?;
        world.rebuild_account_rekey_records().map_err(|error| {
            format!("invalid account rekey state in world constructor: {error}")
        })?;
        crate::smartcontracts::isi::kaigi::rebuild_kaigi_relay_registry(&mut world).map_err(
            |error| {
                error.map_rejection(|error| {
                    format!("invalid Kaigi relay registry in world constructor: {error}")
                })
            },
        )?;
        crate::smartcontracts::isi::kaigi::rebuild_kaigi_account_dependencies(&mut world).map_err(
            |error| {
                error.map_rejection(|error| {
                    format!("invalid Kaigi account dependencies in world constructor: {error}")
                })
            },
        )?;
        world
            .rebuild_asset_definition_alias_indexes()
            .map_err(|error| {
                format!("duplicate asset definition alias in world constructor: {error}")
            })?;
        world
            .rebuild_contract_alias_indexes()
            .map_err(|error| format!("duplicate contract alias in world constructor: {error}"))?;
        world.rebuild_asset_definition_indexes().map_err(|error| {
            format!("invalid asset definition domain context in world constructor: {error}")
        })?;
        world
            .rebuild_confidential_policy_transition_index()
            .map_err(|error| {
                format!("invalid confidential-policy transition in world constructor: {error}")
            })?;
        world.rebuild_governance_read_indexes().map_err(|error| {
            format!("invalid governance read indexes in world constructor: {error}")
        })?;
        world.rebuild_nft_owner_index();
        world
            .rebuild_nft_custody_indexes()
            .map_err(|error| format!("invalid native NFT custody in world constructor: {error}"))?;
        world.rebuild_rwa_indexes();
        world.rebuild_escrow_indexes();
        world.rebuild_game_session_indexes().map_err(|error| {
            format!("invalid game session indexes in world constructor: {error}")
        })?;
        world
            .rebuild_vpn_lease_indexes()
            .map_err(|error| format!("invalid VPN lease indexes in world constructor: {error}"))?;
        world.rebuild_repo_agreement_indexes();
        world.rebuild_bond_vault_index();
        world.rebuild_proof_status_index();
        world.validate_identifier_claims().map_err(|error| {
            format!("identifier claims must match account bindings in world constructor: {error}")
        })?;
        Ok(world)
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Creates a [`World`] populated with assets and pre-defined roles.
    ///
    /// This constructor inserts `roles` directly into the world state without
    /// emitting events or applying the `Register<Role>` semantics (such as
    /// auto-granting a role to an initial owner).
    pub fn with_assets_and_roles<D, A, Ad, As, N, R>(
        domains: D,
        accounts: A,
        asset_definitions: Ad,
        assets: As,
        nfts: N,
        roles: R,
    ) -> Self
    where
        D: IntoIterator<Item = Domain>,
        A: IntoIterator<Item = Account>,
        Ad: IntoIterator<Item = AssetDefinition>,
        As: IntoIterator<Item = Asset>,
        N: IntoIterator<Item = Nft>,
        R: IntoIterator<Item = Role>,
    {
        let mut world = Self::with_assets(domains, accounts, asset_definitions, assets, nfts);
        for mut role in roles {
            role.ensure_permission_epochs(0);
            world.roles.insert(role.id.clone(), role);
        }
        world
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Grant a role to an account in test/bench setup code.
    ///
    /// This directly mutates role assignments without emitting events.
    pub fn grant_role_for_tests(&mut self, account: AccountId, role: RoleId) {
        self.account_roles
            .insert(RoleIdWithOwner::new(account, role), ());
    }
    fn rebuild_account_identity_indexes(&mut self) -> Result<(), String> {
        account_identity_restore::rebuild(self)
    }
    fn rebuild_account_alias_index(&mut self) -> Result<(), String> {
        let mut index = BTreeMap::new();
        let mut reverse = BTreeMap::<AccountId, BTreeSet<AccountAlias>>::new();
        let existing_bindings: Vec<_> = self
            .account_aliases
            .view()
            .iter()
            .map(|(label, account_id)| (label.clone(), account_id.clone()))
            .collect();
        let view = self.accounts.view();
        for (label, account_id) in existing_bindings {
            if account_label_is_pii(&label) {
                return Err(format!(
                    "Account alias {label:?} looks like raw PII; use UAID/opaque identifiers"
                ));
            }
            let Some(_account_value) = view.get(&account_id) else {
                return Err(format!(
                    "Account alias {label:?} references missing account {account_id}"
                ));
            };
            if let Some(existing) = index.get(&label) {
                if existing != &account_id {
                    return Err(format!(
                        "Account alias {label:?} already bound to account {existing}"
                    ));
                }
                continue;
            }
            reverse
                .entry(account_id.clone())
                .or_default()
                .insert(label.clone());
            index.insert(label, account_id);
        }
        for (account_id, value) in view.iter() {
            let Some(label) = value.as_ref().label() else {
                continue;
            };
            if account_label_is_pii(label) {
                return Err(format!(
                    "Account alias {label:?} looks like raw PII; use UAID/opaque identifiers"
                ));
            }
            let Some(existing) = index.get(label) else {
                return Err(format!(
                    "Account primary label {label:?} is missing its authoritative alias binding"
                ));
            };
            if existing != account_id {
                return Err(format!(
                    "Account primary label {label:?} is bound to account {existing}, not {account_id}"
                ));
            }
        }
        let previous_reverse = {
            let reverted_aliases = self.account_aliases.block_and_revert();
            let mut previous = BTreeMap::<AccountId, BTreeSet<AccountAlias>>::new();
            for (label, account_id) in reverted_aliases.iter() {
                previous
                    .entry(account_id.clone())
                    .or_default()
                    .insert(label.clone());
            }
            // Abort the temporary revert view so the authoritative alias ledger and its undo
            // journal remain byte-for-byte unchanged.
            drop(reverted_aliases);
            previous
        };
        self.account_aliases_by_account =
            rebuild_derived_storage_with_previous(reverse, previous_reverse);
        Ok(())
    }
