    fn validate_plain_governance_tally_capacity(&self) -> Result<(), String> {
        let referenda = self.governance_referenda.view();
        for (_, record) in referenda.iter() {
            record.validate_context()?;
        }
        for (referendum_id, locks) in self.governance_locks.view().iter() {
            let record = referenda.get(referendum_id).ok_or_else(|| {
                format!("governance locks have no owning referendum {referendum_id}")
            })?;
            if record.mode == GovernanceReferendumMode::Zk {
                continue;
            }
            crate::smartcontracts::isi::world::isi::plain_governance_tally_v1(
                locks, None, None, record.plain_policy()?,
            ).map_err(|error| format!("governance locks for referendum {referendum_id} exceed the exact frozen tally domain: {error}"))?;
        }
        Ok(())
    }
    /// Rebuild the unique logical-beacon height lookup for finalized global-beacon pulses.
    ///
    /// # Errors
    /// Returns an error when either the current or latest-block-previous authoritative pulse view
    /// stores a pulse under a noncanonical id or lets two records claim the same consensus slot.
    pub(crate) fn rebuild_global_beacon_pulse_slots(&mut self) -> Result<(), String> {
        fn pulse_slot_index<'a>(
            pulses: impl IntoIterator<
                Item = (
                    &'a [u8; 32],
                    &'a iroha_data_model::consensus::FinalizedGlobalThresholdBeaconPulseV1,
                ),
            >,
        ) -> Result<BTreeMap<(BeaconSessionId, u64), [u8; 32]>, String> {
            let mut rebuilt = BTreeMap::new();
            for (stored_pulse_id, pulse) in pulses {
                if pulse.pulse_id != *stored_pulse_id {
                    return Err(format!(
                        "global beacon pulse {} is stored under noncanonical id {}",
                        hex::encode(pulse.pulse_id),
                        hex::encode(stored_pulse_id)
                    ));
                }
                let slot = (
                    BeaconSessionId::for_network_v1(&pulse.network_id),
                    pulse.height,
                );
                if let Some(existing_pulse_id) = rebuilt.insert(slot, *stored_pulse_id) {
                    return Err(format!(
                        "global beacon pulses {} and {} claim the same logical-beacon-height slot",
                        hex::encode(existing_pulse_id),
                        hex::encode(stored_pulse_id)
                    ));
                }
            }
            Ok(rebuilt)
        }

        let current = {
            let pulses = self.global_beacon_pulses.view();
            pulse_slot_index(pulses.iter())?
        };
        let previous = {
            let reverted_pulses = self.global_beacon_pulses.block_and_revert();
            pulse_slot_index(reverted_pulses.iter())?
        };
        self.global_beacon_pulse_slots = rebuild_derived_storage_with_previous(current, previous);
        Ok(())
    }
    fn rebuild_confidential_policy_transition_index(&mut self) -> core::result::Result<(), String> {
        #[expect(
            clippy::zero_sized_map_values,
            reason = "Both current and undo maps rebuild the authoritative Storage<K, ()> transition index without changing its journal representation"
        )]
        fn derive<'a>(
            definitions: impl Iterator<Item = (&'a AssetDefinitionId, &'a AssetDefinition)>,
        ) -> core::result::Result<
            (BTreeMap<(u64, AssetDefinitionId), ()>, BTreeMap<u64, u32>),
            String,
        > {
            let mut transitions = BTreeMap::new();
            let mut counts = BTreeMap::<u64, u32>::new();
            for (definition_id, definition) in definitions {
                let policy = definition.confidential_policy();
                if !policy.pending_transition_is_valid() {
                    return Err(format!(
                        "asset definition `{definition_id}` has a structurally invalid pending confidential-policy transition"
                    ));
                }
                if let Some(transition) = policy.pending_transition() {
                    let effective_height = transition.effective_height();
                    transitions.insert((effective_height, definition_id.clone()), ());
                    let count = counts.entry(effective_height).or_default();
                    *count = count.checked_add(1).ok_or_else(|| {
                        format!(
                            "confidential-policy transition count overflows at height {effective_height}"
                        )
                    })?;
                }
            }
            Ok((transitions, counts))
        }
        // Validate both cuts before installing either derived store. A transition
        // consumed at H must become pending again when H is replaced after restore.
        let ((transitions, counts), (previous_transitions, previous_counts)) =
            {
                let definitions = self.asset_definitions.snapshot();
                let current = derive(definitions.current().iter())?;
                let previous =
                    derive(
                        definitions
                            .current()
                            .iter()
                            .filter(|(key, _)| !definitions.revert_map().contains_key(*key))
                            .chain(definitions.revert_map().iter().filter_map(|(key, value)| {
                                value.as_ref().map(|value| (key, value))
                            })),
                    )?;
                (current, previous)
            };
        self.confidential_policy_transition_index =
            rebuild_derived_storage_with_previous(transitions, previous_transitions);
        self.confidential_policy_transition_counts =
            rebuild_derived_storage_with_previous(counts, previous_counts);
        Ok(())
    }
