/// Derive one active timed-OVN resource reservation from canonical Parliament state.
fn parliament_timed_ovn_resource_reservation_v1(
    governance_attempt_id: GovernanceAttemptId,
    attempt: &ParliamentAttemptStateV1,
    ballot_attempt_id: BallotAttemptId,
) -> Option<(BallotAttemptId, ParliamentTimedOvnResourceReservationV1)> {
    if attempt.attempt().id != governance_attempt_id
        || attempt.attempt().status != GovernanceAttemptStatusV1::Active
    {
        return None;
    }
    let ballot = attempt.ballot(&ballot_attempt_id)?;
    if matches!(
        ballot.attempt().status,
        BallotAttemptStatusV1::Finalized
            | BallotAttemptStatusV1::NoResult
            | BallotAttemptStatusV1::Superseded
    ) || attempt
        .active_ballot_for_body(&ballot.attempt().body_instance_id)
        .is_none_or(|active| active.attempt().id != ballot_attempt_id)
        || attempt
            .body(&ballot.attempt().body_instance_id)
            .is_none_or(|body| body.instance().status != BodyInstanceStatusV1::Balloting)
    {
        return None;
    }
    let release_height = ballot.release_height()?;
    Some((
        ballot_attempt_id,
        ParliamentTimedOvnResourceReservationV1 {
            governance_attempt_id,
            resource_windows: [
                (
                    ballot.registered_at_height(),
                    ballot.commitment_close_height(),
                ),
                (release_height, ballot.opening_deadline_height()),
            ],
            cast_capable: matches!(
                ballot.attempt().status,
                BallotAttemptStatusV1::Registration
                    | BallotAttemptStatusV1::SurvivorFreeze
                    | BallotAttemptStatusV1::TimedCommitment
            ),
        },
    ))
}

/// Derive one active hidden-ballot phase window for compact casting snapshots.
fn parliament_timed_ovn_casting_candidate_v1(
    governance_attempt_id: GovernanceAttemptId,
    attempt: &ParliamentAttemptStateV1,
    ballot_attempt_id: BallotAttemptId,
) -> Option<(BallotAttemptId, ParliamentTimedOvnCastingCandidateV1)> {
    if attempt.attempt().id != governance_attempt_id
        || attempt.attempt().status != GovernanceAttemptStatusV1::Active
    {
        return None;
    }
    let ballot = attempt.ballot(&ballot_attempt_id)?;
    let body_instance_id = ballot.attempt().body_instance_id;
    let body = attempt.body(&body_instance_id)?;
    if body.instance().status != BodyInstanceStatusV1::Balloting
        || attempt
            .active_ballot_for_body(&body_instance_id)
            .is_none_or(|active| active.attempt().id != ballot_attempt_id)
        || attempt
            .sealed_body_for_role(body.instance().body)
            .is_none_or(|active| active.instance().id != body_instance_id)
        || attempt
            .required_bodies()
            .iter()
            .find(|required| required.body == body.instance().body)
            .is_none_or(|required| {
                required.decision_mode != ParliamentDecisionModeV1::HiddenBindingBallot
            })
    {
        return None;
    }
    let (valid_from_height, valid_until_height_exclusive) = match ballot.attempt().status {
        BallotAttemptStatusV1::Registration => (
            ballot.registered_at_height(),
            ballot.registration_close_height(),
        ),
        BallotAttemptStatusV1::SurvivorFreeze => (
            ballot.registration_close_height(),
            ballot.survivor_freeze_height(),
        ),
        BallotAttemptStatusV1::TimedCommitment => (
            ballot.survivor_freeze_height(),
            ballot.commitment_close_height(),
        ),
        BallotAttemptStatusV1::AwaitingRelease
        | BallotAttemptStatusV1::Opening
        | BallotAttemptStatusV1::Finalized
        | BallotAttemptStatusV1::NoResult
        | BallotAttemptStatusV1::Superseded => return None,
    };
    Some((
        ballot_attempt_id,
        ParliamentTimedOvnCastingCandidateV1 {
            governance_attempt_id,
            valid_from_height,
            valid_until_height_exclusive,
        },
    ))
}

/// Return whether either closed resource window of two timed-OVN schedules intersects.
///
/// Each schedule carries its registration-through-commitment window and its release-through-
/// opening window. Admission reserves both because every V1 registration, maximum ballot chunk,
/// and aggregate opening can consume most of the standard per-block gas budget.
fn parliament_timed_ovn_resource_windows_overlap_v1(
    left: [(u64, u64); 2],
    right: [(u64, u64); 2],
) -> bool {
    left.into_iter().any(|(left_start, left_end)| {
        right
            .into_iter()
            .any(|(right_start, right_end)| left_start <= right_end && right_start <= left_end)
    })
}

/// Insert one derived timed-OVN reservation into a prospective exact index.
///
/// Callers build the prospective index off to the side and publish it only
/// after every reservation passes. This keeps attempt admission and restore
/// fail-atomic while sharing one exact duplicate, overlap, and capacity rule.
fn insert_parliament_timed_ovn_resource_reservation_v1(
    reservations: &mut BTreeMap<BallotAttemptId, ParliamentTimedOvnResourceReservationV1>,
    ballot_attempt_id: BallotAttemptId,
    reservation: ParliamentTimedOvnResourceReservationV1,
) -> Result<(), ParliamentTimedOvnResourceReservationErrorV1> {
    if reservations.contains_key(&ballot_attempt_id) {
        return Err(ParliamentTimedOvnResourceReservationErrorV1::DuplicateBallotAttempt);
    }
    if reservations.values().any(|existing| {
        parliament_timed_ovn_resource_windows_overlap_v1(
            reservation.resource_windows,
            existing.resource_windows,
        )
    }) {
        return Err(ParliamentTimedOvnResourceReservationErrorV1::ResourceScheduleConflict);
    }
    if reservation.cast_capable {
        let current_count = u32::try_from(
            reservations
                .values()
                .filter(|existing| existing.cast_capable)
                .count(),
        )
        .map_err(|_| {
            ParliamentTimedOvnResourceReservationErrorV1::TooManyConcurrentCastingContexts
        })?;
        if !iroha_data_model::parliament_casting::parliament_timed_ovn_casting_capacity_allows_new_v1(
            current_count,
        ) {
            return Err(
                ParliamentTimedOvnResourceReservationErrorV1::TooManyConcurrentCastingContexts,
            );
        }
    }
    reservations.insert(ballot_attempt_id, reservation);
    Ok(())
}

fn parliament_timed_ovn_reservation_reducer_error_v1(
    error: ParliamentTimedOvnResourceReservationErrorV1,
) -> crate::governance::parliament::ParliamentReducerErrorV1 {
    use crate::governance::parliament::{ParliamentReducerEntityV1, ParliamentReducerErrorV1};

    match error {
        ParliamentTimedOvnResourceReservationErrorV1::DuplicateBallotAttempt => {
            ParliamentReducerErrorV1::DuplicateOrZeroIdentifier(
                ParliamentReducerEntityV1::BallotAttempt,
            )
        }
        ParliamentTimedOvnResourceReservationErrorV1::ResourceScheduleConflict => {
            ParliamentReducerErrorV1::TimedOvnResourceScheduleConflict
        }
        ParliamentTimedOvnResourceReservationErrorV1::TooManyConcurrentCastingContexts => {
            ParliamentReducerErrorV1::TooManyConcurrentCastingContexts
        }
    }
}

