    /// Get mutable reference to [`Asset`]
    ///
    /// # Errors
    /// If domain, account or asset not found
    pub fn asset_mut(&mut self, id: &AssetId) -> Result<&mut AssetValue, FindError> {
        let resolved_id = self
            .resolve_asset_id_for_current_scope(id)
            .unwrap_or_else(|_| id.clone());
        let _ = self.account(resolved_id.account())?;
        if self.assets.get(&resolved_id).is_some() {
            // This raw mutable lease is not a complete typed quantity owner.
            self.quantity_mutation_observation.changed();
        }
        self.assets
            .get_mut(&resolved_id)
            .ok_or_else(|| FindError::Asset(resolved_id.into()))
    }
    /// Resolve the balance partition scope for an asset definition in the current execution context.
    ///
    /// A dataspace-restricted definition homed in a non-universal dataspace H always resolves to
    /// `Dataspace(H)` and is usable only on route H. Universal-homed restricted definitions keep
    /// one partition per execution dataspace.
    ///
    /// # Errors
    /// Returns an error when the definition is missing, when a confined definition is accessed
    /// on another route, or when a universal-homed restricted definition is accessed without an
    /// execution dataspace context.
    pub fn resolve_asset_balance_scope(
        &self,
        definition_id: &AssetDefinitionId,
    ) -> Result<AssetBalanceScope, Error> {
        let definition = self.asset_definition(definition_id).map_err(Error::from)?;
        if let Some(home) = self.confined_asset_home(&definition)? {
            self.ensure_confined_asset_route(home)?;
            return Ok(AssetBalanceScope::Dataspace(home));
        }
        match definition.balance_scope_policy() {
            AssetBalancePolicy::Global => Ok(AssetBalanceScope::Global),
            AssetBalancePolicy::DataspaceRestricted => self
                .current_dataspace_id
                .map(AssetBalanceScope::Dataspace)
                .ok_or_else(|| {
                    Error::InvariantViolation(
                        "dataspace-restricted asset access requires transaction dataspace context"
                            .into(),
                    )
                }),
        }
    }
    /// Home that confines every balance of `definition`, if it is confined.
    fn confined_asset_home(
        &self,
        definition: &AssetDefinition,
    ) -> Result<Option<DataSpaceId>, Error> {
        crate::read_scope::confined_home(self, definition).map_err(|error| {
            Error::InvariantViolation(format!("invalid asset-definition home: {error}").into())
        })
    }
    /// A confined definition moves only on its home route.
    fn ensure_confined_asset_route(&self, home: DataSpaceId) -> Result<(), Error> {
        match self.current_dataspace_id {
            Some(route) if route != home => Err(Error::InvariantViolation(
                format!(
                    "asset confined to home dataspace {} cannot be accessed on route {}",
                    home.as_u64(),
                    route.as_u64()
                )
                .into(),
            )),
            _ => Ok(()),
        }
    }
    /// Canonicalize an [`AssetId`] into the effective execution scope.
    ///
    /// When `dataspace_hint` is provided for a dataspace-restricted asset, it
    /// overrides the ambient execution dataspace. This is used for transfers
    /// whose destination account is bound to a different dataspace than the
    /// caller's current execution scope.
    ///
    /// # Errors
    /// Returns an error when the requested id contradicts the effective scope
    /// policy (for example, cross-dataspace access for restricted assets).
    pub fn resolve_asset_id_for_scope_hint(
        &self,
        id: &AssetId,
        dataspace_hint: Option<DataSpaceId>,
    ) -> Result<AssetId, Error> {
        let definition = self
            .asset_definition(id.definition())
            .map_err(Error::from)?;
        let requested_dataspace = match id.scope() {
            AssetBalanceScope::Dataspace(dataspace) => Some(*dataspace),
            AssetBalanceScope::Global => None,
        };
        if let Some(home) = self.confined_asset_home(&definition)? {
            if requested_dataspace.is_some_and(|requested| requested != home)
                || dataspace_hint.is_some_and(|hint| hint != home)
            {
                return Err(Error::InvariantViolation(
                    format!(
                        "asset confined to home dataspace {} cannot use another balance scope",
                        home.as_u64()
                    )
                    .into(),
                ));
            }
            self.ensure_confined_asset_route(home)?;
            return Ok(AssetId::with_scope(
                id.definition().clone(),
                id.account().clone(),
                AssetBalanceScope::Dataspace(home),
            ));
        }
        let ambient_dataspace = self.current_dataspace_id;
        let compatible_requested_dataspace =
            requested_dataspace.filter(|requested| match ambient_dataspace {
                None => true,
                Some(ambient) => ambient == DataSpaceId::UNIVERSAL || ambient == *requested,
            });
        let expected_scope = match definition.balance_scope_policy() {
            AssetBalancePolicy::Global => AssetBalanceScope::Global,
            AssetBalancePolicy::DataspaceRestricted => dataspace_hint
                .or(compatible_requested_dataspace)
                .or(ambient_dataspace)
                .map(AssetBalanceScope::Dataspace)
                .ok_or_else(|| {
                    Error::InvariantViolation(
                        "dataspace-restricted asset access requires transaction dataspace context"
                            .into(),
                    )
                })?,
        };
        match (id.scope(), &expected_scope) {
            (AssetBalanceScope::Global, AssetBalanceScope::Global) => {}
            (AssetBalanceScope::Global, AssetBalanceScope::Dataspace(_)) => {}
            (AssetBalanceScope::Dataspace(_), AssetBalanceScope::Global) => {
                return Err(Error::InvariantViolation(
                    "global assets cannot be addressed with dataspace scope".into(),
                ));
            }
            (AssetBalanceScope::Dataspace(actual), AssetBalanceScope::Dataspace(expected)) => {
                if actual != expected {
                    return Err(Error::InvariantViolation(
                        "dataspace-restricted assets cannot move across dataspaces in normal transfer/mint paths".into(),
                    ));
                }
            }
        }
        Ok(AssetId::with_scope(
            id.definition().clone(),
            id.account().clone(),
            expected_scope,
        ))
    }
    /// Canonicalize an [`AssetId`] into the current execution scope.
    ///
    /// # Errors
    /// Returns an error when the requested id contradicts the active scope policy
    /// (for example, cross-dataspace access for restricted assets).
    pub fn resolve_asset_id_for_current_scope(&self, id: &AssetId) -> Result<AssetId, Error> {
        self.resolve_asset_id_for_scope_hint(id, None)
    }
    /// Get an asset or initialize it with `default_asset_value` using the exact provided
    /// [`AssetId`].
    ///
    /// Callers must only use this with a balance id that has already been canonicalized for the
    /// intended scope. This is required for transfer destinations whose bound account dataspace
    /// differs from the current execution dataspace. This low-level helper does not enforce
    /// transfer-control holding limits and is restricted to independently validated
    /// initialization; production credit paths must use the checked exact deposit helper.
    ///
    /// # Errors
    /// - There is no account with such name.
    /// - The default or existing asset balance violates the definition's numeric spec.
    #[allow(clippy::missing_panics_doc)]
    #[cfg(any(test, feature = "iroha-core-tests"))]
    pub(crate) fn asset_or_insert_exact(
        &mut self,
        asset_id: &AssetId,
        default_asset_value: impl Into<Quantity>,
    ) -> Result<&mut AssetValue, Error> {
        let resolved_id = asset_id.clone();
        let spec = self.asset_definition(resolved_id.definition())?.spec();
        self.account(resolved_id.account())?;
        let default_asset_value = default_asset_value.into();
        ensure_asset_quantity_value(&default_asset_value, spec)?;
        if let Some(value) = self.assets.get(&resolved_id) {
            ensure_asset_quantity_value(value.as_ref(), spec)?;
        }
        // Returning a mutable balance also observes callers that overwrite it directly.
        self.quantity_mutation_observation.changed();
        if self.assets.get(&resolved_id).is_none() {
            let asset = Asset::new(resolved_id.clone(), default_asset_value);
            self.emit_asset_event(AssetEvent::Created(asset.clone()));
            let (asset_id, asset_value) = asset.into_key_value();
            let is_nonzero = !asset_value.as_ref().is_zero();
            self.track_asset_holder(&asset_id);
            if is_nonzero {
                self.track_nonzero_asset_holder(&asset_id);
            }
            self.assets.insert(asset_id, asset_value);
        }
        Ok(self
            .assets
            .get_mut(&resolved_id)
            .expect("Just inserted, cannot fail."))
    }
