    fn persist_query_index_status(
        &self,
        indexed_height: u64,
        indexed_block_hash: Option<HashOf<BlockHeader>>,
    ) {
        let _persistence_guard = self.query_index_journal_persistence_lock.lock();
        let path = self.query_index_journal_path();
        self.set_query_index_status(indexed_height, indexed_block_hash);
        if path.as_os_str().is_empty() {
            return;
        }
        self.persist_query_index_status_snapshot_locked(&path);
    }
    fn set_query_index_status(
        &self,
        indexed_height: u64,
        indexed_block_hash: Option<HashOf<BlockHeader>>,
    ) {
        self.query_index_journal
            .write()
            .set_latest(indexed_height, indexed_block_hash);
    }
    fn persist_query_index_status_snapshot_locked(&self, path: &Path) {
        let tmp_path = path.with_extension("norito.tmp");
        let measure_bytes = |path: &Path| -> Option<u64> {
            match std::fs::metadata(path) {
                Ok(meta) => Some(meta.len()),
                Err(err) if err.kind() == std::io::ErrorKind::NotFound => Some(0),
                Err(err) => {
                    warn!(?err, path = %path.display(), "failed to stat query index journal");
                    None
                }
            }
        };
        let before_bytes = match (measure_bytes(path), measure_bytes(&tmp_path)) {
            (Some(main), Some(tmp)) => Some(main.saturating_add(tmp)),
            _ => None,
        };
        let accounting_mutation = self
            .kura
            .begin_total_disk_usage_mutation()
            .with_resource_paths(vec![path.to_path_buf(), tmp_path.clone()]);
        let persistence_succeeded = match self.query_index_journal.read().persist() {
            Ok(()) => true,
            Err(err) => {
                warn!(
                    ?err,
                    path = %path.display(),
                    "failed to persist query index journal"
                );
                false
            }
        };
        let after_bytes = match (measure_bytes(path), measure_bytes(&tmp_path)) {
            (Some(main), Some(tmp)) => Some(main.saturating_add(tmp)),
            _ => None,
        };
        if let (Some(before_bytes), Some(after_bytes)) = (before_bytes, after_bytes) {
            self.kura.update_disk_usage_delta(before_bytes, after_bytes);
            if persistence_succeeded {
                accounting_mutation.finish();
            } else {
                // A measurable residue is not a completed journal publication.
                drop(accounting_mutation);
            }
        } else {
            drop(accounting_mutation);
            if let Err(err) = self.kura.refresh_disk_usage_bytes() {
                warn!(
                    ?err,
                    "failed to reconcile Kura disk usage after query index journal persistence"
                );
            }
        }
    }
    /// Fetch the latest durable query-index snapshot marker.
    #[must_use]
    pub fn query_index_status_snapshot(&self) -> QueryIndexStatus {
        self.query_index_journal.read().snapshot()
    }
