    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Persist the latest durable query projection checkpoint descriptor.
    pub fn persist_query_projection_checkpoint(
        &self,
        checkpoint: Option<QueryProjectionCheckpoint>,
    ) {
        let _persistence_guard = self
            .query_projection_checkpoint_journal_persistence_lock
            .lock();
        let path = self.query_projection_checkpoint_journal_path();
        let mut journal = self.query_projection_checkpoint_journal.write();
        journal.set_latest(checkpoint);
        if path.as_os_str().is_empty() {
            return;
        }
        let tmp_path = path.with_extension("norito.tmp");
        let measure_bytes = |path: &Path| -> Option<u64> {
            match std::fs::metadata(path) {
                Ok(meta) => Some(meta.len()),
                Err(err) if err.kind() == std::io::ErrorKind::NotFound => Some(0),
                Err(err) => {
                    warn!(
                        ?err,
                        path = %path.display(),
                        "failed to stat query projection checkpoint journal"
                    );
                    None
                }
            }
        };
        let before_bytes = match (measure_bytes(&path), measure_bytes(&tmp_path)) {
            (Some(main), Some(tmp)) => Some(main.saturating_add(tmp)),
            _ => None,
        };
        let accounting_mutation = self
            .kura
            .begin_total_disk_usage_mutation()
            .with_resource_paths(vec![path.clone(), tmp_path.clone()]);
        let persistence_succeeded = match journal.persist() {
            Ok(()) => true,
            Err(err) => {
                warn!(
                    ?err,
                    path = %path.display(),
                    "failed to persist query projection checkpoint journal"
                );
                false
            }
        };
        let after_bytes = match (measure_bytes(&path), measure_bytes(&tmp_path)) {
            (Some(main), Some(tmp)) => Some(main.saturating_add(tmp)),
            _ => None,
        };
        if let (Some(before_bytes), Some(after_bytes)) = (before_bytes, after_bytes) {
            self.kura.update_disk_usage_delta(before_bytes, after_bytes);
            if persistence_succeeded {
                accounting_mutation.finish();
            } else {
                // A measurable residue is not a completed journal publication.
                drop(accounting_mutation);
            }
        } else {
            drop(accounting_mutation);
            if let Err(err) = self.kura.refresh_disk_usage_bytes() {
                warn!(
                    ?err,
                    "failed to reconcile Kura disk usage after projection checkpoint journal persistence"
                );
            }
        }
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Build and persist a query projection checkpoint from the current index snapshot.
    pub fn publish_query_projection_checkpoint(
        &self,
        emitted_at_unix: u64,
        shards: Vec<QueryProjectionCheckpointShard>,
    ) -> QueryProjectionCheckpoint {
        let checkpoint = QueryProjectionCheckpoint::from_index_status(
            self.query_index_status_snapshot(),
            emitted_at_unix,
            shards,
        );
        self.persist_query_projection_checkpoint(Some(checkpoint.clone()));
        checkpoint
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Validate uploaded shard archives against the current query-index snapshot and
    /// build a checkpoint publication plan without mutating state yet.
    ///
    /// This lets a future DA worker preflight a large batch of uploaded projection
    /// shards before it persists the checkpoint descriptor that points at them.
    ///
    /// # Errors
    ///
    /// Returns [`QueryProjectionCheckpointPlanError`] when the uploaded shards do not
    /// form a coherent immutable checkpoint for the current query-index snapshot.
    pub fn plan_query_projection_checkpoint_from_archives<I>(
        &self,
        emitted_at_unix: u64,
        uploads: I,
    ) -> Result<QueryProjectionCheckpointPublishPlan, QueryProjectionCheckpointPlanError>
    where
        I: IntoIterator<Item = QueryProjectionUploadedShardArchive>,
    {
        QueryProjectionCheckpointPublishPlan::from_uploaded_archives(
            self.query_index_status_snapshot(),
            emitted_at_unix,
            uploads,
        )
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Build and persist a query projection checkpoint from uploaded shard archives.
    ///
    /// This is the intended handoff point for the future DA projection worker: once
    /// archive blobs have been uploaded and resolved to `(manifest_digest, storage_ticket)`,
    /// the worker can atomically persist the corresponding checkpoint descriptor.
    ///
    /// # Errors
    ///
    /// Returns [`QueryProjectionCheckpointPlanError`] when the uploaded shards do not
    /// form a coherent immutable checkpoint for the current query-index snapshot.
    pub fn publish_query_projection_checkpoint_from_archives<I>(
        &self,
        emitted_at_unix: u64,
        uploads: I,
    ) -> Result<QueryProjectionCheckpoint, QueryProjectionCheckpointPlanError>
    where
        I: IntoIterator<Item = (QueryProjectionShardArchive, BlobDigest, StorageTicketId)>,
    {
        let plan = self.plan_query_projection_checkpoint_from_archives(
            emitted_at_unix,
            uploads
                .into_iter()
                .map(QueryProjectionUploadedShardArchive::from),
        )?;
        let checkpoint = plan.into_checkpoint();
        self.persist_query_projection_checkpoint(Some(checkpoint.clone()));
        Ok(checkpoint)
    }
    #[cfg(test)]
    fn ingest_pin_intents(
        &self,
        block_height: u64,
        intents: Vec<iroha_data_model::da::pin_intent::DaPinIntent>,
        context: &str,
    ) -> Vec<DaPinIntentWithLocation> {
        let positions = Self::pin_intent_bundle_positions(&intents);
        let nexus = self.nexus_snapshot();
        let (intents, rejected) = {
            let view = self.view();
            let world = view.world();
            let account_exists = |account: &iroha_data_model::account::AccountId| {
                world.accounts().get(account).is_some()
            };
            crate::da::sanitize_pin_intents_against_nexus_at_height(
                intents,
                &nexus,
                block_height,
                account_exists,
            )
        };
        self.insert_sanitized_pin_intents(block_height, intents, rejected, context, &positions)
    }
    fn ingest_committed_pin_intents_from_kura_into(
        &self,
        nexus: &iroha_config::parameters::actual::Nexus,
        store: &mut DaPinStore,
        shard_cursors: &DaShardCursorIndex,
        block_height: u64,
        intents: Vec<iroha_data_model::da::pin_intent::DaPinIntent>,
    ) -> Vec<DaPinIntentWithLocation> {
        let positions = Self::pin_intent_bundle_positions(&intents);
        let (intents, rejected) = crate::da::sanitize_pin_intents_against_nexus_at_height(
            intents,
            nexus,
            block_height,
            |_| true,
        );
        Self::insert_sanitized_pin_intents_into(
            store,
            block_height,
            intents,
            rejected,
            "kura-replay",
            &positions,
            |lane_id| {
                shard_cursors
                    .canonical_reset_height_for_lane(lane_id)
                    .is_none_or(|reset_height| block_height > reset_height)
            },
        )
    }
    fn pin_intent_bundle_positions(
        intents: &[iroha_data_model::da::pin_intent::DaPinIntent],
    ) -> BTreeMap<iroha_data_model::da::pin_intent::DaPinIntent, usize> {
        iroha_data_model::da::pin_intent::DaPinIntentBundle::new(intents.to_vec())
            .intents
            .into_iter()
            .enumerate()
            .map(|(idx, intent)| (intent, idx))
            .collect()
    }
    #[cfg(test)]
    fn insert_sanitized_pin_intents(
        &self,
        block_height: u64,
        intents: Vec<iroha_data_model::da::pin_intent::DaPinIntent>,
        rejected: Vec<crate::da::DaPinIntentValidationError>,
        context: &str,
        positions: &BTreeMap<iroha_data_model::da::pin_intent::DaPinIntent, usize>,
    ) -> Vec<DaPinIntentWithLocation> {
        let canonical_reset_heights = self.canonical_lane_reset_heights_snapshot();
        let mut store = self.da_pin_intents.write();
        Self::insert_sanitized_pin_intents_into(
            &mut store,
            block_height,
            intents,
            rejected,
            context,
            positions,
            |lane_id| {
                canonical_reset_heights
                    .get(&lane_id)
                    .is_none_or(|reset_height| block_height > *reset_height)
            },
        )
    }
    fn insert_sanitized_pin_intents_into(
        store: &mut DaPinStore,
        block_height: u64,
        intents: Vec<iroha_data_model::da::pin_intent::DaPinIntent>,
        rejected: Vec<crate::da::DaPinIntentValidationError>,
        context: &str,
        positions: &BTreeMap<iroha_data_model::da::pin_intent::DaPinIntent, usize>,
        mut lane_visible: impl FnMut(LaneId) -> bool,
    ) -> Vec<DaPinIntentWithLocation> {
        if !rejected.is_empty() {
            for reason in rejected {
                warn!(
                    height = block_height,
                    context,
                    ?reason,
                    "dropping invalid DA pin intent during ingestion"
                );
            }
        }
        if intents.is_empty() {
            return Vec::new();
        }
        let mut inserted = Vec::new();
        for (idx, intent) in intents.into_iter().enumerate() {
            if !lane_visible(intent.lane_id) {
                warn!(
                    height = block_height,
                    lane = %intent.lane_id.as_u32(),
                    context,
                    "dropping DA pin intent from an earlier lane incarnation"
                );
                continue;
            }
            let position = positions.get(&intent).copied().unwrap_or(idx);
            let Some(index_in_bundle) = crate::da::da_bundle_location_index(position) else {
                warn!(
                    height = block_height,
                    index = position,
                    context,
                    "dropping DA pin intent with unrepresentable bundle location"
                );
                continue;
            };
            let location = DaCommitmentLocation {
                block_height,
                index_in_bundle,
            };
            if store.insert(intent.clone(), location) {
                inserted.push(DaPinIntentWithLocation { intent, location });
            }
        }
        inserted
    }
    fn active_reset_lanes(
        lanes_to_reset: &BTreeSet<LaneId>,
        lane_config: &iroha_config::parameters::actual::LaneConfig,
    ) -> BTreeSet<LaneId> {
        lanes_to_reset
            .iter()
            .copied()
            .filter(|lane_id| lane_config.entry(*lane_id).is_some())
            .collect()
    }
    fn record_da_lane_reset_watermarks(
        &self,
        lanes_to_reset: &BTreeSet<LaneId>,
        reset_height: u64,
        releases: &mut LaneLifecycleReleases<'_>,
    ) {
        if lanes_to_reset.is_empty() || reset_height == 0 {
            return;
        }
        {
            let mut cursors = releases.shard_cursors.write();
            cursors.mark_lanes_canonically_reset(lanes_to_reset, reset_height);
        }
        self.persist_lane_lifecycle_cursor_journal(releases);
    }
    #[cfg(test)]
    pub(crate) fn advance_da_shard_cursors_from_bundle(
        &self,
        block_height: u64,
        records: &[iroha_data_model::da::commitment::DaCommitmentRecord],
    ) -> Result<(), DaShardCursorError> {
        let lane_config = self.nexus_snapshot().lane_config.clone();
        let mut cursors = self.da_shard_cursors.write();
        self.advance_da_shard_cursors_into(&mut cursors, &lane_config, block_height, records.iter())
    }
    #[expect(
        single_use_lifetimes,
        reason = "stable Rust requires a named lifetime for borrowed impl Trait items"
    )]
    fn advance_da_shard_cursors_into<'a>(
        &self,
        cursors: &mut DaShardCursorIndex,
        lane_config: &iroha_config::parameters::actual::LaneConfig,
        block_height: u64,
        records: impl Iterator<Item = &'a DaCommitmentRecord> + Clone,
    ) -> Result<(), DaShardCursorError> {
        let result = cursors.record_records(lane_config, records.clone(), block_height);
        #[cfg(feature = "telemetry")]
        {
            match &result {
                Ok(()) => {
                    for record in records {
                        let shard_id = lane_config.shard_id(record.lane_id);
                        self.telemetry.record_da_shard_cursor_event(
                            "advance",
                            record.lane_id.as_u32(),
                            shard_id,
                            block_height,
                        );
                        record_da_shard_cursor_lag(
                            &self.telemetry,
                            record.lane_id.as_u32(),
                            shard_id,
                            0,
                        );
                    }
                }
                Err(err) => {
                    let (lane_id, shard_id, lag_blocks) = match err {
                        DaShardCursorError::Regression {
                            lane_id,
                            shard_id,
                            block_height,
                            ..
                        }
                        | DaShardCursorError::MissingCursor {
                            lane_id,
                            shard_id,
                            block_height,
                        } => (
                            lane_id.as_u32(),
                            *shard_id,
                            i64::try_from(*block_height).unwrap_or(i64::MAX),
                        ),
                        DaShardCursorError::StaleCursor {
                            lane_id,
                            shard_id,
                            observed_height,
                            required_height,
                        } => (
                            lane_id.as_u32(),
                            *shard_id,
                            i64::try_from(required_height.saturating_sub(*observed_height))
                                .unwrap_or(i64::MAX),
                        ),
                        DaShardCursorError::UnknownLane {
                            lane_id,
                            block_height,
                        } => {
                            let shard_id = lane_config.shard_id(*lane_id);
                            (
                                lane_id.as_u32(),
                                shard_id,
                                i64::try_from(*block_height).unwrap_or(i64::MAX),
                            )
                        }
                    };
                    let reason = match err {
                        DaShardCursorError::Regression { .. } => "regression",
                        DaShardCursorError::MissingCursor { .. } => "missing_cursor",
                        DaShardCursorError::StaleCursor { .. } => "stale_cursor",
                        DaShardCursorError::UnknownLane { .. } => "unknown_lane",
                    };
                    self.telemetry.record_da_shard_cursor_event(
                        reason,
                        lane_id,
                        shard_id,
                        block_height,
                    );
                    record_da_shard_cursor_lag(&self.telemetry, lane_id, shard_id, lag_blocks);
                }
            }
        }
        result
    }
    /// Fixture adapter; production publication uses its already held cursor writer.
    #[cfg(test)]
    pub(crate) fn advance_da_receipt_cursors_from_bundle(
        &self,
        block_height: u64,
        records: &[iroha_data_model::da::commitment::DaCommitmentRecord],
    ) -> Result<(), DaReceiptCursorError> {
        let mut cursors = self.da_receipt_cursors.write();
        self.advance_da_receipt_cursors_into(&mut cursors, block_height, records.iter())
    }
    #[expect(
        single_use_lifetimes,
        reason = "stable Rust requires a named lifetime for borrowed impl Trait items"
    )]
    fn advance_da_receipt_cursors_into<'a>(
        &self,
        cursors: &mut DaReceiptCursorIndex,
        block_height: u64,
        records: impl ExactSizeIterator<Item = &'a DaCommitmentRecord>,
    ) -> Result<(), DaReceiptCursorError> {
        let result = cursors.record_bundle(block_height, records);
        #[cfg(feature = "telemetry")]
        {
            if let Ok(advanced) = &result {
                for (lane_epoch, sequence) in advanced {
                    self.telemetry.set_da_receipt_cursor(
                        lane_epoch.lane_id.as_u32(),
                        lane_epoch.epoch,
                        *sequence,
                    );
                }
            }
        }
        result.map(|_| ())
    }
    fn record_confidential_compute_into(
        store: &mut ConfidentialComputeStore,
        lane_config: &iroha_config::parameters::actual::LaneConfig,
        block_height: u64,
        records: &[iroha_data_model::da::commitment::DaCommitmentRecord],
        mut include: impl FnMut(&iroha_data_model::da::commitment::DaCommitmentRecord) -> bool,
    ) -> Result<(), ConfidentialComputeError> {
        for (idx, record) in records.iter().enumerate() {
            if !include(record) {
                continue;
            }
            let Some(index_in_bundle) = crate::da::da_bundle_location_index(idx) else {
                warn!(
                    height = block_height,
                    index = idx,
                    "skipping confidential-compute record with unrepresentable DA bundle location"
                );
                continue;
            };
            if let Some(policy) =
                crate::da::validate_confidential_compute_record(lane_config, record)?
            {
                let location = DaCommitmentLocation {
                    block_height,
                    index_in_bundle,
                };
                store.insert(record, location, policy);
            }
        }
        Ok(())
    }
