    /// Install or update a dataspace AXT policy entry.
    pub fn set_axt_policy(&mut self, dsid: DataSpaceId, mut policy: AxtPolicyEntry) {
        let previous_policy = self.world.axt_policies.view().get(&dsid).copied();
        let existing_counter = self.world.axt_handle_counters.view().get(&dsid).copied();
        let requested_counter = if policy.next_handle_counter == 0 {
            None
        } else {
            Some(
                AxtHandleCounterRecord::try_from_parts(
                    policy.next_handle_counter,
                    policy.active_handle_era,
                )
                .expect("explicit AXT policy counter must be non-zero"),
            )
        };
        // Once a durable ratchet exists, neither caller-supplied counter nor
        // era may replace it. The requested era is only a lower bound for an
        // authenticated identity transition below.
        let mut counter = existing_counter.or(requested_counter);
        let previous_was_active = previous_policy.as_ref().is_some_and(axt_policy_is_active);
        let next_is_active = axt_policy_is_active(&policy);
        let revokes_authority = previous_was_active || next_is_active && existing_counter.is_some();
        let raises_generation_floor = counter
            .as_ref()
            .is_some_and(|counter| policy.active_handle_era > counter.authorization_generation());
        if revokes_authority
            && (axt_policy_identity_changed(previous_policy.as_ref(), Some(&policy))
                || raises_generation_floor)
        {
            counter
                .as_mut()
                .expect("an authorized AXT policy must retain its permanent counter")
                .try_revoke_for_policy_transition(policy.active_handle_era)
                .expect("explicit AXT policy transition exhausted its permanent counter");
        }
        if policy.manifest_root != [0; 32] {
            assert!(
                counter.is_some(),
                "an active AXT policy requires a permanent non-zero counter ratchet"
            );
        }
        if let Some(counter) = counter {
            policy.next_handle_counter = counter.next();
            policy.active_handle_era = counter.authorization_generation();
            let mut block = self.world.axt_handle_counters.block();
            block.insert(dsid, counter);
            block.commit();
        } else {
            policy.next_handle_counter = 0;
        }
        let mut block = self.world.axt_policies.block();
        let mut tx = block.transaction();
        tx.insert(dsid, policy);
        tx.apply();
        block.commit();
    }
    /// Rebuild the committed AXT policy cache from Space Directory manifests and lane bindings.
    ///
    /// When the Space Directory is empty, existing explicit policies are preserved unless they
    /// target lanes that no longer exist in the current lane catalog.
    pub fn refresh_axt_policies_from_directory(&self) -> Option<AxtPolicySnapshot> {
        let view = self.view();
        let nexus = view.nexus.clone();
        let block_height = self.block_hashes.view().len() as u64;
        let valid_lanes = axt_cached_policy_retain_lane_ids_at_height(&nexus, block_height);
        let mut snapshot =
            crate::smartcontracts::ivm::host::CoreHost::derive_axt_policy_snapshot_from_directory(
                &view,
            );
        drop(view);
        let Some(snap) = snapshot.as_mut() else {
            let (has_directory_data, has_active_manifest) = {
                let manifests = self.world.space_directory_manifests.view();
                let bindings = self.world.uaid_dataspaces.view();
                let has_directory_data =
                    manifests.iter().next().is_some() || bindings.iter().next().is_some();
                let has_active_manifest = manifests
                    .iter()
                    .any(|(_, set)| set.iter().any(|(_, record)| record.is_active()));
                (has_directory_data, has_active_manifest)
            };
            if !has_directory_data || has_active_manifest {
                let mut block = self.world.axt_policies.block();
                let mut tx = block.transaction();
                let stale: Vec<_> = tx
                    .view()
                    .iter()
                    .filter(|(_, policy)| !valid_lanes.contains(&policy.target_lane))
                    .map(|(dsid, _)| *dsid)
                    .collect();
                if stale.is_empty() {
                    return None;
                }
                for dsid in stale {
                    tx.remove(dsid);
                }
                tx.apply();
                block.commit();
                return None;
            }
            let mut block = self.world.axt_policies.block();
            let mut tx = block.transaction();
            let stale: Vec<_> = tx.view().iter().map(|(dsid, _)| *dsid).collect();
            for dsid in stale {
                tx.remove(dsid);
            }
            tx.apply();
            block.commit();
            return None;
        };
        let existing_policies: BTreeMap<_, _> = self
            .world
            .axt_policies
            .view()
            .iter()
            .map(|(dsid, policy)| (*dsid, *policy))
            .collect();
        let durable_counters: BTreeMap<_, _> = self
            .world
            .axt_handle_counters
            .view()
            .iter()
            .map(|(dsid, record)| (*dsid, *record))
            .collect();
        let mut initial_counter_dsids = Vec::new();
        for binding in &mut snap.entries {
            if let Some(previous) = existing_policies.get(&binding.dsid)
                && previous.manifest_root == binding.policy.manifest_root
                && previous.target_lane == binding.policy.target_lane
            {
                binding.policy.active_handle_era = binding
                    .policy
                    .active_handle_era
                    .max(previous.active_handle_era);
            }
            if let Some(record) = durable_counters.get(&binding.dsid) {
                binding.policy.next_handle_counter = record.next();
                binding.policy.active_handle_era = record.authorization_generation();
            } else if binding.policy.manifest_root != [0; 32] {
                let initial = AxtHandleCounterRecord::initial(binding.policy.active_handle_era);
                binding.policy.next_handle_counter = initial.next();
                binding.policy.active_handle_era = initial.authorization_generation();
                initial_counter_dsids.push(binding.dsid);
            }
        }
        if !initial_counter_dsids.is_empty() {
            let mut block = self.world.axt_handle_counters.block();
            for dsid in initial_counter_dsids {
                let generation = snap
                    .entries
                    .iter()
                    .find(|binding| binding.dsid == dsid)
                    .map_or(0, |binding| binding.policy.active_handle_era);
                block.insert(dsid, AxtHandleCounterRecord::initial(generation));
            }
            block.commit();
        }
        let mut block = self.world.axt_policies.block();
        let mut tx = block.transaction();
        snap.version = AxtPolicySnapshot::compute_version(&snap.entries);
        let existing_keys: Vec<_> = tx.view().iter().map(|(dsid, _)| *dsid).collect();
        for dsid in existing_keys {
            tx.remove(dsid);
        }
        for binding in &snap.entries {
            tx.insert(binding.dsid, binding.policy);
        }
        tx.apply();
        block.commit();
        snapshot
    }
    #[cfg(test)]
    /// Remove a dataspace AXT policy entry.
    pub fn remove_axt_policy(&mut self, dsid: &DataSpaceId) {
        let previous_policy = self.world.axt_policies.view().get(dsid).copied();
        let existing_counter = self.world.axt_handle_counters.view().get(dsid).copied();
        if previous_policy.as_ref().is_some_and(axt_policy_is_active) {
            let mut counter = existing_counter.or_else(|| {
                previous_policy.and_then(|policy| {
                    AxtHandleCounterRecord::try_from_parts(
                        policy.next_handle_counter,
                        policy.active_handle_era,
                    )
                    .ok()
                })
            });
            counter
                .as_mut()
                .expect("an authorized AXT policy must retain its permanent counter")
                .try_revoke_for_policy_transition(0)
                .expect("explicit AXT policy removal exhausted its permanent counter");
            let mut counters = self.world.axt_handle_counters.block();
            counters.insert(*dsid, counter.expect("counter was initialized above"));
            counters.commit();
        }
        let mut block = self.world.axt_policies.block();
        block.remove(*dsid);
        block.commit();
    }
    /// Push a committed block hash when constructing scenarios in tests.
    ///
    /// The synthetic autoscale sample keeps the test state eligible for a
    /// canonical snapshot: production block commits always retain the same
    /// height/hash suffix, so a hash-only fixture must do so as well.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    pub fn push_block_hash_for_testing(&mut self, block_hash: HashOf<BlockHeader>) {
        let block_height = u64::try_from(self.block_hashes.committed_height())
            .unwrap_or(u64::MAX)
            .saturating_add(1);
        let mut block = self.block_hashes.block();
        block.push(block_hash);
        block.commit_for_tests();
        let history_cap = autoscale_sample_history_cap(&self.nexus_snapshot().autoscale);
        let mut runtime = self.canonical_runtime.block();
        let mut history: VecDeque<_> = runtime.autoscale_sample_history.iter().copied().collect();
        let baseline_timestamp_ms = block_height.saturating_mul(100).max(1);
        let creation_time_ms = history.back().map_or(baseline_timestamp_ms, |previous| {
            previous
                .creation_time_ms
                .saturating_add(1)
                .max(baseline_timestamp_ms)
        });
        append_autoscale_sample_record(
            &mut history,
            AutoscaleSampleRecord {
                block_height,
                block_hash,
                creation_time_ms,
                work_count: 0,
            },
            history_cap,
        );
        runtime.get_mut().autoscale_sample_history = history.into_iter().collect();
        runtime.commit();
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Latest committed block height recorded in the transactions storage (0 when empty).
    pub fn transactions_latest_height_for_testing(&self) -> usize {
        self.transactions.latest_height()
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Prune the AXT replay ledger using the provided slot and retention window (test helper).
    pub fn prune_axt_replay_ledger_for_tests(&mut self, current_slot: u64, retention_slots: u64) {
        let mut block = self.world.axt_replay_ledger.block();
        let expired: Vec<_> = block
            .iter()
            .filter(|(_, record)| record.is_expired(current_slot, retention_slots))
            .map(|(key, _)| *key)
            .collect();
        for key in expired {
            block.remove(key);
        }
        block.commit();
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Insert an AXT replay record (test helper).
    pub fn insert_axt_replay_entry_for_tests(
        &mut self,
        key: AxtHandleReplayKey,
        record: AxtReplayRecord,
    ) {
        let mut block = self.world.axt_replay_ledger.block();
        block.insert(key, record);
        block.commit();
    }
