    /// Prepare a deployed contract in the isolated Torii query cache.
    ///
    /// A cache hit trusts the content address established by world-state
    /// admission and therefore performs no artifact copy, hash, parse, or
    /// instruction decode. A miss recomputes and verifies the complete
    /// domain-separated artifact hash before publishing the prepared value.
    ///
    /// # Errors
    /// Returns [`ivm::VMError`] if `bytecode` is malformed or does not match
    /// `code_hash`.
    pub fn prepare_contract_query_program(
        &self,
        code_hash: Hash,
        bytecode: &[u8],
    ) -> Result<ProgramSummary, ivm::VMError> {
        self.contract_query_ivm_cache
            .lock()
            .summarize_program_with_hash(code_hash, bytecode)
    }
    #[cfg(test)]
    /// Return contract query summary and preparation counters.
    #[must_use]
    pub fn contract_query_ivm_cache_stats(&self) -> crate::smartcontracts::ivm::cache::CacheStats {
        self.contract_query_ivm_cache.lock().stats()
    }
    #[cfg(test)]
    /// Return prepared-artifact and owned-runtime counters for contract queries.
    #[must_use]
    pub fn contract_query_prepared_cache_stats(
        &self,
    ) -> crate::smartcontracts::ivm::cache::PreparedContractCacheStats {
        self.contract_query_ivm_cache
            .lock()
            .prepared_contract_cache()
            .stats()
    }
    /// Create a point-in-time snapshot tuned for query/IVM execution.
    ///
    /// This avoids taking the transactions index view and other full-snapshot
    /// components used by [`State::view`]. Its generation retry still captures
    /// the world and block-hash journal atomically because query cursors and
    /// finalized registry proofs bind both.
    #[track_caller]
    pub fn query_view(&self) -> StateQueryView<'_> {
        const STATE_QUERY_VIEW_LOG_THRESHOLD: Duration = Duration::from_millis(10);
        let caller = core::panic::Location::caller();
        let total_start = Instant::now();
        let (
            world,
            native_execution_tip,
            block_hashes,
            block_hashes_wait,
            world_wait,
            query_ledger_time_ms,
            projection,
            commit_topology,
            prev_commit_topology,
            commit_topology_wait,
            prev_commit_topology_wait,
        ) = loop {
            let generation_before = self.state_view_generation();
            if !generation_before.is_multiple_of(2) {
                self.note_view_generation_contention(caller);
                std::thread::yield_now();
                continue;
            }
            let block_hashes_start = Instant::now();
            let block_hashes = self.block_hashes.view();
            let block_hashes_wait = block_hashes_start.elapsed();
            let query_ledger_time_ms = self.latest_block_creation_time_ms_fast();
            let world_start = Instant::now();
            let mut world = self.world.view();
            let runtime = self.canonical_runtime.view();
            let native_execution_tip = self.native_execution_tip.view();
            let projection = self.project_canonical_runtime(runtime.get(), &world);
            let commit_topology_start = Instant::now();
            let commit_topology = self.commit_topology.view();
            let commit_topology_wait = commit_topology_start.elapsed();
            let prev_commit_topology_start = Instant::now();
            let prev_commit_topology = self.prev_commit_topology.view();
            let prev_commit_topology_wait = prev_commit_topology_start.elapsed();
            let world_wait = world_start.elapsed();
            let generation_after = self.state_view_generation();
            if is_stable_state_view_generation(generation_before, generation_after) {
                let projection =
                    projection.expect("persisted canonical runtime projection must be valid");
                world.dataspace_catalog = projection.nexus.dataspace_catalog.clone();
                break (
                    world,
                    native_execution_tip,
                    block_hashes,
                    block_hashes_wait,
                    world_wait,
                    query_ledger_time_ms,
                    projection,
                    commit_topology,
                    prev_commit_topology,
                    commit_topology_wait,
                    prev_commit_topology_wait,
                );
            }
            drop(world);
            self.note_view_generation_contention(caller);
            std::thread::yield_now();
        };
        let total_wait = total_start.elapsed();
        let (mut max_component, mut max_wait) = ("block_hashes", block_hashes_wait);
        if world_wait > max_wait {
            max_component = "world";
            max_wait = world_wait;
        }
        if commit_topology_wait > max_wait {
            max_component = "commit_topology";
            max_wait = commit_topology_wait;
        }
        if prev_commit_topology_wait > max_wait {
            max_component = "prev_commit_topology";
            max_wait = prev_commit_topology_wait;
        }
        if max_wait >= STATE_QUERY_VIEW_LOG_THRESHOLD {
            debug!(
                caller = %caller,
                max_component,
                max_wait_us = max_wait.as_micros(),
                total_wait_us = total_wait.as_micros(),
                block_hashes_wait_us = block_hashes_wait.as_micros(),
                world_wait_us = world_wait.as_micros(),
                commit_topology_wait_us = commit_topology_wait.as_micros(),
                prev_commit_topology_wait_us = prev_commit_topology_wait.as_micros(),
                "state query_view acquisition slow"
            );
        }
        StateQueryView {
            native_execution_tip,
            block_hashes,
            commit_topology,
            prev_commit_topology,
            ivm: &self.ivm,
            pipeline_ivm_prepared_cache: self.pipeline_ivm_prepared_cache.read().clone(),
            kura: &self.kura,
            query_handle: &self.query_handle,
            query_ledger_time_ms,
            accounts_snapshot_cache: SyncOnceCell::new(),
            #[cfg(feature = "telemetry")]
            telemetry: &self.telemetry,
            pipeline: crate::pipeline_validity_policy::effective_pipeline(
                self.pipeline.clone(),
                world.parameters.get(),
            ),
            oracle: self.oracle.clone(),
            crypto: self.crypto(),
            nexus: projection.nexus,
            lane_incarnations: projection.incarnations,
            lane_incarnation_activation_heights: projection.activation_heights,
            lane_manifests: projection.manifests,
            zk: crate::zk_validity_policy::effective_zk(self.zk.clone(), world.parameters()),
            content: self.content.clone(),
            chain_id: self.chain_id.clone(),
            network_id: self.network_id,
            world,
        }
    }
    /// Snapshot of the current commit topology.
    ///
    /// This avoids acquiring a full [`StateView`] when only validator ordering is needed.
    #[track_caller]
    pub fn commit_topology_snapshot(&self) -> Vec<PeerId> {
        self.commit_topology.view().iter().cloned().collect()
    }
    /// Snapshot of the previous commit topology.
    ///
    /// This avoids acquiring a full [`StateView`] when only the prior validator ordering is
    /// required.
    #[track_caller]
    pub fn prev_commit_topology_snapshot(&self) -> Vec<PeerId> {
        self.prev_commit_topology.view().iter().cloned().collect()
    }
    /// Authenticate a threshold-key lifecycle certificate for the contiguous next block.
    ///
    /// This admission check uses the committee World's consensus schedule holds for the next
    /// height (the same entry execution reads), never the mutable commit topology. Execution
    /// still checks the certificate again, including its exact height, session compare-and-set
    /// and replay protection.
    ///
    /// # Errors
    ///
    /// Rejects a chain without a committed parent, a next height without a scheduled committee,
    /// and any invalid network, height, roster or quorum binding. Returns the committed parent
    /// hash and roster so ingress can also require local ownership of the global control route.
    pub fn verify_next_height_threshold_key_lifecycle_certificate_v1(
        &self,
        certificate: &iroha_data_model::isi::consensus_keys::ThresholdKeyLifecycleCertificateV1,
    ) -> core::result::Result<(HashOf<BlockHeader>, Vec<PeerId>), String> {
        let (parent_hash, height, roster) = {
            let view = self.view();
            let parent_hash = view
                .latest_block_hash()
                .ok_or_else(|| "lifecycle admission requires a committed parent".to_owned())?;
            let height = u64::try_from(view.height())
                .ok()
                .and_then(|parent| parent.checked_add(1))
                .ok_or_else(|| "lifecycle execution height overflows".to_owned())?;
            let roster = threshold_key_lifecycle_roster_v1(view.world(), height)?;
            (parent_hash, height, roster)
        };
        verify_threshold_key_lifecycle_certificate_v1(
            certificate,
            self.network_id_ref(),
            height,
            &roster,
        )
        .map_err(|error| error.to_string())?;
        Ok((parent_hash, roster))
    }
    /// Latest committed block height derived from the block hash journal.
    ///
    /// This is cheaper than acquiring a full [`StateView`] and avoids locking
    /// world-state components.
    #[track_caller]
    pub fn committed_height(&self) -> usize {
        self.block_hashes.committed_height()
    }
    /// Wait until a stable State publication reaches at least `required_height`.
    ///
    /// The notification is only a wakeup: a fresh even generation and committed
    /// height establish readiness. Registering before sampling prevents a lost
    /// publication between the predicate and suspension. No State view or writer
    /// fence is retained while waiting. The caller owns its deadline, cancellation
    /// and all retained work; completion does not authenticate any certificate or
    /// authorize a durable write without reclassification.
    pub async fn wait_for_committed_height(&self, required_height: u64) {
        loop {
            let published = self.publication_notify.notified();
            tokio::pin!(published);
            published.as_mut().enable();
            let before = self.state_view_generation();
            let height = self.committed_height();
            let after = self.state_view_generation();
            if is_stable_state_view_generation(before, after)
                && u64::try_from(height).is_ok_and(|height| height >= required_height)
            {
                return;
            }
            published.await;
        }
    }
    /// Number of committed blocks durably indexed by Kura.
    ///
    /// This avoids acquiring a full [`StateView`] when callers only need to
    /// verify that the state height is backed by durable block storage.
    #[track_caller]
    ///
    /// # Errors
    /// Returns an error if canonical storage is poisoned, its commit marker or
    /// index cannot be read exactly, or the durable count does not fit `usize`.
    pub fn exact_durable_block_count(&self) -> crate::kura::Result<usize> {
        self.kura.exact_durable_blocks_count()
    }
    /// Load a committed block by height from Kura.
    ///
    /// This avoids acquiring a full [`StateView`] when only block retrieval is needed.
    #[track_caller]
    ///
    /// # Errors
    /// Returns an original local resource refusal if Kura cannot complete the read,
    /// or a canonical history error if the read fails or the returned body
    /// contradicts the committed hash or height.
    pub fn block_by_height(
        &self,
        height: NonZeroUsize,
    ) -> core::result::Result<
        Option<iroha_data_model::block::SharedSignedBlock>,
        crate::execution_attempt::ExecutionAttemptError<CanonicalHistoryError>,
    > {
        let Some(expected) = self.block_hashes.view().get(height.get() - 1).copied() else {
            return Ok(None);
        };
        committed_block_from_kura(&self.kura, height, expected, &self.ivm_execution_budget())
    }
    /// Load a committed block hash by height from Kura's durable index.
    ///
    /// This avoids loading the whole block when callers only need to verify
    /// that state and Kura agree on the latest durable block.
    #[track_caller]
    pub fn durable_block_hash(&self, height: NonZeroUsize) -> Option<HashOf<BlockHeader>> {
        self.kura.get_durable_block_hash(height)
    }
    /// Resolve a committed block height by block hash using Kura's index.
    ///
    /// This avoids acquiring a full [`StateView`] when only hash lookup is needed.
    #[track_caller]
    pub fn block_height_by_hash(&self, hash: HashOf<BlockHeader>) -> Option<NonZeroUsize> {
        let height = self.kura.get_block_height_by_hash(hash)?;
        (self.block_hashes.view().get(height.get() - 1) == Some(&hash)).then_some(height)
    }
    /// Load a committed block by hash from Kura.
    ///
    /// This avoids acquiring a full [`StateView`] when only hash-based block retrieval is needed.
    #[track_caller]
    ///
    /// # Errors
    /// Returns an original local resource refusal or canonical history error when
    /// the resolved block cannot be read or authenticated against the committed
    /// hash and height.
    pub fn block_by_hash(
        &self,
        hash: HashOf<BlockHeader>,
    ) -> core::result::Result<
        Option<iroha_data_model::block::SharedSignedBlock>,
        crate::execution_attempt::ExecutionAttemptError<CanonicalHistoryError>,
    > {
        match self.block_height_by_hash(hash) {
            Some(height) => self.block_by_height(height),
            None => Ok(None),
        }
    }
    /// Latest committed block header from the state cache.
    ///
    /// This avoids acquiring a full [`StateView`] when callers only need the
    /// latest committed header for contextual validation.
    #[track_caller]
    pub fn latest_block_header_fast(&self) -> Option<BlockHeader> {
        self.latest_block_header.read().clone()
    }
    /// Latest authenticated committed block creation time.
    ///
    /// Unlike [`StateReadOnly::latest_block`], this never loads or decodes a
    /// block body from Kura when a query needs only deterministic ledger time.
    /// The original authenticated native execution tip supplies missing cached headers.
    #[must_use]
    pub fn latest_block_creation_time_ms_fast(&self) -> Option<u64> {
        let latest_hash = self.latest_block_hash_fast();
        let cached_header = self.latest_block_header.read().clone();
        self.latest_block_creation_time_ms_from_header(latest_hash, cached_header.as_ref())
    }
    fn latest_block_creation_time_ms_from_header(
        &self,
        latest_hash: Option<HashOf<BlockHeader>>,
        cached_header: Option<&BlockHeader>,
    ) -> Option<u64> {
        let cached = cached_header
            .filter(|header| Some(header.hash()) == latest_hash)
            .map(|header| u64::try_from(header.creation_time().as_millis()).unwrap_or(u64::MAX));
        cached.or_else(|| {
            let tip = (*self.native_execution_tip.view().get())?;
            (Some(tip.iroha_hash()) == latest_hash
                && usize::try_from(tip.height()).ok() == Some(self.block_hashes.view().len()))
            .then_some(tip.creation_time_ms())
        })
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    #[expect(
        clippy::large_types_passed_by_value,
        reason = "the header is transferred into the committed-header cache"
    )]
    fn update_latest_block_header_cache(&self, header: BlockHeader) {
        *self.latest_block_header.write() = Some(header);
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Override the latest committed block-header cache in tests.
    pub fn update_latest_block_header_cache_for_tests(&self, header: BlockHeader) {
        self.update_latest_block_header_cache(header);
    }
    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Advance the test-only committed frontier with one contiguous block header.
    ///
    /// This updates only the block-hash journal and latest-header cache. It is
    /// intended for cross-crate admission tests that need a real
    /// [`StateReadOnly::height`] transition without constructing a full block.
    pub fn append_committed_block_header_for_tests(&self, header: BlockHeader) {
        let expected_height = u64::try_from(self.block_hashes.view().len())
            .unwrap_or(u64::MAX)
            .saturating_add(1);
        assert_eq!(
            header.height().get(),
            expected_height,
            "test block header must extend the committed frontier contiguously"
        );
        let mut _view_generation_notice = self.state_view_publication();
        let _view_generation = _view_generation_notice.begin();
        let mut block_hashes = self.block_hashes.block();
        block_hashes.push_for_tests(header.hash());
        block_hashes.commit_for_tests();
        self.update_latest_block_header_cache(header);
    }

    /// Produce a finalized Network input/full typed-output proof under explicit limits.
    ///
    /// Only the committed height/hash journal is captured around storage I/O;
    /// no full World view is held while authenticating bytes or constructing proofs.
    /// # Errors
    /// Rejects absent committed heights, unauthenticated storage, invalid complete
    /// source/output joins, absent outer input identities, or exceeded serving limits.
    #[track_caller]
    pub fn block_proofs_for_entry(
        &self,
        block_height: NonZeroU64,
        entry_hash: HashOf<TransactionEntrypoint>,
        limits: BlockProofLimits,
    ) -> Result<BlockProofs, BlockProofError> {
        let expected_hash = self.committed_block_hash_for_proof(block_height)?;
        let hashes = self.block_hashes.view();
        let source = block_proofs::NativeProofSource {
            kura: &self.kura,
            chain_id: self.chain_id_ref(),
            network: *self.network_id_ref(),
            hashes: &hashes,
            budget: &self.ivm_execution_budget(),
        };
        let proof = block_proofs_for_entry_from_kura(
            source,
            block_height,
            expected_hash,
            entry_hash,
            limits,
        )?;
        self.recheck_committed_block_hash_for_proof(block_height, expected_hash)?;
        Ok(proof)
    }

    /// Read the original QC-authenticated executed block wire for proof transport.
    ///
    /// Admits its signed size before any body read and checks the full output
    /// structure. The returned bytes are the exact authenticated storage bytes.
    /// # Errors
    /// Rejects unavailable or corrupt finalized bodies and exceeded read/work/response limits.
    pub fn executed_block_wire(
        &self,
        block_height: NonZeroU64,
        limits: BlockProofLimits,
    ) -> Result<crate::kura::NativeFrameBytes, BlockProofError> {
        let expected_hash = self.committed_block_hash_for_proof(block_height)?;
        let hashes = self.block_hashes.view();
        let source = block_proofs::NativeProofSource {
            kura: &self.kura,
            chain_id: self.chain_id_ref(),
            network: *self.network_id_ref(),
            hashes: &hashes,
            budget: &self.ivm_execution_budget(),
        };
        let wire = executed_block_wire_from_kura(source, block_height, expected_hash, limits)?;
        self.recheck_committed_block_hash_for_proof(block_height, expected_hash)?;
        Ok(wire)
    }

    /// Project the signer and explicit KAGEMUSHA Activate/Unload attempts (with each Unload
    /// claim's paid account) of one committed External Network input, for an account-scoped
    /// ledger-finality route filter.
    ///
    /// The body is read through the checkpoint-resumed native authenticator (as
    /// [`Self::read_executed_carrier_from_checkpoints`] reads) under the five explicit
    /// [`BlockProofLimits`], with source frames, their decoding and the Activate/Unload shape
    /// decodes charged to `read_budget`. No Merkle path is built and no output is copied. The
    /// projection is DATA, never finality authority. Source work depends on node-local
    /// checkpoints, so on-chain readers must not use it.
    /// # Errors
    /// Rejects absent or replaced committed history, an unauthenticated or invalid body and
    /// exceeded limits, all before building paths. Genesis and a sealed input carry no
    /// attempt and are refused as [`BlockProofError::EntrypointNotFound`]. A local decoder
    /// refusal of an Activate or Unload frame stays [`BlockProofError::Deferred`].
    #[track_caller]
    pub fn kagemusha_ledger_entry_owner(
        &self,
        block_height: NonZeroU64,
        entry_hash: HashOf<TransactionEntrypoint>,
        limits: BlockProofLimits,
        read_budget: &CanonicalHistoryReadBudget,
    ) -> Result<KagemushaLedgerEntryOwnerV1, BlockProofError> {
        let block = self.kagemusha_ledger_body(block_height, entry_hash, limits, read_budget)?;
        // Activate/Unload shape decodes are charged to the same request decoder allowance.
        read_budget
            .with(|| kagemusha_ledger_entry_owner_from_body(&block, block_height, entry_hash))
    }

    /// Read the selective inclusion of one committed External Network input whose owner
    /// projection `admit` accepts: its entry path, joined complete Network output and output
    /// path.
    ///
    /// The body is read as [`Self::kagemusha_ledger_entry_owner`] reads it. An owner that
    /// `admit` refuses answers `None` before any path is built or any output is copied. The
    /// response limit bounds the inclusion frame before its output row is copied.
    /// # Errors
    /// Rejects what [`Self::kagemusha_ledger_entry_owner`] rejects, a missing output join, or
    /// an inclusion frame above the response limit.
    #[track_caller]
    pub fn kagemusha_ledger_inclusion_for_entry(
        &self,
        block_height: NonZeroU64,
        entry_hash: HashOf<TransactionEntrypoint>,
        limits: BlockProofLimits,
        read_budget: &CanonicalHistoryReadBudget,
        admit: impl FnOnce(&KagemushaLedgerEntryOwnerV1) -> bool,
    ) -> Result<Option<KagemushaLedgerEntryInclusionV1>, BlockProofError> {
        let block = self.kagemusha_ledger_body(block_height, entry_hash, limits, read_budget)?;
        read_budget.with(|| {
            kagemusha_ledger_inclusion_for_entry_from_body(
                &block,
                block_height,
                entry_hash,
                limits,
                admit,
            )
        })
    }

    /// One committed body for the KAGEMUSHA ledger reads, bound to this State's captured hash
    /// journal and native execution tip, and rechecked against the journal afterwards.
    fn kagemusha_ledger_body(
        &self,
        block_height: NonZeroU64,
        entry_hash: HashOf<TransactionEntrypoint>,
        limits: BlockProofLimits,
        read_budget: &CanonicalHistoryReadBudget,
    ) -> Result<iroha_data_model::block::SharedSignedBlock, BlockProofError> {
        // Genesis carries no wallet attempt and has no compact certificate: read nothing.
        if block_height == NonZeroU64::MIN {
            return Err(BlockProofError::EntrypointNotFound {
                entry_hash,
                block_height,
            });
        }
        let expected_hash = self.committed_block_hash_for_proof(block_height)?;
        // Capture only the immutable journal and opaque native tip within one publication
        // interval, as `read_executed_carrier_from_checkpoints` does.
        let (hashes, tip) = loop {
            let before = self.state_view_generation();
            if !before.is_multiple_of(2) {
                std::thread::yield_now();
                continue;
            }
            let hashes = self.block_hashes.view();
            let tip = *self.native_execution_tip.view().get();
            if is_stable_state_view_generation(before, self.state_view_generation()) {
                break (hashes, tip);
            }
            drop(hashes);
            std::thread::yield_now();
        };
        let history =
            CanonicalHistorySource::new(&self.kura, &hashes, tip, read_budget.frames().clone());
        let block = read_checkpointed_body(
            &self.kura,
            history,
            block_height,
            expected_hash,
            limits,
            read_budget,
        )?;
        self.recheck_committed_block_hash_for_proof(block_height, expected_hash)?;
        Ok(block)
    }

    /// Read one complete native execution for an off-chain reader, starting the
    /// authenticating walk at the nearest verified history checkpoint instead of
    /// signed genesis (see
    /// [`read_executed_carrier_from_checkpoints`](crate::smartcontracts::isi::tx::read_executed_carrier_from_checkpoints)).
    /// Source work depends on node-local checkpoints: on-chain readers must use
    /// [`Self::read_finalized_execution_carrier`].
    /// # Errors
    /// Rejects absent/replaced canonical history, invalid body/cache, or exceeded limits.
    pub fn read_executed_carrier_from_checkpoints(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
        read_budget: &CanonicalHistoryReadBudget,
    ) -> Result<
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrier,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        use iroha_data_model::query::error::QueryExecutionFail;
        if max_work == 0 || max_bytes == 0 {
            return Err(QueryExecutionFail::GasBudgetExceeded.into());
        }
        // Capture only the actual immutable journal and opaque executed tip. No World,
        // transactions or configuration view crosses the storage/crypto handoff. The same
        // publication interval binds this immutable history cut before any source I/O.
        let (hashes, tip) = loop {
            let before = self.state_view_generation();
            if !before.is_multiple_of(2) {
                std::thread::yield_now();
                continue;
            }
            let hashes = self.block_hashes.view();
            let tip = *self.native_execution_tip.view().get();
            if is_stable_state_view_generation(before, self.state_view_generation()) {
                break (hashes, tip);
            }
            drop(hashes);
            std::thread::yield_now();
        };
        let expected = hashes.get(height.get() - 1).copied();
        let source =
            CanonicalHistorySource::new(&self.kura, &hashes, tip, read_budget.frames().clone());
        let carrier = crate::smartcontracts::isi::tx::read_executed_carrier_from_checkpoints(
            source,
            height,
            max_work,
            max_bytes,
            read_budget,
        )?;
        if self.block_hashes.view().get(height.get() - 1).copied() != expected {
            return Err(QueryExecutionFail::Conversion(
                "canonical carrier changed during finalized read".into(),
            )
            .into());
        }
        Ok(carrier)
    }

    /// Read an authenticated canonical summary source in the caller's original cold owner.
    /// Unlike execution projections this checks only the committed header hash and height.
    ///
    /// # Errors
    /// Preserves original capacity refusal, absent body, corruption and header substitution.
    pub fn read_canonical_history_block(
        &self,
        height: NonZeroUsize,
        read_budget: &CanonicalHistoryReadBudget,
    ) -> Result<
        iroha_data_model::block::SharedSignedBlock,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        read_budget.with(|| {
            self.view()
                .canonical_history()
                .with_read_budget(read_budget)
                .block_with_admission(height, |_, _| Ok(()))
        })
    }

    /// Read one complete finalized execution carrier without holding a World view.
    ///
    /// Captures only the canonical height/hash journal before I/O and rechecks
    /// that binding afterwards. Wire and source/output work limits are explicit;
    /// this read has no proof protocol's separate response-size ceiling.
    /// # Errors
    /// Rejects absent/replaced canonical history, invalid finality/body/cache, or exceeded limits.
    pub fn read_finalized_execution_carrier(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
    ) -> Result<
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrier,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        self.read_finalized_execution_carrier_in_pool(
            height,
            max_work,
            max_bytes,
            &self.ivm_execution_budget(),
        )
    }

    /// Begin one durable off-chain finalized read in the original State execution pool.
    ///
    /// The returned operation retains its immutable hash generation and physical
    /// frame/prefix across local refusal. Ordinary one-shot request readers remain
    /// unchanged; dropping this owner cancels its read without publishing authority.
    /// # Errors
    /// Rejects absent history or the same finite source admission required by the
    /// ordinary finalized-carrier reader before body I/O.
    pub fn begin_finalized_execution_carrier_read(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
    ) -> Result<
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrierReadAttempt<'_>,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrierReadAttempt::new(
            self,
            &self.kura,
            self.block_hashes.view(),
            height,
            max_work,
            max_bytes,
        )
    }

    /// Read one block-event execution under its original finite State source owner.
    ///
    /// This off-chain event projection does not authorize State mutation or deterministic
    /// instruction metering. It preserves the caller's work/byte limits and original
    /// execution pool; genesis results still require their actual H2 successor. Both
    /// captures are one-shot: an active/changed publication returns its original release
    /// observation rather than waiting inside the single event consumer.
    /// # Errors
    /// Preserves original State capture refusal, local execution refusal and canonical rejection.
    pub fn read_finalized_event_carrier(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
    ) -> Result<crate::smartcontracts::isi::tx::FinalizedExecutionCarrier, FinalizedEventReadError>
    {
        #[cfg(all(test, sumeragi_core_mutation = "HC201"))]
        return self
            .read_finalized_execution_carrier(height, max_work, max_bytes)
            .map_err(Into::into);
        #[cfg(not(all(test, sumeragi_core_mutation = "HC201")))]
        self.read_finalized_event_carrier_after_read(height, max_work, max_bytes, || {})
    }

    // This probe is used only by deterministic tests at the real post-I/O boundary.
    // The production caller supplies no callback, owner, source or visibility hint.
    fn read_finalized_event_carrier_after_read(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
        after_read: impl FnOnce(),
    ) -> Result<crate::smartcontracts::isi::tx::FinalizedExecutionCarrier, FinalizedEventReadError>
    {
        use iroha_data_model::query::error::QueryExecutionFail;
        if max_work == 0 || max_bytes == 0 {
            return Err(QueryExecutionFail::GasBudgetExceeded.into());
        }
        let budget = self.ivm_execution_budget();
        // Every physical hash guard ends before original-pool refund callbacks run.
        budget.with_deferred_refund_notifications(|_| {
            let mut releases = self.block_hashes.reader_release_batch();
            let (hashes, tip) = self.try_event_source(&mut releases, || {})?;
            let expected = hashes.get(height.get() - 1).copied().ok_or_else(|| {
                QueryExecutionFail::Conversion("canonical carrier height is unavailable".into())
            })?;
            let carrier = if height.get() <= 2 {
                // Same G1/H2 verifier and same pool; use the captured original journal
                // instead of entering a second blocking State reader on this event path.
                crate::smartcontracts::isi::tx::read_finalized_execution_carrier(
                    &self.kura,
                    self.chain_id_ref(),
                    *self.network_id_ref(),
                    &hashes,
                    height,
                    expected,
                    max_work,
                    max_bytes,
                    &budget,
                )?
            } else {
                let source = CanonicalHistorySource::new(&self.kura, &hashes, tip, budget.clone());
                crate::smartcontracts::isi::tx::read_finalized_event_carrier(
                    source,
                    &self.kura,
                    self.chain_id_ref(),
                    *self.network_id_ref(),
                    height,
                    expected,
                    max_work,
                    max_bytes,
                )?
            };
            // A new stable tip may append while I/O runs. Keep the target's current
            // membership check, but never spin or hide an active/changed writer here.
            after_read();
            let mut current_releases = self.block_hashes.reader_release_batch();
            let (current_hashes, _) = self.try_event_source(&mut current_releases, || {})?;
            if current_hashes.get(height.get() - 1).copied() != Some(expected) {
                return Err(QueryExecutionFail::Conversion(
                    "canonical carrier changed during finalized event read".into(),
                )
                .into());
            }
            Ok(carrier)
        })
    }

    // Existing physical reader acquisition owns both release notices. The test probe
    // runs at the real capture boundary; ordinary callers install no callback or source.
    fn try_event_source<'state>(
        &'state self,
        releases: &mut Option<iroha_allocation::release::DeferredReleaseBatch>,
        after_capture: impl FnOnce(),
    ) -> Result<(BlockHashesView<'state>, Option<NativeExecutionTip>), StateViewError> {
        #[cfg(all(test, sumeragi_core_mutation = "HC202"))]
        {
            let mut after_capture = Some(after_capture);
            loop {
                let generation = self.state_view_generation();
                if generation % 2 != 0 {
                    std::thread::yield_now();
                    continue;
                }
                let hashes = self.block_hashes.try_view_retaining(releases)?;
                let tip = *self.native_execution_tip.view().get();
                if let Some(probe) = after_capture.take() {
                    probe();
                }
                if is_stable_state_view_generation(generation, self.state_view_generation()) {
                    return Ok((hashes, tip));
                }
                drop(hashes);
                std::thread::yield_now();
            }
        }
        #[cfg(not(all(test, sumeragi_core_mutation = "HC202")))]
        {
            let release = self.state_write_lock.observe_release();
            let generation = self.state_view_generation();
            if !generation.is_multiple_of(2) {
                return Err(StateViewError::Busy(release));
            }
            let hashes = self.block_hashes.try_view_retaining(releases)?;
            let tip = *self.native_execution_tip.view().get();
            after_capture();
            if !is_stable_state_view_generation(generation, self.state_view_generation()) {
                return Err(StateViewError::Busy(release));
            }
            Ok((hashes, tip))
        }
    }

    /// Read the complete signed-genesis prefix under an off-chain caller's original owner.
    ///
    /// Unlike a checkpoint walk, a G1 execution requires its actual H2 successor. The
    /// synchronous scope retains the caller's cumulative decoder work and physical frame
    /// pool through the returned carrier; it grants no query admission or State mutation.
    /// # Errors
    /// Preserves original local refusal, missing/substituted history and finite read limits.
    pub fn read_finalized_execution_carrier_with_read_budget(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
        read_budget: &CanonicalHistoryReadBudget,
    ) -> Result<
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrier,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        read_budget.with(|| {
            #[cfg(all(test, sumeragi_core_mutation = "HC184"))]
            let budget = self.ivm_execution_budget();
            #[cfg(all(test, sumeragi_core_mutation = "HC184"))]
            let pool = &budget;
            #[cfg(not(all(test, sumeragi_core_mutation = "HC184")))]
            let pool = read_budget.frames();
            self.read_finalized_execution_carrier_in_pool(height, max_work, max_bytes, pool)
        })
    }

    // One unchanged full-prefix source/error kernel serves the deterministic execution
    // owner and the explicitly admitted off-chain owner. Neither substitutes for the other.
    fn read_finalized_execution_carrier_in_pool(
        &self,
        height: NonZeroUsize,
        max_work: u64,
        max_bytes: u64,
        budget: &iroha_allocation::AllocationBudget,
    ) -> Result<
        crate::smartcontracts::isi::tx::FinalizedExecutionCarrier,
        crate::execution_attempt::ExecutionAttemptError<
            iroha_data_model::query::error::QueryExecutionFail,
        >,
    > {
        use iroha_data_model::query::error::QueryExecutionFail;
        if max_work == 0 || max_bytes == 0 {
            return Err(QueryExecutionFail::GasBudgetExceeded.into());
        }
        let hashes = self.block_hashes.view();
        let expected = hashes.get(height.get() - 1).copied().ok_or_else(|| {
            QueryExecutionFail::Conversion("canonical carrier height is unavailable".into())
        })?;
        let carrier = crate::smartcontracts::isi::tx::read_finalized_execution_carrier(
            &self.kura,
            self.chain_id_ref(),
            *self.network_id_ref(),
            &hashes,
            height,
            expected,
            max_work,
            max_bytes,
            budget,
        )?;
        if self.block_hashes.view().get(height.get() - 1).copied() != Some(expected) {
            return Err(QueryExecutionFail::Conversion(
                "canonical carrier changed during finalized read".into(),
            )
            .into());
        }
        Ok(carrier)
    }

    fn committed_block_hash_for_proof(
        &self,
        block_height: NonZeroU64,
    ) -> Result<HashOf<BlockHeader>, BlockProofError> {
        let height_index = usize::try_from(block_height.get())
            .map_err(|_| BlockProofError::HeightOutOfRange(block_height))?;
        self.block_hashes
            .view()
            .get(height_index - 1)
            .copied()
            .ok_or(BlockProofError::BlockNotFound(block_height))
    }

    fn recheck_committed_block_hash_for_proof(
        &self,
        block_height: NonZeroU64,
        expected: HashOf<BlockHeader>,
    ) -> Result<(), BlockProofError> {
        let actual = self.committed_block_hash_for_proof(block_height)?;
        if actual != expected {
            return Err(BlockProofError::BlockHashMismatch {
                block_height,
                expected,
                actual,
            });
        }
        Ok(())
    }
    /// Return whether an enabled, non-depleted time trigger remains reachable after
    /// `parent_creation_time` and therefore needs ledger-clock progress.
    ///
    /// This avoids acquiring a full [`StateView`] on consensus hot paths that only need
    /// to decide whether an otherwise idle block is required for trigger scheduling.
    #[track_caller]
    pub fn time_trigger_clock_progress_required_fast(
        &self,
        parent_creation_time: Duration,
    ) -> bool {
        let world = self.world_view();
        world.triggers().time_triggers().iter().any(|(_, action)| {
            time_trigger_action_requires_clock_progress(action, parent_creation_time)
        })
    }
    #[cfg(test)]
    /// Check if any time triggers should fire for a block with the given header.
    ///
    /// This avoids acquiring a full [`StateView`] on consensus hot paths that only need
    /// trigger readiness.
    #[track_caller]
    pub fn time_triggers_due_for_block_fast(&self, block_header: &BlockHeader) -> bool {
        let to = block_header.creation_time();
        let since = self
            .latest_block_header_fast()
            .map_or(to, |latest_header| latest_header.creation_time());
        let (since, length) = to.checked_sub(since).map_or_else(
            || {
                warn!(
                    prev_time_ms = since.as_millis(),
                    block_time_ms = to.as_millis(),
                    "Block creation time regressed; clamping time interval to zero."
                );
                (to, Duration::ZERO)
            },
            |length| (since, length),
        );
        let interval = TimeInterval::new(since, length);
        let event = TimeEvent { interval };
        let current_block_height = block_header.height().get();
        let current_block_time_ms =
            u64::try_from(block_header.creation_time().as_millis()).unwrap_or(u64::MAX);
        let world = self.world_view();
        world.triggers().time_triggers().iter().any(|(_, action)| {
            crate::smartcontracts::triggers::set::time_trigger_action_is_due(
                action,
                &event,
                current_block_height,
                current_block_time_ms,
            )
        })
    }
    /// Latest committed block hash derived from the block hash journal.
    ///
    /// This is cheaper than acquiring a full [`StateView`] and avoids locking
    /// world-state components.
    #[track_caller]
    pub fn latest_block_hash_fast(&self) -> Option<HashOf<BlockHeader>> {
        self.block_hashes.view().last().copied()
    }
    #[cfg(test)]
    /// Previous committed block hash (if any) derived from the block hash journal.
    ///
    /// This is cheaper than acquiring a full [`StateView`] and avoids locking
    /// world-state components.
    #[track_caller]
    pub fn prev_block_hash_fast(&self) -> Option<HashOf<BlockHeader>> {
        self.block_hashes.view().iter().nth_back(1).copied()
    }
    /// Whether a canonical carrier or sealed signed-execution replay identity is committed.
    ///
    /// This avoids acquiring a full [`StateView`] when only committed-entrypoint
    /// membership is required.
    #[track_caller]
    pub fn has_committed_entrypoint(&self, hash: HashOf<TransactionEntrypoint>) -> bool {
        self.transactions.view().get(&hash).is_some()
    }
    /// Return the transaction admission limits used by ingress validation.
    ///
    /// This avoids acquiring a full [`WorldView`] when transaction admission only
    /// needs current Sumeragi clock drift and transaction limit parameters.
    #[track_caller]
    #[must_use]
    pub fn transaction_admission_limits(
        &self,
    ) -> (
        Duration,
        iroha_data_model::parameter::system::TransactionParameters,
    ) {
        let params = self.world.parameters.view();
        (params.sumeragi().max_clock_drift(), params.transaction())
    }
    #[cfg(test)]
    /// Warm the block stateless-validation cache for a Torii batch with one cache lock.
    #[doc(hidden)]
    #[track_caller]
    pub fn warm_stateless_validation_cache_for_torii_prechecked_batch<'iter, 'tx, I>(&self, txs: I)
    where
        'tx: 'iter,
        I: IntoIterator<Item = &'iter crate::tx::AcceptedTransaction<'tx>>,
    {
        self.warm_stateless_validation_cache_for_torii_prechecked_entries(txs);
    }
    #[cfg(test)]
    fn warm_stateless_validation_cache_for_torii_prechecked_entries<'iter, 'tx, I>(&self, txs: I)
    where
        'tx: 'iter,
        I: IntoIterator<Item = &'iter crate::tx::AcceptedTransaction<'tx>>,
    {
        let cache_cap = self.pipeline.stateless_cache_cap;
        if cache_cap == 0 {
            return;
        }
        let (max_clock_drift, tx_params) = self.transaction_admission_limits();
        let max_clock_drift_ms = max_clock_drift.as_millis();
        let entries = txs
            .into_iter()
            .filter_map(|tx| stateless_validation_cache_warm_entry(tx, max_clock_drift_ms))
            .collect::<Vec<_>>();
        if entries.is_empty() {
            return;
        }
        let allowed_signing = self.crypto.read().allowed_signing.clone();
        let context = StatelessValidationContext::new(
            self.network_id,
            u64::try_from(max_clock_drift_ms).unwrap_or(u64::MAX),
            tx_params,
            allowed_signing,
        );
        let mut cache = self.stateless_validation_cache.lock();
        cache.set_cap(cache_cap);
        cache.ensure_context(context);
        for entry in entries {
            cache.insert_ok(entry.key, entry.expires_at_ms, entry.not_before_ms);
        }
    }
    /// Block cadence frozen into the Sumeragi height profile.
    #[track_caller]
    #[must_use]
    pub fn sumeragi_block_cadence(&self) -> Duration {
        self.world.parameters.view().sumeragi().block_cadence()
    }
    /// Return whether the canonical account exists in current world state.
    ///
    /// This avoids constructing a full [`WorldView`] for Torii admission checks
    /// that only need account membership.
    #[track_caller]
    #[must_use]
    pub fn has_account(&self, account_id: &AccountId) -> bool {
        self.world.accounts.view().get(account_id).is_some()
    }
    /// Committed block height for an entrypoint identity, if present in the index.
    ///
    /// This avoids acquiring a full [`StateView`] when only the entrypoint index
    /// lookup is required.
    #[track_caller]
    pub fn committed_entrypoint_height(
        &self,
        hash: &HashOf<TransactionEntrypoint>,
    ) -> Option<NonZeroUsize> {
        self.transactions.view().get(hash)
    }
    /// Borrow the configured chain identifier.
    ///
    /// This avoids acquiring a full [`StateView`] when only the chain id is needed.
    #[must_use]
    pub fn chain_id_ref(&self) -> &iroha_model_base::chain::ChainId {
        &self.chain_id
    }
    /// Borrow the exact genesis-derived transaction security domain.
    #[must_use]
    pub const fn network_id_ref(&self) -> &iroha_data_model::NetworkId {
        &self.network_id
    }
    /// Snapshot the current ZK verification settings.
    ///
    /// This avoids acquiring a full [`StateView`] when only verifier settings are needed.
    /// Validity-affecting values come from the committed ZK validity policy
    /// ([`crate::zk_validity_policy::ZkValidityPolicyV1`]) when the chain installed
    /// one; the installed value contributes local resource settings.
    #[must_use]
    #[track_caller]
    pub fn zk_snapshot(&self) -> iroha_config::parameters::actual::Zk {
        crate::zk_validity_policy::effective_zk(self.zk.clone(), &self.world.parameters.view())
    }
    /// Borrow the ZK settings installed in this State.
    ///
    /// The value holds the local resource settings of this node (verifier
    /// workers and queues, wall-clock budgets, FASTPQ prover settings). Its
    /// validity values are the protocol default, or what a test fixture
    /// installed, and are not what validation reads: use [`Self::zk_snapshot`],
    /// a view or a block for those. The field itself is private, so
    /// [`Self::install_node_zk`] and the test-only installers are its only
    /// writers.
    #[must_use]
    pub const fn installed_zk(&self) -> &iroha_config::parameters::actual::Zk {
        &self.zk
    }
    /// Borrow the pipeline settings installed in this State.
    ///
    /// The value holds the local resource settings of this node (workers,
    /// caches, tracing, accelerator selection and signature batching). Its fee
    /// policy is not an authority; effective fees come from committed parameters.
    /// Its execution limits are the protocol default, or what a test
    /// fixture installed, and are not what validation reads: use
    /// [`Self::pipeline_snapshot`], a view or a block for those. The field
    /// itself is private, so [`Self::install_node_pipeline`] and the test-only
    /// installer are its only writers.
    #[must_use]
    pub const fn installed_pipeline(&self) -> &iroha_config::parameters::actual::Pipeline {
        &self.pipeline
    }
    /// Worker pool sized by the installed pipeline, shared by every block validation.
    ///
    /// Reusing one pool keeps workers (and their thread-local verification caches)
    /// warm instead of spawning and joining threads for each block.
    pub(crate) const fn pipeline_parallelism(&self) -> &PipelineParallelism {
        &self.pipeline_parallelism
    }
    /// Snapshot the current pipeline settings.
    ///
    /// This avoids acquiring a full [`StateView`] when only query/pipeline limits are needed.
    /// Validity-affecting values come from the committed pipeline validity policy
    /// ([`crate::pipeline_validity_policy::PipelineValidityPolicyV1`]) when the chain
    /// installed one; the installed value contributes local resource settings.
    #[must_use]
    pub fn pipeline_snapshot(&self) -> iroha_config::parameters::actual::Pipeline {
        crate::pipeline_validity_policy::effective_pipeline(
            self.pipeline.clone(),
            &self.world.parameters.view(),
        )
    }
    /// Snapshot the effective cycle ceiling for newly admitted IVM programs.
    ///
    /// Both the committed pipeline validity policy and the governance-controlled
    /// smart-contract fuel parameter are consensus-visible admission limits, so
    /// producers must embed the lower value in generated program headers.
    #[must_use]
    pub fn ivm_admission_cycle_limit(&self) -> NonZeroU64 {
        let parameters = self.world.parameters.view();
        let fuel = parameters.smart_contract().fuel();
        // The committed pipeline validity policy decides the ceiling, as in
        // every view and block.
        let ceiling =
            crate::pipeline_validity_policy::effective_pipeline(self.pipeline.clone(), &parameters)
                .ivm_max_cycles_upper_bound;
        NonZeroU64::new(ceiling.get().min(fuel.get())).expect("both IVM cycle limits are non-zero")
    }
