    /// Retain notification before acquiring publication writers and fences.
    #[inline]
    fn state_view_publication(&self) -> StateViewPublication<'_> {
        StateViewPublication::new(&self.view_generation, &self.publication_notify)
    }
    /// Observe the actual publisher before a compound read of this original State.
    pub(crate) fn view_publication_release(&self) -> iroha_allocation::release::ReleaseWait {
        self.state_write_lock.observe_release()
    }
    #[inline]
    pub(crate) fn state_view_generation(&self) -> u64 {
        self.view_generation.load(Ordering::Acquire)
    }
    /// Exclude committed State publication while consensus consumes a
    /// generation-bound validation result and performs its private-key action.
    #[cfg(test)]
    pub(crate) fn consensus_publication_lease(&self) -> PublicationGuard<'_> {
        self.state_commit_lock.lock()
    }
    /// Exclude committed publication only for the gateway's final synchronous capture handoff.
    /// Native proof/Kura reads, network waits and callback reconciliation must precede this lease.
    pub(crate) fn stream_token_gateway_publication_lease(&self) -> PublicationGuard<'_> {
        self.state_commit_lock.lock()
    }
    /// Exclude publication only while consuming an exact current Musubi inventory readback.
    /// Native proof and Kura reads precede this lease; it exposes no Queue or signing authority.
    pub(crate) fn musubi_pin_outbox_publication_lease(&self) -> PublicationGuard<'_> {
        self.state_commit_lock.lock()
    }
    #[inline]
    fn note_view_generation_contention(&self, caller: &'static core::panic::Location<'static>) {
        let now = Instant::now();
        let suppressed = self
            .view_lock_contention_log
            .lock()
            .should_emit(now, STATE_VIEW_LOCK_CONTENTION_WARN_COOLDOWN);
        if let Some(suppressed_since_last) = suppressed {
            warn!(
                caller = %caller,
                suppressed_since_last,
                cooldown_ms = STATE_VIEW_LOCK_CONTENTION_WARN_COOLDOWN.as_millis(),
                "state view generation contended; retrying snapshot"
            );
        }
    }
    /// Create point in time view of [`State`]
    #[track_caller]
    pub fn view(&self) -> StateView<'_> {
        self.try_view()
            .expect("persisted canonical runtime projection must be valid")
    }
    /// Acquire one generation-bound view, validating its runtime/World projection.
    ///
    /// # Errors
    /// Returns the exact runtime projection error after the captured generation
    /// is stable. Recovery and read-only API callers can reject malformed state
    /// without deriving a partial view or substituting configured runtime values.
    #[track_caller]
    pub fn try_view(&self) -> Result<StateView<'_>, LaneLifecycleError> {
        loop {
            match self.try_view_once() {
                Ok(view) => return Ok(view),
                Err(StateViewError::Busy(_)) => {}
                Err(StateViewError::Runtime(error)) => return Err(error),
                Err(error) => return Err(LaneLifecycleError::Storage(error.to_string())),
            }
            self.note_view_generation_contention(core::panic::Location::caller());
            std::thread::yield_now();
        }
    }
    /// Attempt one complete nonblocking view acquisition with the original retry source.
    ///
    /// # Errors
    /// Returns the exact original release observation when busy. Stable malformed
    /// runtime, changed custody and poisoned reader ownership remain terminal errors.
    /// Callers retain their own absolute deadlines; this method never retries.
    #[track_caller]
    pub fn try_view_once(&self) -> Result<StateView<'_>, StateViewError> {
        StateViewReleases::new(self).try_view_once()
    }
    #[track_caller]
    fn try_view_once_with_index_releases(
        &self,
        releases: &mut LaneLifecycleReleases<'_>,
    ) -> Result<StateView<'_>, StateViewError> {
        const STATE_VIEW_LOG_THRESHOLD: Duration = Duration::from_millis(10);
        let caller = core::panic::Location::caller();
        let total_start = Instant::now();
        {
            // Every production visibility interval is enclosed by this original
            // State writer. Observe before sampling so even an early unlock is retained.
            let generation_release = self.state_write_lock.observe_release();
            let generation_before = self.state_view_generation();
            if !generation_before.is_multiple_of(2) {
                return Err(StateViewError::Busy(generation_release));
            }
            let block_hashes_start = Instant::now();
            let block_hashes = self.block_hashes.try_view_retaining(&mut releases.hashes)?;
            let block_hashes_wait = block_hashes_start.elapsed();
            let latest_hash = block_hashes.last().copied();
            let cached_header = releases.header.try_read_or_wait()?.clone();

            let nexus_start = Instant::now();
            let canonical_runtime = self.canonical_runtime.view();
            let canonical_runtime_predecessor = self.canonical_runtime.predecessor_view();
            let native_execution_tip = self.native_execution_tip.view();
            let native_execution_tip_predecessor = self.native_execution_tip.predecessor_view();
            let nexus_wait = nexus_start.elapsed();
            let world_start = Instant::now();
            let mut world = self.world.try_view_retaining(&mut releases.world)?;
            let baseline = releases.manifests.try_read_or_wait()?.clone();
            let projection = Self::project_canonical_runtime_from_inputs(
                canonical_runtime.get(),
                &world,
                &baseline,
                &*releases.nexus.try_read_or_wait()?,
            );
            let world_wait = world_start.elapsed();
            let transactions_start = Instant::now();
            let transactions = self
                .transactions
                .try_view_retaining(&mut releases.membership)?;
            let transactions_wait = transactions_start.elapsed();
            let commit_topology_start = Instant::now();
            let commit_topology = self.commit_topology.view();
            let commit_topology_wait = commit_topology_start.elapsed();
            let prev_commit_topology_start = Instant::now();
            let prev_commit_topology = self.prev_commit_topology.view();
            let prev_commit_topology_wait = prev_commit_topology_start.elapsed();
            let pipeline_ivm_prepared_cache = releases.prepared_cache.try_read_or_wait()?.clone();
            let crypto = releases.crypto.try_read_or_wait()?.clone();
            let query_ledger_time_ms = cached_header
                .as_ref()
                .filter(|header| Some(header.hash()) == latest_hash)
                .map(|header| u64::try_from(header.creation_time().as_millis()).unwrap_or(u64::MAX))
                .or_else(|| {
                    let tip = (*native_execution_tip.get())?;
                    (Some(tip.iroha_hash()) == latest_hash
                        && usize::try_from(tip.height()).ok() == Some(block_hashes.len()))
                    .then_some(tip.creation_time_ms())
                });
            let generation_after = self.state_view_generation();
            if !is_stable_state_view_generation(generation_before, generation_after) {
                drop(prev_commit_topology);
                drop(commit_topology);
                drop(transactions);
                drop(world);
                return Err(StateViewError::Busy(generation_release));
            }
            let projection = projection?;
            let canonical_runtime::CanonicalRuntimeProjection {
                nexus,
                incarnations: lane_incarnations,
                activation_heights: lane_incarnation_activation_heights,
                lineage: _,
                samples: _,
                manifests: lane_manifests,
                privacy: _,
            } = projection;
            world.dataspace_catalog = nexus.dataspace_catalog.clone();
            let total_wait = total_start.elapsed();
            let (mut max_component, mut max_wait) = ("block_hashes", block_hashes_wait);
            if world_wait > max_wait {
                max_component = "world";
                max_wait = world_wait;
            }
            if transactions_wait > max_wait {
                max_component = "transactions";
                max_wait = transactions_wait;
            }
            if commit_topology_wait > max_wait {
                max_component = "commit_topology";
                max_wait = commit_topology_wait;
            }
            if prev_commit_topology_wait > max_wait {
                max_component = "prev_commit_topology";
                max_wait = prev_commit_topology_wait;
            }
            if nexus_wait > max_wait {
                max_component = "nexus";
                max_wait = nexus_wait;
            }
            if max_wait >= STATE_VIEW_LOG_THRESHOLD {
                debug!(
                    caller = %caller,
                    max_component,
                    max_wait_us = max_wait.as_micros(),
                    total_wait_us = total_wait.as_micros(),
                    block_hashes_wait_us = block_hashes_wait.as_micros(),
                    world_wait_us = world_wait.as_micros(),
                    transactions_wait_us = transactions_wait.as_micros(),
                    commit_topology_wait_us = commit_topology_wait.as_micros(),
                    prev_commit_topology_wait_us = prev_commit_topology_wait.as_micros(),
                    nexus_wait_us = nexus_wait.as_micros(),
                    state_view_generation = generation_after,
                    "state view acquisition slow or retried"
                );
            }
            let zk = crate::zk_validity_policy::effective_zk(self.zk.clone(), world.parameters());
            let pipeline = crate::pipeline_validity_policy::effective_pipeline(
                self.pipeline.clone(),
                world.parameters.get(),
            );
            let fraud_monitoring = crate::fraud_admission_policy::effective_fraud(
                self.fraud_monitoring.clone(),
                world.parameters.get(),
            );
            return Ok(StateView {
                publication_generation: generation_after,
                canonical_runtime,
                canonical_runtime_predecessor,
                native_execution_tip,
                native_execution_tip_predecessor,
                world,
                block_hashes,
                transactions,
                commit_topology,
                prev_commit_topology,
                ivm: &self.ivm,
                pipeline_ivm_prepared_cache,
                da_receipt_cursors: &self.da_receipt_cursors,
                da_shard_cursors: &self.da_shard_cursors,
                kura: &self.kura,
                query_handle: &self.query_handle,
                query_ledger_time_ms,
                accounts_snapshot_cache: SyncOnceCell::new(),
                #[cfg(feature = "telemetry")]
                telemetry: &self.telemetry,
                pipeline,
                oracle: self.oracle.clone(),
                crypto,
                nexus,
                lane_incarnations,
                lane_incarnation_activation_heights,
                lane_manifests,
                fraud_monitoring,
                zk,
                gov: self.gov.clone(),
                content: self.content.clone(),
                settlement: self.settlement,
                settlement_engine: self.settlement_engine.clone(),
                chain_id: self.chain_id.clone(),
                network_id: self.network_id,
                created_at: Instant::now(),
            });
        }
    }
    fn prune_lane_lifecycle_world_block_state_for_lanes(
        world: &mut WorldBlock<'_>,
        lanes_to_reset: &BTreeSet<LaneId>,
    ) {
        if lanes_to_reset.is_empty() {
            return;
        }
        Self::prune_da_pin_intent_world_block_indexes_for_lanes(world, lanes_to_reset);
        let stale_public_lane_stake_share_keys = Self::public_lane_stake_share_keys_for_lanes(
            &world.public_lane_stake_shares,
            lanes_to_reset,
        );
        for key in stale_public_lane_stake_share_keys {
            world.public_lane_stake_shares.remove(key);
        }
    }
    fn da_pin_intent_index_prune_keys_for_lanes(
        by_ticket: &impl StorageReadOnly<StorageTicketId, DaPinIntentWithLocation>,
        by_alias: &impl StorageReadOnly<String, StorageTicketId>,
        by_manifest: &impl StorageReadOnly<ManifestDigest, StorageTicketId>,
        by_lane_epoch: &impl StorageReadOnly<(LaneId, u64, u64), StorageTicketId>,
        lanes_to_reset: &BTreeSet<LaneId>,
    ) -> DaPinIntentIndexPruneKeys {
        if lanes_to_reset.is_empty() {
            return DaPinIntentIndexPruneKeys::default();
        }
        let mut keys = DaPinIntentIndexPruneKeys::default();
        for (ticket, record) in by_ticket.iter() {
            if lanes_to_reset.contains(&record.intent.lane_id) {
                keys.tickets.insert(*ticket);
            }
        }
        for (lane_epoch_key, ticket) in by_lane_epoch.iter() {
            if lanes_to_reset.contains(&lane_epoch_key.0) {
                keys.tickets.insert(*ticket);
            }
        }
        for (alias, ticket) in by_alias.iter() {
            if keys.tickets.contains(ticket) {
                keys.aliases.insert(alias.clone());
            }
        }
        for (manifest, ticket) in by_manifest.iter() {
            if keys.tickets.contains(ticket) {
                keys.manifests.insert(*manifest);
            }
        }
        for (lane_epoch_key, ticket) in by_lane_epoch.iter() {
            if lanes_to_reset.contains(&lane_epoch_key.0) || keys.tickets.contains(ticket) {
                keys.lane_epochs.insert(*lane_epoch_key);
            }
        }
        keys
    }
    fn prune_da_pin_intent_world_indexes_for_lanes(&self, lanes_to_reset: &BTreeSet<LaneId>) {
        let stale_keys = {
            let by_ticket = self.world.da_pin_intents_by_ticket.view();
            let by_alias = self.world.da_pin_intents_by_alias.view();
            let by_manifest = self.world.da_pin_intents_by_manifest.view();
            let by_lane_epoch = self.world.da_pin_intents_by_lane_epoch.view();
            Self::da_pin_intent_index_prune_keys_for_lanes(
                &by_ticket,
                &by_alias,
                &by_manifest,
                &by_lane_epoch,
                lanes_to_reset,
            )
        };
        if stale_keys.is_empty() {
            return;
        }
        if !stale_keys.aliases.is_empty() {
            let mut tx = self.world.da_pin_intents_by_alias.block();
            for alias in stale_keys.aliases {
                tx.remove(alias);
            }
            tx.commit();
        }
        if !stale_keys.manifests.is_empty() {
            let mut tx = self.world.da_pin_intents_by_manifest.block();
            for manifest in stale_keys.manifests {
                tx.remove(manifest);
            }
            tx.commit();
        }
        if !stale_keys.lane_epochs.is_empty() {
            let mut tx = self.world.da_pin_intents_by_lane_epoch.block();
            for lane_epoch_key in stale_keys.lane_epochs {
                tx.remove(lane_epoch_key);
            }
            tx.commit();
        }
        if !stale_keys.tickets.is_empty() {
            let mut tx = self.world.da_pin_intents_by_ticket.block();
            for ticket in stale_keys.tickets {
                tx.remove(ticket);
            }
            tx.commit();
        }
    }
    fn prune_da_pin_intent_world_block_indexes_for_lanes(
        world: &mut WorldBlock<'_>,
        lanes_to_reset: &BTreeSet<LaneId>,
    ) {
        let stale_keys = Self::da_pin_intent_index_prune_keys_for_lanes(
            &world.da_pin_intents_by_ticket,
            &world.da_pin_intents_by_alias,
            &world.da_pin_intents_by_manifest,
            &world.da_pin_intents_by_lane_epoch,
            lanes_to_reset,
        );
        if stale_keys.is_empty() {
            return;
        }
        for alias in stale_keys.aliases {
            world.da_pin_intents_by_alias.remove(alias);
        }
        for manifest in stale_keys.manifests {
            world.da_pin_intents_by_manifest.remove(manifest);
        }
        for lane_epoch_key in stale_keys.lane_epochs {
            world.da_pin_intents_by_lane_epoch.remove(lane_epoch_key);
        }
        for ticket in stale_keys.tickets {
            world.da_pin_intents_by_ticket.remove(ticket);
        }
    }
    fn public_lane_stake_share_keys_for_lanes(
        stake_shares: &impl StorageReadOnly<(LaneId, AccountId, AccountId), PublicLaneStakeShare>,
        lanes_to_reset: &BTreeSet<LaneId>,
    ) -> Vec<(LaneId, AccountId, AccountId)> {
        if lanes_to_reset.is_empty() {
            return Vec::new();
        }
        stake_shares
            .iter()
            .filter(|&(key, record)| {
                lanes_to_reset.contains(&key.0) || lanes_to_reset.contains(&record.lane_id)
            })
            .map(|(key, _record)| key.clone())
            .collect()
    }
    fn prune_public_lane_economic_state_for_lanes(&self, lanes_to_reset: &BTreeSet<LaneId>) {
        if lanes_to_reset.is_empty() {
            return;
        }
        let stale_stake_share_keys = {
            let stake_shares = self.world.public_lane_stake_shares.view();
            Self::public_lane_stake_share_keys_for_lanes(&stake_shares, lanes_to_reset)
        };
        if !stale_stake_share_keys.is_empty() {
            let mut tx = self.world.public_lane_stake_shares.block();
            for key in stale_stake_share_keys {
                tx.remove(key);
            }
            tx.commit();
        }
    }
    fn reset_lane_scoped_runtime_state(
        &self,
        lanes_to_reset: &BTreeSet<LaneId>,
        publish_process_runtime: bool,
        releases: &mut LaneLifecycleReleases<'_>,
    ) {
        if lanes_to_reset.is_empty() {
            return;
        }
        self.reset_lane_scoped_runtime_indexes(lanes_to_reset, releases);
        if publish_process_runtime {
            self.publish_lane_scoped_runtime_reset(lanes_to_reset);
            if releases.hydrated.read().is_some() {
                self.persist_lane_lifecycle_cursor_journal(releases);
            }
        }
    }
    fn reset_lane_scoped_runtime_indexes(
        &self,
        lanes_to_reset: &BTreeSet<LaneId>,
        releases: &mut LaneLifecycleReleases<'_>,
    ) {
        if lanes_to_reset.is_empty() {
            return;
        }
        releases.commitments.write().prune_lanes(lanes_to_reset);
        releases
            .confidential_compute
            .write()
            .prune_lanes(lanes_to_reset);
        releases.pin_intents.write().prune_lanes(lanes_to_reset);
        releases.receipt_cursors.write().prune_lanes(lanes_to_reset);
        {
            let mut cursors = releases.shard_cursors.write();
            cursors.prune_lanes(lanes_to_reset);
        }
    }
    fn publish_lane_scoped_runtime_reset(&self, lanes_to_reset: &BTreeSet<LaneId>) {
        if lanes_to_reset.is_empty() {
            return;
        }
        #[cfg(feature = "telemetry")]
        self.telemetry
            .prune_da_receipt_lanes(lanes_to_reset.iter().map(|lane| lane.as_u32()));
        crate::status::prune_lane_scoped_snapshots(lanes_to_reset);
        crate::status::reset_public_lane_staking_lanes(lanes_to_reset);
    }
    /// Install the empty provisional registry exactly once before emergency Fast
    /// snapshot authentication. This path cannot import manifest authority.
    ///
    /// # Errors
    /// Refuses Strict startup, a repeat call, or an already authenticated snapshot State.
    pub fn install_provisional_empty_lane_manifests_for_emergency_fast_pre_auth(
        &mut self,
    ) -> Result<(), LaneLifecycleError> {
        if !self.kura.emergency_fast_startup_enabled()
            || self.provisional_emergency_lane_manifests_consumed
        {
            return Err(runtime_catalog_invalid(
                "provisional emergency lane manifests require the one-shot pre-authentication phase",
            ));
        }
        self.provisional_emergency_lane_manifests_consumed = true;
        self.install_unchecked_lane_manifests_in_publication(&Arc::new(
            LaneManifestRegistry::provisional_empty_for_emergency_fast_startup(),
        ));
        Ok(())
    }
    /// Install an arbitrary registry for isolated tests and fixture generation.
    /// This method is absent from ordinary shipping binaries.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    pub fn install_lane_manifests_for_testing(&self, manifests: &LaneManifestRegistryHandle) {
        self.install_unchecked_lane_manifests_in_publication(manifests);
    }
    fn install_unchecked_lane_manifests_in_publication(
        &self,
        manifests: &LaneManifestRegistryHandle,
    ) {
        let privacy = Arc::new(LanePrivacyRegistry::from_manifest_registry(manifests));
        let manifests = Arc::clone(manifests);
        let mut publication_notice = self.state_view_publication();
        let mut releases = LaneLifecycleReleases::new(self);
        let mut state_write_release = self.state_write_lock.defer_notifications();
        let _state_write_lock = state_write_release.lock();
        let publication = publication_notice.begin();
        self.install_prepared_lane_manifests_in_publication(
            manifests,
            privacy,
            &publication,
            &mut releases,
        );
    }
    /// Publish manifest and privacy projections inside one existing State generation.
    fn install_prepared_lane_manifests_in_publication(
        &self,
        manifests: LaneManifestRegistryHandle,
        privacy: LanePrivacyRegistryHandle,
        _publication: &StateViewGenerationWriteGuard<'_>,
        releases: &mut LaneLifecycleReleases<'_>,
    ) {
        {
            let mut guard = releases.manifests.write();
            *guard = manifests;
            #[cfg(test)]
            lifecycle_index_publication::after_manifest_write_for_test();
        }
        let mut privacy_guard = releases.privacy.write();
        *privacy_guard = privacy;
    }
    /// Install the lane compliance engine snapshot (consensus-critical when configured).
    pub fn install_lane_compliance_engine(&self, engine: Option<Arc<LaneComplianceEngine>>) {
        let mut guard = self.lane_compliance.write();
        *guard = engine;
    }
    /// Snapshot the currently configured lane compliance engine.
    pub fn lane_compliance_engine(&self) -> Option<Arc<LaneComplianceEngine>> {
        self.lane_compliance.read().clone()
    }
    fn lane_authority_inputs(
        &self,
        lane_id: LaneId,
        block_height: u64,
    ) -> Option<ResolvedLaneAuthorityInputs> {
        let nexus = self.nexus_snapshot();
        let validator_mode = nexus.staking.validator_mode(lane_id, &nexus.lane_catalog);
        lane_authority::inputs_from_nexus(lane_id, validator_mode, &nexus, block_height)
    }
    /// Resolve the authoritative validator accounts for a lane from manifests or staking state.
    #[cfg(test)]
    pub fn authoritative_lane_validator_accounts(&self, lane_id: LaneId) -> Vec<AccountId> {
        let block_height = self.lane_authority_height();
        let Some(inputs) = self.lane_authority_inputs(lane_id, block_height) else {
            return Vec::new();
        };
        let manifest_registry = self.lane_manifests.read().clone();
        lane_authority::validator_accounts_with_inputs(
            &self.world.view(),
            lane_id,
            manifest_registry.as_ref(),
            &inputs,
            block_height,
        )
    }
    /// Resolve the exact current-height `3f+1` authority for a lane/dataspace route.
    ///
    /// The returned height and committee come from one immutable state view so
    /// status and proxy callers cannot decorate a committee with data read
    /// across a concurrent commit boundary.
    ///
    /// # Errors
    /// Returns an error for an unknown or inactive route, inconsistent authority
    /// or committee geometry, unavailable selection entropy, an undersized pool,
    /// or failed canonical peer encoding.
    pub fn resolve_lane_committee(
        &self,
        route: LaneAuthorityRoute,
    ) -> Result<LaneAuthorityCommittee, LaneAuthorityError> {
        let view = self.view();
        let authority_height = u64::try_from(view.height()).unwrap_or(u64::MAX);
        StateReadOnly::resolve_lane_committee_at_height(&view, route, authority_height)
    }
    /// Resolve the exact `3f+1` authority for a lane/dataspace route at an
    /// explicit consensus height.
    ///
    /// # Errors
    /// Returns an error for a route inactive at `authority_height`, an unknown
    /// dataspace, inconsistent authority or committee geometry, unavailable selection
    /// entropy, an undersized pool, or failed canonical peer encoding.
    pub fn resolve_lane_committee_at_height(
        &self,
        route: LaneAuthorityRoute,
        authority_height: u64,
    ) -> Result<LaneAuthorityCommittee, LaneAuthorityError> {
        let view = self.view();
        StateReadOnly::resolve_lane_committee_at_height(&view, route, authority_height)
    }
    /// Resolve the peers authoritative for a route at the committed height: the global
    /// committee (lanes and dataspaces are routing labels; every transaction executes in the
    /// global Sumeragi block). Torii routes and proxies requests by this authority.
    ///
    /// # Errors
    /// The route is unknown or inactive, or no validator is live.
    pub fn resolve_route_authority(
        &self,
        route: LaneAuthorityRoute,
    ) -> Result<LaneAuthorityCommittee, LaneAuthorityError> {
        let view = self.view();
        let authority_height = u64::try_from(view.height()).unwrap_or(u64::MAX);
        lane_authority::resolve_global_route(view.world(), route, view.nexus(), authority_height)
    }
    /// [`Self::resolve_route_authority`] at an explicit consensus height.
    ///
    /// # Errors
    /// The route is unknown or inactive at `authority_height`, or no validator is live there.
    pub fn resolve_route_authority_at_height(
        &self,
        route: LaneAuthorityRoute,
        authority_height: u64,
    ) -> Result<LaneAuthorityCommittee, LaneAuthorityError> {
        let view = self.view();
        lane_authority::resolve_global_route(view.world(), route, view.nexus(), authority_height)
    }
    /// Return whether a lane is active at the committed lane-authority height.
    pub fn is_lane_active_for_authority(&self, lane_id: LaneId) -> bool {
        let nexus = self.nexus_snapshot();
        consensus_lane_dataspace_at_height(lane_id, &nexus, self.lane_authority_height()).is_some()
    }
    /// Resolve the only lane allowed to own staking storage at the committed authority height.
    #[cfg(test)]
    pub(crate) fn staking_authority_lane(&self, lane_id: LaneId) -> Option<LaneId> {
        let nexus = self.nexus_snapshot();
        nexus_staking_authority_lane_at_height(lane_id, &nexus, self.lane_authority_height())
    }
    fn lane_authority_height(&self) -> u64 {
        self.latest_block_header_fast()
            .map(|header| header.height().get())
            .unwrap_or_else(|| {
                self.world
                    .view()
                    .consensus_keys()
                    .iter()
                    .map(|(_, record)| record.activation_height)
                    .max()
                    .unwrap_or(0)
            })
    }
    /// Return live explicit manifest validator bindings configured for a lane, if any.
    pub fn manifest_lane_validator_bindings(
        &self,
        lane_id: LaneId,
    ) -> Vec<ManifestValidatorBinding> {
        let block_height = self.lane_authority_height();
        self.manifest_lane_validator_bindings_at_height(lane_id, block_height)
    }
    /// Return explicit manifest validator bindings live at an exact authority height.
    ///
    /// This is used by proposal-bound transports so a validator whose consensus key activates at
    /// the next height can be reached without substituting the current committee.
    pub fn manifest_lane_validator_bindings_at_height(
        &self,
        lane_id: LaneId,
        block_height: u64,
    ) -> Vec<ManifestValidatorBinding> {
        let Some(inputs) = self.lane_authority_inputs(lane_id, block_height) else {
            return Vec::new();
        };
        let lane_manifests = self.lane_manifests.read().clone();
        let Ok(Some(rules)) =
            lane_authority::manifest_rules_for_lane(lane_id, lane_manifests.as_ref(), &inputs)
        else {
            return Vec::new();
        };
        let world = self.world.view();
        bounded_authority::live_manifest_validator_bindings(
            &world,
            lane_id,
            &rules.validator_bindings,
            &rules.validators,
            block_height,
        )
    }
    #[cfg(test)]
    fn lane_relay_committee_seed(
        &self,
        dataspace_id: DataSpaceId,
        lane_id: LaneId,
        block_height: u64,
    ) -> [u8; 32] {
        let world_view = self.world.view();
        match Self::lane_relay_committee_seed_from_sources(
            &world_view,
            &self.network_id,
            dataspace_id,
            lane_id,
            block_height,
        ) {
            Ok(seed) => seed,
            Err(_)
                if world_view
                    .global_beacon_key_sessions()
                    .iter()
                    .next()
                    .is_none()
                    && world_view
                        .global_beacon_active_session()
                        .iter()
                        .next()
                        .is_none()
                    && world_view.global_beacon_pulses().iter().next().is_none()
                    && world_view
                        .global_beacon_latest_pulse()
                        .iter()
                        .next()
                        .is_none() =>
            {
                Self::lane_relay_committee_seed_for_fixture(
                    &self.network_id,
                    dataspace_id,
                    lane_id,
                    block_height,
                )
            }
            Err(error) => panic!("lane relay fixture requires a valid beacon: {error}"),
        }
    }
    fn lane_relay_committee_seed_from_sources(
        world: &impl WorldReadOnly,
        network_id: &iroha_data_model::NetworkId,
        dataspace_id: DataSpaceId,
        lane_id: LaneId,
        block_height: u64,
    ) -> Result<[u8; 32], crate::beacon::GlobalThresholdBeaconError> {
        let pulse = crate::beacon::verified_latest_global_threshold_beacon_pulse_v1(
            world,
            network_id,
            block_height.saturating_sub(1),
        )?;
        Ok(crate::beacon::global_threshold_beacon_lane_relay_seed_v1(
            &pulse,
            block_height,
            dataspace_id.as_u64(),
            lane_id.as_u32(),
        ))
    }
    #[cfg(test)]
    fn lane_relay_committee_seed_for_fixture(
        network_id: &iroha_data_model::NetworkId,
        dataspace_id: DataSpaceId,
        lane_id: LaneId,
        block_height: u64,
    ) -> [u8; 32] {
        // Unit fixtures that exercise lane authority independently of beacon
        // persistence use explicit synthetic entropy. This helper is never an
        // error recovery path for partially populated or invalid beacon state.
        const TEST_ENTROPY_DOMAIN: &[u8] = b"iroha:lane-relay:test-entropy:v1";
        let fixture_entropy = Hash::new_from_chunks(&[
            TEST_ENTROPY_DOMAIN,
            network_id.as_bytes(),
            block_height.to_be_bytes().as_slice(),
        ]);
        let mut buffer = Vec::with_capacity(
            LANE_RELAY_SEED_DOMAIN.len()
                + Hash::LENGTH
                + core::mem::size_of::<u64>()
                + core::mem::size_of::<u32>(),
        );
        buffer.extend_from_slice(LANE_RELAY_SEED_DOMAIN);
        buffer.extend_from_slice(fixture_entropy.as_ref());
        buffer.extend_from_slice(&dataspace_id.as_u64().to_le_bytes());
        buffer.extend_from_slice(&lane_id.as_u32().to_le_bytes());
        Hash::new(buffer).into()
    }
    fn lane_relay_committee_from_pool(
        pool: &[PeerId],
        committee_size: usize,
        seed: [u8; 32],
    ) -> Result<Vec<PeerId>, norito::Error> {
        let mut scored = Vec::with_capacity(pool.len());
        for peer in pool {
            let mut buffer = Vec::with_capacity(LANE_RELAY_MEMBER_DOMAIN.len() + seed.len());
            buffer.extend_from_slice(LANE_RELAY_MEMBER_DOMAIN);
            buffer.extend_from_slice(&seed);
            // Committee order is consensus-significant, so ambient Norito
            // layout guards must never alter this ranking preimage.
            let encoded = norito::encode_canonical(peer)?;
            buffer.extend_from_slice(&encoded);
            scored.push((Hash::new(buffer), peer.clone()));
        }
        scored.sort_by(|lhs, rhs| lhs.0.cmp(&rhs.0).then_with(|| lhs.1.cmp(&rhs.1)));
        scored.dedup_by(|lhs, rhs| lhs.1 == rhs.1);
        Ok(scored
            .into_iter()
            .take(committee_size)
            .map(|(_, peer)| peer)
            .collect())
    }
