    /// Derive the initial committee for a brand-new autoscale lane incarnation.
    ///
    /// This is the only path allowed to consult mutable manifests, stake, and
    /// peer/key liveness. The returned authority is persisted in the
    /// lane metadata before the incarnation and catalog commitments are
    /// derived; all later authority resolution reads that pin instead.
    #[cfg(test)]
    fn derive_new_autoscale_lane_committee_from_sources(
        world: &impl WorldReadOnly,
        network_id: &iroha_data_model::NetworkId,
        lane_id: LaneId,
        manifest_registry: &LaneManifestRegistry,
        nexus: &iroha_config::parameters::actual::Nexus,
        proposal_height: u64,
    ) -> Vec<PeerId> {
        let Some(lane) = nexus
            .lane_catalog
            .lanes()
            .iter()
            .find(|lane| lane.id == lane_id)
        else {
            return Vec::new();
        };
        if !nexus.autoscale.enabled
            || !lane_claims_autoscale_managed(lane)
            || lane.visibility != iroha_data_model::nexus::LaneVisibility::Public
            || lane.alias != format!("elastic-lane-{}", lane.id.as_u32())
            || lane
                .autoscale_created_height()
                .is_none_or(|height| height > proposal_height)
            || lane.dataspace_id != nexus.routing_policy.default_dataspace
            || ensure_autoscale_managed_lane_in_range(
                lane.id,
                nexus.autoscale.min_lane_id.get(),
                nexus.autoscale.max_lane_id_exclusive.get(),
            )
            .is_err()
            || ensure_autoscale_managed_lane_inherits_default_profile(lane, nexus).is_err()
        {
            return Vec::new();
        }
        let dataspace_id = lane.dataspace_id;
        let exact_manifest_rules = match manifest_registry.status(lane_id) {
            Some(status) if status.dataspace != dataspace_id => return Vec::new(),
            Some(status) => {
                if manifest_registry.ensure_lane_ready(lane_id).is_err() {
                    return Vec::new();
                }
                status.rules().filter(|rules| !rules.validators.is_empty())
            }
            None => None,
        };
        let manifest_rules = if exact_manifest_rules.is_some() {
            exact_manifest_rules
        } else {
            let eligible_lanes = nexus
                .lane_catalog
                .lanes()
                .iter()
                .filter(|candidate| !lane_uses_reserved_autoscale_metadata(candidate))
                .filter(|candidate| {
                    nexus_active_lane_dataspace_at_height(candidate.id, nexus, proposal_height)
                        == Some(dataspace_id)
                })
                .map(|candidate| candidate.id)
                .collect();
            match manifest_registry.dataspace_authority_rules_for_lanes(
                lane_id,
                dataspace_id,
                &eligible_lanes,
            ) {
                Ok(rules) => rules,
                Err(_) => return Vec::new(),
            }
        };
        if let Some(rules) = manifest_rules {
            if !rules.validator_bindings.is_empty() {
                let pool = bounded_authority::live_manifest_validator_bindings(
                    world,
                    lane_id,
                    &rules.validator_bindings,
                    &rules.validators,
                    proposal_height,
                )
                .into_iter()
                .map(|binding| binding.peer_id)
                .collect::<Vec<_>>();
                return Self::autoscale_lane_committee_from_pool(
                    world,
                    network_id,
                    lane_id,
                    dataspace_id,
                    nexus,
                    &pool,
                    proposal_height,
                );
            }
            let pool = bounded_authority::live_manifest_validator_account_peers(
                world,
                lane_id,
                &rules.validators,
                proposal_height,
            )
            .into_iter()
            .map(|(_, peer)| peer)
            .collect::<Vec<_>>();
            return Self::autoscale_lane_committee_from_pool(
                world,
                network_id,
                lane_id,
                dataspace_id,
                nexus,
                &pool,
                proposal_height,
            );
        }

        let stake_source_lanes: BTreeSet<_> = nexus
            .lane_catalog
            .lanes()
            .iter()
            .filter(|candidate| !lane_uses_reserved_autoscale_metadata(candidate))
            .filter(|candidate| {
                nexus_active_lane_dataspace_at_height(candidate.id, nexus, proposal_height)
                    == Some(dataspace_id)
            })
            .filter(|candidate| {
                matches!(
                    nexus
                        .staking
                        .validator_mode(candidate.id, &nexus.lane_catalog),
                    iroha_config::parameters::actual::LaneValidatorMode::StakeElected
                )
            })
            .map(|candidate| candidate.id)
            .collect();
        let canonical_owner = stake_source_lanes.iter().next().copied();
        let Some(stake_candidates) = lane_authority::live_stake_candidates_for_lanes(
            world,
            lane_id,
            &stake_source_lanes,
            canonical_owner,
            &nexus.staking.min_validator_stake,
            nexus.staking.max_validators.get(),
            proposal_height,
        ) else {
            return Vec::new();
        };
        if !stake_candidates.is_empty() {
            let pool = lane_authority::ranked_stake_peer_pool(stake_candidates);
            return Self::autoscale_lane_committee_from_pool(
                world,
                network_id,
                lane_id,
                dataspace_id,
                nexus,
                &pool,
                proposal_height,
            );
        }
        Vec::new()
    }
    #[cfg(test)]
    fn pin_new_autoscale_lane_committee_from_sources(
        world: &impl WorldReadOnly,
        network_id: &iroha_data_model::NetworkId,
        manifest_registry: &LaneManifestRegistry,
        nexus: &iroha_config::parameters::actual::Nexus,
        lane: &mut iroha_data_model::nexus::LaneConfig,
        proposal_height: u64,
    ) -> Result<(), LaneLifecycleError> {
        lane.metadata.remove(AUTOSCALE_META_COMMITTEE);
        let mut prospective_nexus = nexus.clone();
        prospective_nexus.lane_catalog = prospective_nexus.lane_catalog.apply_lifecycle(
            &iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![lane.clone()],
                retire: Vec::new(),
            },
        )?;
        prospective_nexus.lane_config = iroha_config::parameters::actual::LaneConfig::from_catalog(
            &prospective_nexus.lane_catalog,
        );
        let required = nexus_lane_committee_size(&prospective_nexus, lane.dataspace_id).ok_or(
            LaneLifecycleError::AutoscaleCommitteeSizeInvalid {
                lane: lane.id,
                dataspace: lane.dataspace_id,
            },
        )?;
        let validator_set = Self::derive_new_autoscale_lane_committee_from_sources(
            world,
            network_id,
            lane.id,
            manifest_registry,
            &prospective_nexus,
            proposal_height,
        );
        if validator_set.len() != required {
            return Err(LaneLifecycleError::AutoscaleCommitteeUnavailable {
                lane: lane.id,
                dataspace: lane.dataspace_id,
                required,
                actual: validator_set.len(),
            });
        }
        let validator_pops = validator_set
            .iter()
            .map(|peer| {
                live_consensus_key_pop_for_peer_on_lane(
                    world,
                    peer,
                    proposal_height,
                    lane.id,
                )
                .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: lane.id,
                    reason: "pinned committee member lacks a live durable BLS proof-of-possession",
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        let committee = autoscale_lane_committee_from_validator_set(validator_set, validator_pops)?;
        lane.metadata.insert(
            AUTOSCALE_META_COMMITTEE.to_owned(),
            encode_autoscale_lane_committee(&committee)?,
        );
        Ok(())
    }
    #[cfg(test)]
    fn autoscale_lane_committee_from_pool(
        world: &impl WorldReadOnly,
        network_id: &iroha_data_model::NetworkId,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        nexus: &iroha_config::parameters::actual::Nexus,
        pool: &[PeerId],
        block_height: u64,
    ) -> Vec<PeerId> {
        let Some(committee_size) = nexus_lane_committee_size(nexus, dataspace_id) else {
            return Vec::new();
        };
        if pool.len() < committee_size {
            return Vec::new();
        }
        // An exact pool has only one possible committee. Its canonical ordering
        // needs no entropy; a larger pool still requires a verified beacon to
        // choose members consistently with relay authority.
        if pool.len() == committee_size {
            let mut committee = pool.to_vec();
            committee.sort();
            committee.dedup();
            return if committee.len() == committee_size {
                committee
            } else {
                Vec::new()
            };
        }
        // Reuse the relay seed and member ranking so lane-block descriptors and
        // later relay verification cannot derive different committee membership.
        let Ok(seed) = Self::lane_relay_committee_seed_from_sources(
            world,
            network_id,
            dataspace_id,
            lane_id,
            block_height,
        ) else {
            return Vec::new();
        };
        let Ok(mut committee) = Self::lane_relay_committee_from_pool(pool, committee_size, seed)
        else {
            return Vec::new();
        };
        if committee.len() != committee_size {
            return Vec::new();
        }
        committee.sort();
        committee
    }
