#[cfg(test)]
mod state_view_lock_tests {
    use super::*;
    use crate::kura::Kura;
    use std::{
        cell::Cell,
        sync::{Arc, mpsc},
        thread,
        time::Duration,
    };
    #[test]
    fn state_view_waits_for_active_view_generation() {
        let kura = Kura::blank_kura_for_testing();
        let query = crate::query::store::LiveQueryStore::start_test();
        let state = Arc::new(State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            query,
        ));
        let view_state = Arc::clone(&state);
        let mut _generation_guard_notice = state.state_view_publication();
        let _generation_guard = _generation_guard_notice.begin();
        let (done_tx, done_rx) = mpsc::channel();
        let handle = thread::spawn(move || {
            let view = view_state.view();
            done_tx
                .send(view.world().peers().is_empty())
                .expect("send view result");
        });
        assert!(
            done_rx.recv_timeout(Duration::from_millis(50)).is_err(),
            "state view returned while a writer generation was active"
        );
        drop(_generation_guard);
        drop(_generation_guard_notice);
        assert!(
            done_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("view should complete after generation guard drops"),
            "state view should expose the committed empty peer set"
        );
        handle.join().expect("view thread");
    }
    #[test]
    fn diagnostic_projection_retries_after_state_generation_change() {
        let kura = Kura::blank_kura_for_testing();
        let query = crate::query::store::LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query);
        let initial_generation = state.state_view_generation();
        let attempts = Cell::new(0_u32);
        let observed = state
            .derive_diagnostics_at_stable_state_generation(
                || {
                    let attempt = attempts.get().saturating_add(1);
                    attempts.set(attempt);
                    if attempt == 1 {
                        let mut generation_guard_notice = state.state_view_publication();
                        let generation_guard = generation_guard_notice.begin();
                        drop(generation_guard);
                        drop(generation_guard_notice);
                    }
                    Ok::<u32, &'static str>(attempt)
                },
                || "one generation retry did not converge",
            )
            .expect("infallible diagnostic projection");
        assert_eq!(
            observed, 2,
            "the mixed-generation observation must be discarded"
        );
        assert_eq!(attempts.get(), 2);
        assert_eq!(state.state_view_generation(), initial_generation + 2);
    }
    #[test]
    fn diagnostic_projection_fails_closed_after_bounded_generation_drift() {
        let kura = Kura::blank_kura_for_testing();
        let query = crate::query::store::LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query);
        let attempts = Cell::new(0_usize);
        let result = state.derive_diagnostics_at_stable_state_generation(
            || {
                attempts.set(attempts.get().saturating_add(1));
                let mut generation_guard_notice = state.state_view_publication();
                let generation_guard = generation_guard_notice.begin();
                drop(generation_guard);
                drop(generation_guard_notice);
                Ok::<(), &'static str>(())
            },
            || "diagnostic State generation did not stabilize",
        );
        assert_eq!(result, Err("diagnostic State generation did not stabilize"));
        assert_eq!(
            attempts.get(),
            DIAGNOSTIC_STABLE_STATE_GENERATION_ATTEMPTS,
            "the diagnostic scan must stop at its fixed retry budget"
        );
    }
}
