#[cfg(test)]
mod committed_transaction_context_tests {
    use super::*;
    use crate::{kura::Kura, query::store::LiveQueryStore};
    use iroha_data_model::{isi::Log, transaction::TransactionBuilder};
    use iroha_test_samples::{ALICE_ID, ALICE_KEYPAIR};
    #[test]
    fn committed_transaction_context_uses_canonical_entrypoint_metadata() {
        let state = State::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let header = BlockHeader::new(core::num::NonZeroU64::MIN, None, None, 0, 0);
        let mut state_block = state.block(header);
        let mut transaction = state_block.transaction();
        let signed = TransactionBuilder::new(
            state.network_id,
            ALICE_ID.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([Log::new(iroha_logger::Level::INFO, "context".into())])
        .sign(ALICE_KEYPAIR.private_key());
        let entrypoint = TransactionEntrypoint::External(signed.clone());
        crate::state::seed_committed_transaction_context(&mut transaction, &entrypoint, 7);
        assert_eq!(
            transaction.tx_call_hash,
            Some(iroha_crypto::Hash::from(signed.hash_as_entrypoint()))
        );
        assert_eq!(
            transaction.current_tx_hash,
            Some(crate::tx::AcceptedTransaction::prepare_signed_metadata(&signed).signed_hash)
        );
        assert_eq!(transaction.current_entrypoint_index, Some(7));
    }

    #[test]
    fn committed_transaction_context_binds_exact_standalone_governance_ballot() {
        let state = State::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let header = BlockHeader::new(core::num::NonZeroU64::MIN, None, None, 0, 0);
        let mut state_block = state.block(header);
        let mut transaction = state_block.transaction();
        let ballot = InstructionBox::from(iroha_data_model::isi::governance::CastZkBallot {
            election_id: "committed.replay.v1".to_owned(),
            proof_b64: "AA==".to_owned(),
            public_inputs_json: "{}".to_owned(),
        });
        let signed = TransactionBuilder::new(
            state.network_id,
            ALICE_ID.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([ballot.clone()])
        .sign(ALICE_KEYPAIR.private_key());
        let entrypoint = TransactionEntrypoint::External(signed);

        crate::state::seed_committed_transaction_context(&mut transaction, &entrypoint, 3);

        transaction
            .consume_governance_ballot_entrypoint_v1(&ballot)
            .expect("committed replay must bind the exact standalone ballot");
        assert_eq!(
            transaction.consume_governance_ballot_entrypoint_v1(&ballot),
            Err(GovernanceBallotEntrypointConsumptionErrorV1::AlreadyConsumed)
        );
    }
    #[test]
    fn signed_conviction_update_cannot_be_substituted_with_a_second_cast() {
        use iroha_data_model::isi::governance::{CastPlainBallot, UpdatePlainConviction};
        let state = State::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let header = BlockHeader::new(core::num::NonZeroU64::MIN, None, None, 0, 0);
        let mut state_block = state.block(header);
        let mut transaction = state_block.transaction();
        let update = InstructionBox::from(UpdatePlainConviction {
            referendum_id: "committed-plain".to_owned(),
            owner: ALICE_ID.clone(),
            amount: 2_u64.into(),
            duration_blocks: 200,
        });
        let cast = InstructionBox::from(CastPlainBallot {
            referendum_id: "committed-plain".to_owned(),
            owner: ALICE_ID.clone(),
            amount: 2_u64.into(),
            duration_blocks: 200,
            direction: 0,
        });
        let signed = TransactionBuilder::new(
            state.network_id,
            ALICE_ID.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([update.clone()])
        .sign(ALICE_KEYPAIR.private_key());
        let entrypoint = TransactionEntrypoint::External(signed);
        crate::state::seed_committed_transaction_context(&mut transaction, &entrypoint, 3);
        assert_eq!(
            transaction.consume_governance_ballot_entrypoint_v1(&cast),
            Err(GovernanceBallotEntrypointConsumptionErrorV1::InstructionMismatch)
        );
        transaction
            .consume_governance_ballot_entrypoint_v1(&update)
            .expect("the exact signed conviction update is the sole direct entrypoint");
    }
}
