    /// Register a confidential proof verification, enforcing per-transaction and per-block quotas.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] if any confidential proof quota would be exceeded or counters overflow.
    pub fn register_confidential_proof(&mut self, proof_bytes: usize) -> Result<(), Error> {
        self.register_confidential_usage(proof_bytes, 1)
    }
    /// Reserve all native proof verification work for one KAGEMUSHA package.
    ///
    /// The actual package selects one sigma verification plus one Omega verification
    /// when lineage is carried. Both fixed-width accumulator originals are included
    /// in the lineage transport byte count. One package remains one confidential
    /// operation, and all existing transaction/block/aggregate-byte ceilings apply.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] without changing accounting when any byte/count arithmetic
    /// overflows or a confidential quota refuses the whole reservation. The existing
    /// output owner retains completed-work accounting after later business rollback.
    pub(crate) fn register_kagemusha_package_proof(
        &mut self,
        package: &iroha_data_model::kagemusha::KagemushaWalletPackageV1,
    ) -> Result<(), Error> {
        let lineage = package.lineage.lineage();
        let proof_bytes = package
            .step_proof
            .bytes
            .len()
            .checked_add(lineage.map_or(0, |value| value.proof.len()))
            .ok_or_else(|| {
                Error::InvariantViolation("KAGEMUSHA package proof-byte count overflow".into())
            })?;
        let verify_calls = if lineage.is_some() { 2 } else { 1 };
        self.register_confidential_usage(proof_bytes, verify_calls)
    }
    /// Return the exact index required by the next privacy proof in this transaction.
    #[must_use]
    pub(crate) const fn next_privacy_action_index(&self) -> u32 {
        self.privacy_actions_in_tx
    }
    /// Install the exact direct privacy submission derived from a new signed payload.
    ///
    /// Passing `None` explicitly clears any previous transaction's binding. This
    /// reset belongs at signed-transaction admission boundaries; child contract,
    /// trigger, and IVM execution must never call it.
    pub(crate) fn bind_privacy_transaction_intent_v1(
        &mut self,
        binding: Option<(
            iroha_data_model::privacy::PrivacyTransactionIntentDigestV1,
            Hash,
        )>,
    ) {
        self.privacy_transaction_intent_binding = binding.map(|(digest, submission_hash)| {
            PrivacyTransactionIntentBindingV1::new(digest, submission_hash)
        });
    }
    /// Install the exact direct private-settlement carrier derived from a signed payload.
    ///
    /// Passing `None` clears the prior transaction's binding. Nested execution
    /// paths must never install or reset this value.
    pub(crate) fn bind_private_settlement_carrier_v1(
        &mut self,
        binding: Option<PrivateSettlementCarrierBindingV1>,
    ) {
        self.private_settlement_carrier_binding = binding;
    }
    /// Install the exact standalone governance ballot derived from a signed payload.
    ///
    /// Passing `None` clears the binding. Nested execution paths must never install
    /// or reset it.
    pub(crate) fn bind_governance_ballot_entrypoint_v1(
        &mut self,
        instruction: Option<iroha_data_model::isi::InstructionBox>,
    ) {
        self.governance_ballot_entrypoint_binding =
            instruction.map(|instruction| GovernanceBallotEntrypointBindingV1 {
                instruction,
                consumed: false,
            });
    }
    /// Consume the exact signed standalone governance ballot once.
    pub(crate) fn consume_governance_ballot_entrypoint_v1(
        &mut self,
        actual: &iroha_data_model::isi::InstructionBox,
    ) -> core::result::Result<(), GovernanceBallotEntrypointConsumptionErrorV1> {
        let binding = self
            .governance_ballot_entrypoint_binding
            .as_mut()
            .ok_or(GovernanceBallotEntrypointConsumptionErrorV1::MissingBinding)?;
        if binding.instruction != *actual {
            return Err(GovernanceBallotEntrypointConsumptionErrorV1::InstructionMismatch);
        }
        if binding.consumed {
            return Err(GovernanceBallotEntrypointConsumptionErrorV1::AlreadyConsumed);
        }
        binding.consumed = true;
        Ok(())
    }
    /// Stage a prevalidated ballot penalty for replay if this overlay is rejected.
    pub(crate) fn defer_governance_ballot_penalty_v1(
        &mut self,
        penalty: DeferredGovernanceBallotPenaltyV1,
    ) {
        self.deferred_governance_ballot_penalties.push(penalty);
    }
    /// Take every ballot penalty that must outlive rejection of this overlay.
    pub(crate) fn take_deferred_governance_ballot_penalties_v1(
        &mut self,
    ) -> Vec<DeferredGovernanceBallotPenaltyV1> {
        core::mem::take(&mut self.deferred_governance_ballot_penalties)
    }
    /// Consume the exact signed private-settlement carrier once.
    pub(crate) fn consume_private_settlement_carrier_binding_v1(
        &mut self,
        payload_digest: Hash,
        instruction_digest: Hash,
    ) -> core::result::Result<(), PrivateSettlementCarrierBindingErrorV1> {
        let max_signed_transaction_bytes =
            self.nexus.atomic_private_settlement.max_carrier_bytes.get();
        self.private_settlement_carrier_binding
            .as_mut()
            .ok_or(PrivateSettlementCarrierBindingErrorV1::MissingBinding)?
            .consume(
                payload_digest,
                instruction_digest,
                max_signed_transaction_bytes,
            )
    }
    /// Consume the exact signed direct privacy submission once.
    ///
    /// Validation is completed before flipping the one-shot bit, so a missing,
    /// stale, or dynamically substituted instruction cannot poison the binding.
    /// A later verifier failure still rolls the bit back because it lives only in
    /// this transaction overlay.
    ///
    /// # Errors
    ///
    /// Returns a closed failure when the binding is missing, stale, substituted,
    /// or already consumed.
    pub(crate) fn consume_privacy_transaction_intent_v1(
        &mut self,
        actual_digest: iroha_data_model::privacy::PrivacyTransactionIntentDigestV1,
        actual_submission_hash: Hash,
    ) -> Result<(), PrivacyTransactionIntentConsumptionErrorV1> {
        let binding = self
            .privacy_transaction_intent_binding
            .as_mut()
            .ok_or(PrivacyTransactionIntentConsumptionErrorV1::MissingBinding)?;
        if binding.digest != actual_digest {
            return Err(PrivacyTransactionIntentConsumptionErrorV1::DigestMismatch);
        }
        if binding.submission_hash != actual_submission_hash {
            return Err(PrivacyTransactionIntentConsumptionErrorV1::SubmissionMismatch);
        }
        if binding.consumed {
            return Err(PrivacyTransactionIntentConsumptionErrorV1::AlreadyConsumed);
        }
        binding.consumed = true;
        Ok(())
    }
    /// Check whether one canonical privacy action can be reserved without
    /// changing transaction or block accounting.
    ///
    /// Runtime handlers call this before invoking a native verifier so an
    /// already-exhausted consensus budget cannot trigger expensive
    /// cryptography.  [`Self::reserve_privacy_action`] delegates to the same
    /// validator, preventing preflight and final reservation from drifting.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] under the same conditions as
    /// [`Self::reserve_privacy_action`].
    pub(crate) fn preflight_privacy_action(
        &self,
        action_index: u32,
        encoded_action_bytes: u64,
    ) -> Result<(), Error> {
        self.validate_privacy_action_reservation(action_index, encoded_action_bytes)
            .map(|_| ())
    }
    /// Reserve one SCCP verifier call's `work` under the `[zk.sccp]` limits before the verifier
    /// runs (`specs/sccp.md` §4.12.1 step 5).
    ///
    /// Like privacy actions, the reservation is staged in this transaction and reaches the
    /// parent block only through [`Self::apply`].
    ///
    /// # Errors
    ///
    /// Returns the name of the first `[zk.sccp]` limit the call, the transaction or the block
    /// would exceed, without reserving anything.
    pub(crate) fn reserve_sccp_verifier_work(
        &mut self,
        work: &iroha_sccp::light_client::SccpVerifierWorkV1,
    ) -> Result<(), &'static str> {
        const OVERFLOW: &str = "verifier work counters";
        let in_tx = self
            .sccp_verifier_work_in_tx
            .checked_add(work)
            .ok_or(OVERFLOW)?;
        let after_block = self
            .sccp_verifier_work_after_block
            .checked_add(work)
            .ok_or(OVERFLOW)?;
        if let Some(limit) =
            crate::smartcontracts::isi::sccp::light_clients::exceeded_verifier_limit(
                &self.zk.sccp,
                work,
                &in_tx,
                &after_block,
            )
        {
            return Err(limit);
        }
        self.sccp_verifier_work_in_tx = in_tx;
        self.sccp_verifier_work_after_block = after_block;
        Ok(())
    }
    /// Reserve one canonically encoded first-release privacy action.
    ///
    /// The reservation is staged in this transaction. The parent block budget
    /// is updated only by [`Self::apply`], so dropping a transaction after any
    /// later instruction failure rolls the charge back together with its world
    /// writes.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] without changing transaction or block accounting when
    /// the action index is duplicated/skipped, a counter overflows, or any
    /// compiled transaction/block action or byte limit would be exceeded.
    pub(crate) fn reserve_privacy_action(
        &mut self,
        action_index: u32,
        encoded_action_bytes: u64,
    ) -> Result<(), Error> {
        let (next_actions, next_bytes, next_block_budget) =
            self.validate_privacy_action_reservation(action_index, encoded_action_bytes)?;
        self.privacy_actions_in_tx = next_actions;
        self.privacy_bytes_in_tx = next_bytes;
        self.privacy_budget_after_block = next_block_budget;
        Ok(())
    }
    fn validate_privacy_action_reservation(
        &self,
        action_index: u32,
        encoded_action_bytes: u64,
    ) -> Result<(u32, u64, crate::privacy::PrivacyBlockBudgetV1), Error> {
        if action_index != self.privacy_actions_in_tx {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    format!(
                        "privacy action index mismatch: expected {}, got {action_index}",
                        self.privacy_actions_in_tx
                    )
                    .into(),
                ),
            ));
        }
        let limits = *self.privacy_budget_after_block.limits();
        let next_actions = self
            .privacy_actions_in_tx
            .checked_add(1)
            .ok_or_else(|| Error::InvariantViolation("privacy action counter overflow".into()))?;
        if next_actions > limits.max_actions_per_transaction {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "privacy action count per transaction exceeded".into(),
                ),
            ));
        }
        let next_bytes = self
            .privacy_bytes_in_tx
            .checked_add(encoded_action_bytes)
            .ok_or_else(|| Error::InvariantViolation("privacy byte counter overflow".into()))?;
        if next_bytes > u64::from(limits.max_privacy_bytes_per_transaction) {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "privacy bytes per transaction exceeded".into(),
                ),
            ));
        }
        let mut next_block_budget = self.privacy_budget_after_block;
        let mut reservation = next_block_budget.begin_transaction();
        reservation
            .reserve(0, encoded_action_bytes)
            .map_err(|error| {
                Error::InvalidParameter(InvalidParameterError::SmartContract(
                    format!("privacy admission budget rejected action: {error}").into(),
                ))
            })?;
        reservation.commit();
        Ok((next_actions, next_bytes, next_block_budget))
    }
    #[cfg(test)]
    pub(crate) fn privacy_budget_for_testing(&self) -> (u32, u64, u32, u64) {
        (
            self.privacy_actions_in_tx,
            self.privacy_bytes_in_tx,
            self.privacy_budget_after_block.actions(),
            self.privacy_budget_after_block.bytes(),
        )
    }

    #[cfg(test)]
    /// Return the number of transfer transcripts staged by this transaction.
    pub(crate) fn pending_transfer_transcript_count_for_testing(&self) -> usize {
        self.pending_transfer_transcripts.len()
    }
    /// Internal helper to account confidential usage while enforcing quotas.
    fn confidential_usage_after(
        &self,
        proof_bytes: usize,
        verify_calls: u32,
    ) -> Result<(u32, u32, u64), Error> {
        if verify_calls == 0 && proof_bytes == 0 {
            return Ok((
                self.zk_confidential_ops_in_tx,
                self.zk_verify_calls_in_tx,
                self.zk_proof_bytes_in_tx,
            ));
        }
        let cfg = &self.zk;
        if cfg.max_proof_size_bytes > 0
            && proof_bytes > usize::try_from(cfg.max_proof_size_bytes).unwrap_or(usize::MAX)
        {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential proof exceeds max_proof_size_bytes".into(),
                ),
            ));
        }
        let tx_ops_after = self
            .zk_confidential_ops_in_tx
            .checked_add(1)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential operation counter overflow".into())
            })?;
        let tx_calls_after = self
            .zk_verify_calls_in_tx
            .checked_add(verify_calls)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential verify-call counter overflow".into())
            })?;
        if cfg.max_verify_calls_per_tx > 0 && tx_calls_after > cfg.max_verify_calls_per_tx {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential verify calls per transaction exceeded".into(),
                ),
            ));
        }
        let block_calls_after = self
            .zk_verify_calls_in_block_so_far
            .checked_add(tx_calls_after)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential verify-call block counter overflow".into())
            })?;
        if cfg.max_verify_calls_per_block > 0 && block_calls_after > cfg.max_verify_calls_per_block
        {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential verify calls per block exceeded".into(),
                ),
            ));
        }
        let block_ops_after = self
            .zk_confidential_ops_in_block_so_far
            .checked_add(tx_ops_after)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential operation block counter overflow".into())
            })?;
        if cfg.max_confidential_ops_per_block > 0
            && block_ops_after > cfg.max_confidential_ops_per_block
        {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential operations per block exceeded".into(),
                ),
            ));
        }
        let proof_bytes_u64 = u64::try_from(proof_bytes).map_err(|_| {
            Error::InvalidParameter(InvalidParameterError::SmartContract(
                "confidential proof size exceeds supported bounds".into(),
            ))
        })?;
        let tx_proof_bytes_after = self
            .zk_proof_bytes_in_tx
            .checked_add(proof_bytes_u64)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential proof-bytes counter overflow".into())
            })?;
        let block_proof_bytes_after = self
            .zk_proof_bytes_in_block_so_far
            .checked_add(tx_proof_bytes_after)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential proof-bytes block overflow".into())
            })?;
        if cfg.max_proof_bytes_block > 0 && block_proof_bytes_after > cfg.max_proof_bytes_block {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential proof bytes per block exceeded".into(),
                ),
            ));
        }
        Ok((tx_ops_after, tx_calls_after, tx_proof_bytes_after))
    }
    /// Enforce the existing proof quota before verification without publishing counters.
    pub(crate) fn check_confidential_proof(&self, proof_bytes: usize) -> Result<(), Error> {
        self.confidential_usage_after(proof_bytes, 1).map(|_| ())
    }
    /// Publish completed proof work after validating the same quota arithmetic.
    fn register_confidential_usage(
        &mut self,
        proof_bytes: usize,
        verify_calls: u32,
    ) -> Result<(), Error> {
        let (ops, calls, bytes) = self.confidential_usage_after(proof_bytes, verify_calls)?;
        self.zk_confidential_ops_in_tx = ops;
        self.zk_verify_calls_in_tx = calls;
        self.zk_proof_bytes_in_tx = bytes;
        Ok(())
    }
    /// Track additional confidential nullifiers consumed within the transaction.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] if the nullifier count overflows or violates configured limits.
    pub fn register_nullifiers(&mut self, count: usize) -> Result<(), Error> {
        if count == 0 {
            return Ok(());
        }
        let count_u32 = u32::try_from(count).map_err(|_| {
            Error::InvalidParameter(InvalidParameterError::SmartContract(
                "nullifier count exceeds supported bounds".into(),
            ))
        })?;
        let total_after = self
            .zk_nullifiers_in_tx
            .checked_add(count_u32)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential nullifier counter overflow".into())
            })?;
        if self.zk.max_nullifiers_per_tx > 0 && total_after > self.zk.max_nullifiers_per_tx {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "nullifiers per transaction cap exceeded".into(),
                ),
            ));
        }
        self.zk_nullifiers_in_tx = total_after;
        Ok(())
    }
    /// Track additional confidential commitments created within the transaction.
    ///
    /// # Errors
    ///
    /// Returns [`Error`] if the commitment count overflows or violates configured limits.
    pub fn register_commitments(&mut self, count: usize) -> Result<(), Error> {
        if count == 0 {
            return Ok(());
        }
        let count_u32 = u32::try_from(count).map_err(|_| {
            Error::InvalidParameter(InvalidParameterError::SmartContract(
                "commitment count exceeds supported bounds".into(),
            ))
        })?;
        let total_after = self
            .zk_commitments_in_tx
            .checked_add(count_u32)
            .ok_or_else(|| {
                Error::InvariantViolation("confidential commitment counter overflow".into())
            })?;
        if self.zk.max_commitments_per_tx > 0 && total_after > self.zk.max_commitments_per_tx {
            return Err(Error::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "commitments per transaction cap exceeded".into(),
                ),
            ));
        }
        self.zk_commitments_in_tx = total_after;
        Ok(())
    }
    /// Track confidential gas usage for this transaction.
    pub fn record_confidential_gas_delta(&mut self, delta: u64) {
        if delta == 0 {
            return;
        }
        self.confidential_gas_used_in_tx = self.confidential_gas_used_in_tx.saturating_add(delta);
        #[cfg(feature = "telemetry")]
        let block_total = self
            .confidential_gas_used_in_block_so_far
            .saturating_add(self.confidential_gas_used_in_tx);
        #[cfg(feature = "telemetry")]
        {
            self.telemetry
                .set_confidential_gas_usage(self.confidential_gas_used_in_tx, block_total);
        }
    }
    /// Require the deterministic identity used by transfer transcripts before balance mutation.
