/// Prior committed policy needed to interpret lane activity and staking ownership.
///
/// Startup must compare the configured policy with this authenticated projection,
/// never with the placeholder defaults used for other process-local Nexus fields.
#[derive(
    Clone,
    Debug,
    PartialEq,
    Eq,
    JsonSerialize,
    JsonDeserialize,
    Encode,
    Decode,
    norito::NoritoSchema,
)]
#[norito_schema(name = "iroha_core::state::SnapshotNexusOwnerPolicy")]
pub(crate) struct SnapshotNexusOwnerPolicy {
    pub dataspaces: Vec<SnapshotDataSpaceMetadata>,
    pub public_validator_mode: SnapshotLaneValidatorMode,
    pub restricted_validator_mode: SnapshotLaneValidatorMode,
    pub max_validators: u32,
    pub routing_default_lane: LaneId,
    pub routing_default_dataspace: DataSpaceId,
    pub autoscale_enabled: bool,
    pub autoscale_min_lane_id: u32,
    pub autoscale_max_lane_id_exclusive: u32,
}
impl SnapshotNexusOwnerPolicy {
    fn from_nexus(nexus: &iroha_config::parameters::actual::Nexus) -> Self {
        Self {
            dataspaces: nexus
                .dataspace_catalog
                .entries()
                .iter()
                .map(|entry| SnapshotDataSpaceMetadata {
                    id: entry.id,
                    alias: entry.alias.clone(),
                    fault_tolerance: entry.fault_tolerance,
                })
                .collect(),
            public_validator_mode: nexus.staking.public_validator_mode.into(),
            restricted_validator_mode: nexus.staking.restricted_validator_mode.into(),
            max_validators: nexus.staking.max_validators.get(),
            routing_default_lane: nexus.routing_policy.default_lane,
            routing_default_dataspace: nexus.routing_policy.default_dataspace,
            autoscale_enabled: nexus.autoscale.enabled,
            autoscale_min_lane_id: nexus.autoscale.min_lane_id.get(),
            autoscale_max_lane_id_exclusive: nexus.autoscale.max_lane_id_exclusive.get(),
        }
    }
}
/// Versioned, consensus-relevant Nexus runtime state persisted with WSV snapshots.
///
/// Local configuration supplies the requested static policy at startup. Its prior
/// ownership projection is retained so reconciliation can reject an actual owner
/// change without mistaking missing configuration for a committed transition.
/// Lifecycle operations and canonical blocks also mutate the effective catalog,
/// autoscale cooldown cursor, and canonical autoscale sample window after startup.
#[derive(Clone, Debug, PartialEq, Eq, JsonSerialize, JsonDeserialize)]
pub(crate) struct SnapshotNexusRuntime {
    /// First-release MV runtime record layout version.
    pub version: u8,
    /// Exact prior policy used to resolve lane activity and staking ownership.
    pub owner_policy: SnapshotNexusOwnerPolicy,
    /// Valid lane identifier namespace size.
    pub lane_count: u32,
    /// Effective lane catalog at the snapshot height.
    pub lanes: Vec<iroha_data_model::nexus::LaneConfig>,
    /// Latest incarnation lineage for every active or retired lane id ever observed.
    pub lane_incarnation_lineage: Vec<SnapshotLaneIncarnationLineage>,
    /// Last committed block height that changed autoscale topology.
    pub autoscale_last_transition_height: u64,
    /// Scale-out sample window used to derive the retained-history cap.
    pub autoscale_scale_out_window_blocks: u16,
    /// Scale-in sample window used to derive the retained-history cap.
    pub autoscale_scale_in_window_blocks: u16,
    /// Configured maximum number of retained autoscale records at snapshot time.
    pub autoscale_sample_history_cap: u32,
    /// Canonical suffix used to reconstruct autoscale windows without Kura bodies.
    pub autoscale_sample_history: Vec<AutoscaleSampleRecord>,
}
impl SnapshotNexusRuntime {
    /// Current first-release persisted-State layout generation.
    ///
    /// The mandatory MV current/undo envelope is part of this layout. Retired
    /// record-only runtime snapshots and unwrapped present undo values are
    /// rejected, never upgraded implicitly. A present-null original is distinct
    /// from absence; this layout generation includes that explicit value frame.
    pub(crate) const VERSION: u8 = 6;
    /// Capture the stateful Nexus fields from a consistent state view.
    #[cfg(test)]
    pub(crate) fn from_nexus(
        nexus: &iroha_config::parameters::actual::Nexus,
        lane_incarnations: &BTreeMap<LaneId, Hash>,
        lane_incarnation_activation_heights: &BTreeMap<LaneId, u64>,
        lane_incarnation_lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
    ) -> Self {
        Self::from_nexus_with_autoscale_history(
            nexus,
            lane_incarnations,
            lane_incarnation_activation_heights,
            &VecDeque::new(),
            lane_incarnation_lineage,
        )
    }
    /// Capture Nexus state together with its canonical autoscale sample suffix.
    pub(crate) fn from_nexus_with_autoscale_history(
        nexus: &iroha_config::parameters::actual::Nexus,
        lane_incarnations: &BTreeMap<LaneId, Hash>,
        lane_incarnation_activation_heights: &BTreeMap<LaneId, u64>,
        autoscale_sample_history: &VecDeque<AutoscaleSampleRecord>,
        lane_incarnation_lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
    ) -> Self {
        debug_assert!(
            validate_lane_incarnation_map(&nexus.lane_catalog, lane_incarnations).is_ok()
        );
        debug_assert!(
            validate_lane_incarnation_activation_heights(
                &nexus.lane_catalog,
                lane_incarnation_activation_heights,
            )
            .is_ok()
        );
        let autoscale_sample_history_cap = autoscale_sample_history_cap(&nexus.autoscale);
        debug_assert!(autoscale_sample_history.len() <= autoscale_sample_history_cap);
        debug_assert!(
            validate_lane_incarnation_lineage(
                &nexus.lane_catalog,
                lane_incarnations,
                lane_incarnation_activation_heights,
                lane_incarnation_lineage,
            )
            .is_ok()
        );
        Self {
            version: Self::VERSION,
            owner_policy: SnapshotNexusOwnerPolicy::from_nexus(nexus),
            lane_count: nexus.lane_catalog.lane_count().get(),
            lanes: nexus.lane_catalog.lanes().to_vec(),
            lane_incarnation_lineage: lane_incarnation_lineage
                .iter()
                .map(|(&lane_id, entry)| SnapshotLaneIncarnationLineage {
                    lane_id,
                    generation: entry.generation,
                    incarnation: entry.incarnation,
                    activation_height: entry.activation_height,
                })
                .collect(),
            autoscale_last_transition_height: nexus.autoscale.last_transition_height,
            autoscale_scale_out_window_blocks: nexus.autoscale.scale_out_window_blocks.get(),
            autoscale_scale_in_window_blocks: nexus.autoscale.scale_in_window_blocks.get(),
            autoscale_sample_history_cap: u32::try_from(autoscale_sample_history_cap)
                .expect("autoscale history cap fits u32"),
            autoscale_sample_history: autoscale_sample_history.iter().copied().collect(),
        }
    }
}
